(window.GIM_TS=window.GIM_TS||{})["Beitzah.1"]={"from":24,"a":[["\u0003מקשרי אצבעותיו ולמעלה\u0004 כלומר אינו מניח את השבלים בכף היד אלא על גבי האצבעות, שהוא דרך שינוי.","\u0003מחכו עלה במערבא\u0004 \u0005[היו צוחקים על\u0006 הלכה \u0005זו בארץ ישראל]\u0006 והיו אומרים: \u0003כיון דמשני\u0004 \u0005[שהוא משנה]\u0006 מדרך עשייתם בחול — \u0003אפילו בכולה ידא נמי\u0004 \u0005[בכל היד גם כן]\u0006 מותר. \u0003אלא\u0004 הלכה כפי ש\u0003אמר ר' אלעזר: מנפח בידו אחת\u0004 ולא בשתים, ויכול לעשות זאת אפילו \u0003בכל כחו,\u0004 ואין חוששים משום מלאכה.","\u0003בית שמאי אומרים: תבלין נדוכין\u0004 ביום טוב בשינוי מה, וכגון \u0003במדוך של עץ. והמלח\u0004 נידוך רק \u0003בפך\u0004 של חרס \u0003ובעץ הפרור\u0004 (ידית של כף המבשלים) לעשות בכך שינוי רב. \u0003ובית הלל אומרים: תבלין נדוכין כדרכן\u0004 אפילו \u0003במדוך של אבן, והמלח\u0004 אינו נידוך אלא בשינוי, אולם די בשינוי מה והריהו נידוך \u0003במדוך של עץ.\u0004","\u0003דכולי עלמא מיהת\u0004 \u0005[על כל פנים לדעת הכל],\u0006 בין לבית שמאי ובין לבית הלל, דיכת \u0003מלח בעיא\u0004 \u0005[צריכה]\u0006 \u0003שנוי,\u0004 ואין עושים אותה כדרכה בחול, \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 נחלקו בכך \u0003רב הונא ורב חסדא; חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 הכל יודעים כי \u0003כל הקדרות\u0004 (תבשילים) \u0003כולן צריכות מלח,\u0004 והיה לו להכינו עוד מבעוד יום, ומשלא הכינו, שוב אינו יכול לעשות כן ביום טוב עצמו אלא בשינוי, אולם \u0003אין כל הקדרות צריכות תבלין\u0004 ויתכן שלא ידע מבעוד יום שיצטרך לתבלין.","\u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר\u0004 טעם אחר: \u0003כל התבלין מפיגים טעמן\u0004 ואינו יכול להכינם מבעוד יום, \u0003ומלח אינה מפיגה טעמה\u0004 ולכן היה יכול להכין את המלח מבעוד יום, ומשלא הכינו, שוב אינו יכול להכינו בחג אלא בשינוי.","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם]\u0006 הלכה למעשה, אם זה או זה הטעם? ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל כגון ש\u0003ידע\u0004 מראש \u0003מאי קדרה בעי לבשולי\u0004 \u0005[איזה\u0006 מין \u0005תבשיל רוצה\u0006 הוא \u0005לבשל],\u0006 ויודע איזה תבלין יצטרך והיה לו להכינו מבעוד יום ואם לא הכינו, אינו יכול להכינו ביום טוב אלא בשינוי, \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 \u0003במוריקא\u0004 \u0005[בכרכום]\u0006 שאין טעמו נפוג במשך יום אחד, ויכול היה להכינו מבעוד יום.","\u0003אמר רב יהודה אמר שמואל: כל הנדוכין\u0004 דברים שצריך לדוך אותם לצורך אכילה \u0003נדוכין כדרכן, ואפילו מלח.\u0004 ומקשים: \u0003והא אמרת\u0004 \u0005[והרי אמרת]\u0006 \u0003מלח בעיא\u0004 \u0005[צריך]\u0006 \u0003שנוי\u0004 בהכנתו לדעת הכל! ומשיבים: \u0003הוא\u0004 ש\u0003אמר\u0004 הלכה זו \u0003כי האי תנא\u0004 \u0005[כדעת תנא זה],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר ר' מאיר: לא נחלקו בית שמאי ובית הלל על הנדוכין שנדוכין כדרכן ומלח עמהן,\u0004","\u0003לא נחלקו אלא לדוכה\u0004 את המלח \u0003בפני עצמה, שבית שמאי אומרים: מלח\u0004 דכים \u0003בפך ובעץ הפרור ל\u0004צורך \u0003צלי,\u0004 כלומר כמות קטנה, שאין הצלי צריך הרבה מלח, \u0003אבל לא\u0004 בכמות מרובה כדי מליחת בשר \u0003לקדרה. ובית הלל אומרים: בכל דבר.\u0004 ותוהים: \u0003בכל דבר סלקא דעתך\u0004 \u0005[עולה על דעתך]\u0006 לומר שיוכלו לדוכו בכל דרך שהיא? והרי אמרנו שאין עושים כן אלא בשינוי! \u0003אלא אימא\u0004 \u0005[אמור]:\u0006 \u0003לכל דבר.\u0004 כלומר, בין לצלי בין לקדירה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא ברדלא לבריה\u0004 \u0005[לבנו]:\u0006 \u0003כי דייכת\u0004 \u0005[כאשר אתה דך\u0006 מלח\u0005]\u0006 \u0003— אצלי אצלויי\u0004 \u0005[הטה אותו על הצד\u0006 קצת\u0005]\u0006 \u0003ודוך,\u0004 שתעשה בו על כל פנים שינוי מעט ביום טוב. וכיוצא בו מסופר: \u0003רב ששת שמע\u0004 ביום טוב \u0003קל בוכנא\u0004 \u0005[\u0006את \u0005קול המדוך]\u0006 הדך מלח, \u0003אמר\u0004 בלבו: \u0003האי לאו מגוויה דביתאי\u0004 \u0005[\u0006קול \u0005זה אינו מתוך ביתי]\u0006 \u0003הוא,\u0004 שהוריתי לבני ביתי שלא לעשות כן.","ושואלים: \u0003ודלמא אצלויי אצלי\u0004 \u0005[ושמא הטו אותו\u0006 ודכו\u0005]\u0006 בהיתר גמור? ומשיבים: \u0003דשמעיה דהוה צליל קליה\u0004 \u0005[ששמע\u0006 אותו \u0005שהיה קולו צלול]\u0006 וכשדכים על הצד לא נשמע קול צלול. ושואלים: \u0003ודלמא תבלין הוו\u0004 \u0005[ושמא תבלים היו],\u0006 שאותם מותר לדוך ביום טוב כדרכם? ומשיבים: \u0003תבלין נבוחי מנבח קלייהו\u0004 \u0005[נשמע קולם כנביחה],\u0006 שכשהם נדוכים יש קול מיוחד בדיכתם, ואפשר להבחין בו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אין עושים\u0004 ביום טוב \u0003טיסני\u0004 מין גריסים שעושים מגרגרי החיטה שכותשים אותם עד שנחלקים לארבע חתיכות, ויש במלאכה זו טירחה רבה, \u0003ואין כותשין במכתשת.\u0004 ותוהים: \u0003תרתי\u0004 \u0005[שתים]?!\u0006 שני דברים סותרים כאחד? שהרי תחילה אמר שאין עושים טיסני בלבד, שהיא מלאכה קשה, ואחר כך אסר כל כתישה במכתשת! ומשיבים, \u0003הכי קאמר\u0004 \u0005[כך אמר],\u0006 כלומר, כך יש לתקן את לשון הברייתא: \u0003מה טעם אין עושין טיסני\u0004 — \u0003לפי שאין כותשין במכתשת.\u0004 ושואלים שוב ולשם מה הוצרך לומר שני דברים?","\u0003ולימא\u0004 \u0005[ושיאמר]:\u0006 \u0003אין כותשין במכתשת\u0004 וממילא נבין שאין עושים טיסני! ומשיבים: \u0003אי תנא\u0004 \u0005[אם היה שונה]\u0006 רק \u0003אין כותשין במכתשת — הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 דווקא \u0003במכתשת גדולה\u0004 שהעבודה בה נראית כמלאכת חול, \u0003אבל במכתשת קטנה אימא שפיר דמי\u0004 \u0005[אמור שיפה,\u0006 שטוב, \u0005הדבר]\u0006 ויכול לעשות אף טיסני, \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין לעשות טיסני בכל דרך שהיא.","ומקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא במפורש\u0005]:\u0006 \u0003אין כותשין במכתשת גדולה, אבל כותשין במכתשת קטנה! אמר אביי:\u0004 עלינו לפרש \u0003כי תניא נמי מתניתא\u0004 \u0005[כאשר שנויה גם כן הברייתא]\u0006 האוסרת לכתוש — ב\u0003מכתשת גדולה תניא\u0004 \u0005[שנויה\u0006 היא\u0005]\u0006 ולא לגבי קטנה. והלכה שניה נאמרה בברייתא, שאין עושים טיסני אפילו במכתשת קטנה."],["\u0003רבא אמר: לא קשיא\u0004 \u0005[אינו קשה]\u0006 ואין סתירה בין הברייתות, \u0003הא\u0004 \u0005[זו]\u0006 שמתירה במכתשת קטנה, מדברת \u0003לן\u0004 \u0005[בנו]\u0006 שאין לנו עבדים, \u0003והא להו\u0004 \u0005[וזו להם,\u0006 לבני ארץ ישראל\u0005]\u0006 שמרובים שם עבדים, וכיון שחששו שמא יזלזלו באיסורים ויכתשו במכתשת הגדולה שמלאכתה אסורה ויאמרו שכתשו בקטנה שהיא מותרת — לכך אסרו עליהם כל כתישה.","מסופר: \u0003רב פפי אקלע לבי\u0004 \u0005[הזדמן לביתו]\u0006 של \u0003מר שמואל,\u0004 ממשפחת ראש הגולה. \u0003אייתי ליה\u0004 \u0005[הביאו לו]\u0006 \u0003דייסא\u0004 העשויה מגריסי חיטה \u0003ולא אכל,\u0004 מתוך החשש שמא כתשו את החיטים בו ביום\u0003.\u0004 ושואלים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 \u0003במכתשת קטנה עבדוה\u0004 \u0005[עשו אותה]\u0006 ובהיתר? ומשיבים: \u0003דחזייה דהוה דייק טפי\u0004 \u0005[שראה שהיתה טחונה יפה]\u0006 ודבר זה אי אפשר לעשותו במכתשת קטנה.","ושואלים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 \u0003מאתמול,\u0004 מערב יום טוב, \u0003עבדוה\u0004 \u0005[עשו אותה]?\u0006 ומשיבים: \u0003דחזייה דהוה קליף צהריה\u0004 \u0005[שראה שקילופו היה בהיר],\u0006 שזה סימן שלא שהה זמן רב. \u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 שלא מטעם זה נמנע, אלא מחשש מעיקר הדבר כי \u0003שאני בי\u0004 \u0005[שונה ביתו]\u0006 של \u0003מר שמואל דאיכא פריצותא דעבדי\u0004 \u0005[שיש\u0006 בו \u0005פריצות של עבדים],\u0006 שהיו עבדיו מזלזלים באיסורים ולכך היו צריכים לאסור שם כל כתישה, כדי שלא יבואו לזלזל באיסורי יום טוב.","\u0003הבורר קטניות ביום טוב. בית שמאי אומרים: בורר אוכל\u0004 (את החלק הנאכל) מתוך הפסולת \u0003ואוכל\u0004 מיד. \u0003ובית הלל אומרים: בורר כדרכו בחיקו\u0004 או \u0003בקנון\u0004 (כלי העשוי כעין משפך) או \u0003בתמחוי\u0004 (קערה גדולה), \u0003אבל לא\u0004 יברור \u0003בטבלא ולא בנפה ולא בכברה\u0004 שהם כלים המיוחדים לברירה, ונראה הדבר כמלאכה של חול. \u0003רבן גמליאל אומר: אף מדיח\u0004 את הקטניות במים \u0003ושולה\u0004 את הפסולת הצפה על פניהם.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר רבן גמליאל: במה דברים אמורים\u0004 שהתירו בית הלל להוציא פסולת כדרך ברירה בחול — \u0003כשהאוכל מרובה על הפסולת, אבל\u0004 אם ה\u0003פסולת מרובה על האוכל\u0004 — \u0003דברי הכל נוטל את האוכל ומניח את הפסולת.\u0004","ושואלים: \u0003פסולת מרובה על האוכל מי איכא מאן דשרי\u0004 \u0005[האם יש מי שמתיר]?\u0006 שמיעוט האוכלים בטל בפסולת, והכל נעשה מוקצה ואסור בטלטול! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 לומר, אלא \u0003דנפיש בטרחא\u0004 \u0005[שמרובה\u0006 הוצאת הפסולת \u0005בטרחה]\u0006 אבל \u0003זוטר בשיעורא\u0004 \u0005[קטנה\u0006 הפסולת \u0005בשיעורה],\u0006 שבאמת יש יותר אוכל מפסולת. אולם מפני שטרחת הוצאת הפסולת מרובה, מוטב להוציא משם את האוכל.","שנינו במשנה, \u0003רבן גמליאל אומר: אף מדיח\u0004 את קטניות במים \u0003ושולה\u0004 את הפסולת הצפה בהם. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' אלעזר בר' צדוק: כך היה מנהגן של בית רבן גמליאל, שהיו מביאין דלי מלא עדשים\u0004 והיו \u0003מציפין עליו מים, ונמצא\u0004 שתוך זמן קצר היה ה\u0003אוכל\u0004 שוקע \u0003למטה והפסולת\u0004 היתה צפה \u0003למעלה,\u0004 ולא הוצרכו לברור בידים.","ושואלים: \u0003והתניא איפכא\u0004 \u0005[והרי שנינו\u0006 בברייתא \u0005להיפך]\u0006 שהאוכל למעלה והפסולת למטה? ומשיבים: \u0003לא קשיא\u0004 \u0005[אין זה קשה];\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאמרנו שהפסולת למטה, מדובר \u0003בעפרא\u0004 \u0005[ב\u0006פסולת \u0005עפר]\u0006 שהעפר כבד ושוקע למטה מן העדשים, \u0003הא\u0004 \u0005[זה]\u0006 שאמרנו שהפסולת למעלה, מדובר \u0003בגילי\u0004 \u0005[בקש]\u0006 שהקש צף על פני המים.","\u0003בית שמאי אומרים: אין משלחין\u0004 מתנה \u0003ביום טוב אלא מנות\u0004 אוכל מוכנות לאכילה, \u0003ובית הלל אומרים:\u0004 שולחים מתנה אפילו \u0003בהמה חיה ועוף, בין חיין בין שחוטין. וכן משלחין יינות, שמנים וסלתות\u0004 ואפילו \u0003קטניות, אבל לא תבואה,\u0004 שהרי אינה ראויה ליום טוב, לפי שאסור לו לטוחנה ביום טוב. \u0003ור' שמעון מתיר בתבואה,\u0004 שכן יש דרכים לעשות ממנה מיני דייסא בלא טחינה.","\u0003תני\u0004 \u0005[שנה]\u0006 \u0003רב יחיאל: ובלבד שלא יעשנו בשורה,\u0004 שהובלת מתנות אלה לא תיעשה בשורה של בני אדם, שאז נראים כהולכים למסחר בשוק. \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003אין שורה\u0004 כזו \u0003פחותה משלשה בני אדם,\u0004 ובפחות מזה מכך אינה נקראת שורה ומותר. \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב אשי: תלתא גברי ותלתא מיני מאי\u0004 \u0005[שלושה אנשים ושלושה מינים\u0006 שונים \u0005מהו]?\u0006 האם נאמר שנראה זה כשיירה, או כשהיו שלושה מינים שונים כל אחד נדון לעצמו? שאלה זו לא נמצאה לה תשובה, ונשארה \u0003בתיקו.\u0004","שנינו במשנה ש\u0003ר' שמעון מתיר ב\u0004משלוח \u0003תבואה. תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003ר' שמעון מתיר בתבואה, כגון: חטין לעשות מהן לודיות\u0004 (מיני עוגיות), וכן \u0003שעורין ליתן לפני בהמתו,\u0004 או \u0003עדשים לעשות מהן רסיסין\u0004 (תבשיל עשוי עדשים מרוסקות), שכל אלה ראויים ביום טוב עצמו.","\u0003משלחין כלים\u0004 (בגדים) \u0003בין תפורין בין שאינן תפורין, ואף על פי שיש בהן כלאים\u0004 (שעטנז) \u0003ו\u0004בלבד ש\u0003הן לצורך המועד. אבל\u0004 לא משלחין \u0003סנדל\u0004 עץ המצופה עור \u0003המסומר\u0004 (שקבועים בו מסמרים וגזרו חכמים שלא לנעלו בשבת ובחג) \u0003ולא מנעל שאינו תפור\u0004 (שהרי אינו ראוי לחג). \u0003ר' יהודה אומר: אף לא\u0004 משלחים \u0003מנעל לבן\u0004 שאין דרך האנשים לנעלו, \u0003מפני שצריך אומן\u0004 כדי לצבעו שחור. \u0003זה הכלל: כל שנאותין\u0004 (מתקשטים) משתמשים \u0003בו ביום טוב\u0004 — משלחין אותו.","על המשנה שואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 שמה שהתירו לשלוח בגדים \u0003תפורין\u0004 — כי הם \u0003חזו\u0004 \u0005[ראויים]\u0006 \u0003למלבוש\u0004 ללבוש אותם, ו\u0003שאין תפורין נמי חזו לכסויי\u0004 \u0005[גם כן ראויים הם להתכסות\u0006 בהם\u0005],\u0006 \u0003אלא\u0004 בגדים שיש בהם \u0003כלאים\u0004 (שעטנז) \u0003למאי חזו\u0004 \u0005[למה\u0006 הם \u0005ראויים],\u0006 וכיון שאינם ראויים לשימוש בחג מדוע שולחים אותם במועד?","\u0003וכי תימא חזו למימך תותיה\u0004 \u0005[ואם תאמר\u0006 ש\u0005ראויים הם כדי להניח תחתיו],\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 על הפסוק: \"ובגד כלאים שעטנז \u0003לא יעלה עליך\"\u0004 (ויקרא יט, יט), ללמד כי אינך רשאי ללובשו, \u0003אבל\u0004 מדין תורה \u0003אתה יכול להציעו תחתיך. אבל אמרו חכמים: אסור לעשות כן, שמא תכרך לו נימא\u0004 (חוט) \u0003על בשרו.\u0004 הרי שמדברי חכמים אסור אף להציע אריג שעטנז תחתיו!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 ש\u0003מפסיק מידי ביני ביני\u0004 \u0005[דבר ביניהם]\u0006 שמניח את אריג הכלאים למטה ומניח דבר אחר עליהם, \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' שמעון בן פזי, אמר ר' יהושע בן לוי, אמר ר' יוסי בן שאול, אמר רבי משום קהלא קדישא\u0004 \u0005[משמו של הקהל הקדוש]\u0006 ש\u0003בירושלים: אפילו עשר מצעות\u0004 המונחות \u0003זו על גבי זו וכלאים תחתיהן\u0004 — \u0003אסור לישן עליהם, משום שנאמר: \"לא יעלה עליך\".\u0004","\u0003אלא\u0004 יש לומר, שמדובר כאן \u0003בוילון\u0004 של כלאים שאפשר לתלות אותו, שהרי איננו מלבוש. ומקשים, \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003עולא: מפני מה אמרו וילון טמא\u0004 כלומר מקבל טומאה ככלי, למרות שאין בו לכאורה שימוש לאדם — \u0003מפני שהשמש מתחמם כנגדו\u0004 שלפעמים קר לשמש והוא מתעטף לפי שעה בוילון, וכיון שיש לחשוש לכך, הרי אין לעשותו של שעטנז."],["\u0003אלא\u0004 בבגדים \u0003קשין\u0004 שעליהם מותר לשבת ואין לחשוש משום כלאים שבהם, \u0003וכי הא\u0004 \u0005[וכפי זה]\u0006 ש\u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: האי נמטא גמדא\u0004 \u0005[זה הלבד הקשה]\u0006 שעושים בעיר \u0003נרש\u0004 — \u0003שריא\u0004 \u0005[מותר]\u0006 לשבת או לשכב עליו ואין לחשוש בו משום שעטנז.","\u0003אמר רב פפא: ערדלין\u0004 \u0005[גרבי לבד]\u0006 — \u0003אין בהם משום כלאים\u0004 משום שהם קשים. \u0003אמר רבא: הני צררי דפשיטי\u0004 \u0005[אותם צרורות של כסף]\u0006 העשויים בד קשה או לבד — \u0003אין בהם משום כלאים,\u0004 אולם \u0003דבזרני\u0004 \u0005[\u0006כיסים \u0005ל\u0006הניח בהם \u0005זרעים]\u0006 — \u0003יש בהם משום כלאים,\u0004 לפי שהם גדולים ורכים יותר. \u0003רב אשי אמר: אחד זה ואחד זה אין בהן משום כלאים, לפי שאין דרך חמום בכך.\u0004 שגם אם הם צמודים לבשרו של אדם, מכל מקום אין זו דרך לבישה וחימום, ולכן אין לאסור אותם.","שנינו במשנה: \u0003אבל לא\u0004 שולחים ביום טוב \u0003סנדל המסומר.\u0004 ושואלים: \u0003סנדל המסומר מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא?\u0004 ומשיבים: \u0003משום מעשה שהיה\u0004 שבשל סנדל המסומר אירע אסון גדול בשבת, וגזרו חכמים שלא ללובשו משום כך בשבת ויום טוב (ראה מסכת שבת ס, א).","\u0003אמר אביי: סנדל המסומר אסור לנעלו\u0004 בשבת אבל \u0003מותר לטלטלו. אסור לנעלו\u0004 — \u0003משום מעשה שהיה,\u0004 וזה ש\u0003מותר לטלטלו\u0004 למדים \u0003מדקתני\u0004 \u0005[ממה ששנינו]\u0006 במשנה לשון: \u0003\"אין משלחין\", דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך]\u0006 לומר ש\u0003אסור\u0004 אפילו \u0003לטלטלו,\u0004 אם כן \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 אפילו \u0003לטלטולי\u0004 \u0005[לטלטל]\u0006 \u0003אסור, משלחין מבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]\u0006 שאסור? אלא ודאי מותר הוא בטלטול בתוך הבית, אף שאסור בלבישה. עוד שנינו במשנה: \u0003לא שולחים ביום טוב מנעל שאינו תפור.\u0004 ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 הלא אינו ראוי לנעלו! ומשיבים: \u0003לא נצרכא\u0004 \u0005[נצרכה]\u0006 אלא במקרה \u0003דאף על גב דנקיט בסיכי\u0004 \u0005[שאף על פי\u0006 שהמנעל \u0005תפור בסיכות]\u0006 ואפשר בדוחק לנעלו, על כן השמיע לנו כיון שאינו תפור ממש אין נועלים אותו, ולכן אסור לשלחו ביום טוב.","","שנינו במשנה ש\u0003ר' יהודה אומר:\u0004 אין משלחים \u0003אף לא מנעל לבן. תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003ר' יהודה מתיר ב\u0004מנעל \u0003שחור, ואוסר בלבן, מפני שצריך ביצת הגיר\u0004 (גוש הגיר) כדי לצבעו יפה. \u0003ר' יוסי אוסר ב\u0004מנעל \u0003שחור, מפני שצריך לצחצחו\u0004 (להחליקו).","ומעירים: \u0003ולא פליגי\u0004 \u0005[ואין הם חולקים]\u0006 בעיקר ההלכה. אלא \u0003מר כי אתריה ומר כי אתריה\u0004 \u0005[חכם זה כפי\u0006 מנהג \u0005מקומו וחכם זה כפי מקומו].\u0006 \u0003באתריה דמר\u0004 \u0005[במקומו של חכם\u0006 זה, ר' יהודה\u0005]\u0006 היה \u0003בשרא\u0004 \u0005[\u0006צד העור הפונה ל\u0005בשר]\u0006 שהוא עשוי כקליפות אחת על גבי השניה מונח \u0003לתחת\u0004 \u0005[מלמטה]\u0006 כלפי פנים ואינו נראה מבחוץ ולכן אינו צריך החלקה, אולם \u0003באתריה דמר\u0004 \u0005[במקומו של חכם\u0006 זה, ר' יוסי\u0005]\u0006 היה \u0003בשרא\u0004 \u0005[\u0006צד העור הפונה ל\u0005בשר]\u0006 \u0003לעיל\u0004 \u0005[מלמעלה]\u0006 מונח כלפי חוץ והיה צורך להחליקו.","שנינו במשנה: \u0003זה הכלל כל שנאותין\u0004 (מתקשטים) \u0003בו ביום טוב\u0004 משלחים אותו. מסופר: \u0003רב ששת שרא להו לרבנן לשדורי\u0004 \u0005[התיר להם לחכמים לשלוח]\u0006 \u0003תפלין ביומא טבא\u0004 \u0005[ביום טוב]\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: והא אנן תנן\u0004 \u0005[והרי אנו שנינו\u0006 במשנה\u0005],\u0006 \u0003כל שנאותין בו ביום טוב משלחין אותו,\u0004 ותפילין אין מניחים ביום טוב! ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר],\u0006 כלומר, כך יש להבין את דברי המשנה: \u0003כל שנאותין בו ב\u0004ימות ה\u0003חול\u0004 — \u0003משלחין אותו ביום טוב.\u0004 כלומר, כל דבר שהוא גמור ושלם עד כדי שראוי להשתמש בו בחול — משלחים אותו כמתנה ביום טוב.","\u0003אמר אביי: תפלין, הואיל ואתו לידן\u0004 \u0005[ובאו לידינו],\u0006 כלומר, הואיל ועסקנו בעניינם, \u0003נימא בהו מילתא\u0004 \u0005[נאמר בהם דבר]\u0006 שיש בו משום חידוש הלכה: \u0003היה\u0004 אדם \u0003בא בדרך\u0004 בערב שבת או חג \u0003ותפילין בראשו\u0004 כדרך שהיו נוהגים אז להיות לבושי תפילין במשך כל היום, \u0003ושקעה עליו חמה\u0004 ונכנסה שבת או יום טוב שאינם זמן תפילין, ואף אסור לטלטל בהם תפילין — \u0003מניח ידו עליהן,\u0004 שלא ייראו ברבים, ומעבירם כך בדרך מלבוש \u0003עד שמגיע לביתו\u0004 ושם חולצם. \u0003היה יושב בבית המדרש ותפילין בראשו וקדש עליו היום\u0004 (השבת או החג) — \u0003מניח ידו עליהן עד שמגיע לביתו.\u0004","\u0003מתיב\u0004 \u0005[מקשה\u0006 על כך\u0005]\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא\u0004 ממה ששנינו: \u0003היה בא בדרך ותפילין בראשו וקדש עליו היום\u0004 — \u0003מניח ידו עליהן עד שמגיע לבית הסמוך לחומה\u0004 ושם חולצם ומשאירם שם. \u0003היה יושב בבית המדרש,\u0004 שהיה מחוץ לעיר \u0003וקדש עליו היום\u0004 — \u0003מניח ידו עליהן עד שמגיע לבית\u0004 שיש בו אנשים היכולים לשמור את התפילין, ובית זה הוא דווקא זה \u0003הסמוך לבית המדרש.\u0004 הרי שאין מוליכם עד לביתו אלא רק לתוך המקום הקרוב אליו ביותר בתוך העיר!","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין זה קשה];\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאמרנו שמניחם בבית הסמוך לחומת העיר \u0003— דמנטרא\u0004 \u0005[שהן,\u0006 התפילין \u0005נשמרות]\u0006 שם, \u0003הא\u0004 \u0005[זה]\u0006 שאמרנו שמוליכן לביתו — מדובר באופן \u0003דלא מנטרא\u0004 \u0005[שאינן נשמרות].\u0006","ומקשים: \u0003אי דלא מנטרא\u0004 \u0005[אם\u0006 מדובר באופן \u0005שאין\u0006 התפילין \u0005נשמרות\u0006 בו\u0005],\u0006 אם כן \u0003מאי איריא\u0004 \u0005[מה שייך\u0006 דווקא\u0005]\u0006 לומר כשהתפילין \u0003בראשו? אפילו\u0004 לא לובשם אלא מצאן כשהן \u0003מחתן בארעא\u0004 \u0005[מונחות בקרקע]\u0006 \u0003נמי\u0004 \u0005[גם כן]\u0006 היה צריך ללבשן ולהביאן, \u0003דהא תנן\u0004 \u0005[שהרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003המוצא תפלין\u0004 כשהן מונחות בשדה — \u0003מכניסן זוג זוג\u0004 כדרך לבישתן!","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין זה קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאמרנו שאינו צריך ללובשן, אלא אם כן היו כבר מונחות בראשו — מדובר באופן \u0003דמנטרא\u0004 \u0005[שהן נשמרות]\u0006 \u0003מחמת גנבי\u0004 \u0005[הגנבים]\u0006 \u0003ו\u0004גם \u0003מחמת כלבי\u0004 \u0005[הכלבים].\u0006 \u0003הא\u0004 \u0005[זו]\u0006 שאמרנו שאף אם מונחות על הקרקע ילבשם ויכניסם לעיר — מדובר באופן \u0003דמנטרא\u0004 \u0005[שנשמרות]\u0006 \u0003מחמת כלבי\u0004 \u0005[הכלבים]\u0006 \u0003ולא מנטרא\u0004 \u0005[נשמרות]\u0006 \u0003מחמת גנבי\u0004 \u0005[הגנבים].\u0006","והחידוש בדבר: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 הואיל ו\u0003רוב לסטים\u0004 \u0005[הגנבים]\u0006 \u0003ישראל נינהו\u0004 \u0005[הם]\u0006 \u0003ולא מזלזלי\u0004 \u0005[יזלזלו]\u0006 \u0003בהן\u0004 בתפילין, ואם כן אין לטלטלן, שהרי אין חשש לחילול קדושתם, על כן \u0003קא משמע לן\u0004 שבכל זאת יש לחשוש למיעוט, וראוי לו להכניסן לתוך העיר.",""],["\u0003יום טוב שחל להיות\u0004 ב\u0003ערב שבת\u0004 — \u0003לא יבשל בתחלה\u0004 ובמתכוון \u0003מיום טוב ל\u0004צורך ה\u0003שבת. אבל מבשל הוא\u0004 בו ביום \u0003ל\u0004צורך \u0003יום טוב\u0004 עצמו, \u0003ואם הותיר\u0004 מן התבשילים — \u0003הותיר\u0004 לצורך \u0003השבת.\u0004 ותיקנו חכמי ישראל הקדמונים תקנת \"עירוב תבשילין\", וכך היא נעשית: \u0003עושה תבשיל\u0004 מיוחד \u0003מערב יום טוב וסומך עליו לשבת\u0004 שתבשיל זה לא ייאכל בחג אלא בשבת דווקא, וכיון שיש לו כבר תבשיל לשבת מותר לו להוסיף ולבשל אפילו ביום טוב תבשילים נוספים אחרים, שכולם יהיו לצורך השבת.","ובפרטי הדבר נחלקו תנאים ראשונים, \u0003בית שמאי אומרים:\u0004 לצורך עירוב זה צריך להכין \u0003שני תבשילין, ובית הלל אומרים:\u0004 די ב\u0003תבשיל אחד. ושוין\u0004 כולם בדעתם \u0003בדג וביצה שעליו\u0004 שטיגנו אותם יחד, \u0003שהן\u0004 נחשבים לענין זה כ\u0003שני תבשילין.\u0004","\u0003אכלו\u0004 לאותו מאכל שהכינו כעירוב ביום טוב ולא נשאר ממנו לשבת, \u0003או שאבד\u0004 — \u0003לא יבשל עליו בתחלה\u0004 אלא אם כן הותיר מתבשילי יום טוב. \u0003ואם שייר ממנו כל שהוא\u0004 — דיו בכך, ו\u0003סומך עליו לשבת.\u0004","שואלים: \u0003מנא הני מילי\u0004 \u0005[מנין דברים אלו],\u0006 מה מקור הלכה זו שיש לעשות עירוב תבשילין, ושאם לא עשה כן אין לבשל ביום טוב לצורך השבת? \u0003אמר שמואל:\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"זכור את יום השבת לקדשו\"\u0004 (שמות כ, ח) והוא למד ממנו: \u0003זכרהו\u0004 — \u0003מאחר שבא להשכיחו,\u0004 שכיון שחל החג בערב שבת, מרוב טירדת החג וריבוי סעודותיו וההכנות להן, ישכח את יום השבת, ולכן תיקנו מצוה מיוחדת להזכיר את השבת אף אז.","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעמה]\u0006 של הזכרה זו בעירוב דווקא ולשם מה בכלל נצטווינו על הזכרה זו? \u0003אמר רבא:\u0004 כוונת חכמים היתה לשמור על כבוד השבת ולכך תיקנו עירוב \u0003כדי שיברור מנה יפה לשבת ומנה יפה ליום טוב,\u0004 שאם לא יכין מראש מנה מיוחדת לשבת, יש לחשוש שלא ידאג לכבדה כראוי.","\u0003רב אשי אמר\u0004 טעם אחר: תקנת חכמים היתה דווקא לכבוד יום טוב ו\u0003כדי שיאמרו\u0004 אנשים וילמדו מכאן ש\u0003אין אופין מיום טוב לשבת,\u0004 אלא אם כן החלו בכך מבעוד יום, ו\u0003קל וחומר\u0004 שאין אופים \u0003מיום טוב לחול,\u0004 ומביא הדבר לחיזוק השמירה על כבוד החג.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003עושה\u0004 אדם \u0003תבשיל מערב יום טוב וסומך עליו לשבת. בשלמא\u0004 \u0005[נניח]\u0006 לדעת \u0003רב אשי\u0004 ש\u0003אמר\u0004 בטעם עירוב תבשילין \u0003כדי שיאמרו\u0004 ש\u0003אין אופין מיום טוב לשבת — היינו\u0004 \u0005[זה\u0006 הטעם\u0005]\u0006 שאם עשה במיוחד \u0003מערב יום טוב — אין\u0004 \u0005[כן],\u0006 אולם \u0003ביום טוב\u0004 עצמו — \u0003לא,\u0004 להזכיר שאין מבשלים מחג לשבת. \u0003אלא לרבא\u0004 שאומר בטעמו שהוא כדי שיברור מנה יפה לחג ומנה יפה לשבת, אם כן \u0003מאי איריא\u0004 \u0005[מה שייך]\u0006 שעושה \u0003מערב יום טוב? אפילו ביום טוב נמי\u0004 \u0005[גם כן]\u0006 יעשה תבשיל שמייחד אותו לשבת, ובכך יזכיר את קדושת השבת!","ומשיבים: \u0003אין הכי נמי\u0004 \u0005[כך, גם כן\u0006 הוא\u0005],\u0006 שבעצם אפשר היה לעשות כן, \u0003אלא גזרה\u0004 גזרו חכמים שיעשה עירובו מערב יום טוב \u0003שמא יפשע\u0004 (יתרשל) ולא יכין כלל.","ומעירים: \u0003ו\u0004ה\u0003תנא מייתי\u0004 \u0005[מביא]\u0006 \u0003לה\u0004 ראיה לעירוב תבשילין \u0003מהכא\u0004 \u0005[מכאן,\u0006 מכתוב זה\u0005],\u0006 שנאמר: \"שבתון שבת קודש לה' מחר \u0003את אשר תאפו אפו ואת אשר תבשלו בשלו\u0004 ואת כל העודף הניחו לכם למשמרת עד הבוקר\" (שמות טז, כג), \u0003מכאן אמר ר' אליעזר: אין אופין\u0004 מיום טוב לשבת \u0003אלא על האפוי\u0004 כבר לצורך השבת מבעוד יום, שרק מוסיפים עליו, \u0003ואין מבשלין אלא על המבושל\u0004 כבר. \u0003מכאן סמכו\u0004 (הביאו רמז) \u0003חכמים לערובי תבשילין מן התורה.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מעשה בר' אליעזר שהיה יושב ודורש כל היום\u0004 של החג \u0003כולו, בהלכות יום טוב. יצתה\u0004 באמצע דרשתו \u0003כת ראשונה, אמר: הללו\u0004 בוודאי \u0003בעלי פטסין\u0004 (כדים גדולים מאוד), שמן הסתם מוכנים לאנשים אלה פיטסין של יין, וכיוצא בו באוכל, והם להוטים אחריו ובשל כך הם יוצאים מבית המדרש. לאחר זמן יצאה \u0003כת שניה, אמר: הללו בעלי חביות\u0004 (שהן קטנות מפיטסין). לאחר מכן משיצאה \u0003כת שלישית, אמר: הללו בעלי כדין\u0004 (הקטנים מחביות).","\u0003כת רביעית, אמר: הללו בעלי לגינין\u0004 שהם קטנים מכדים. יצאה \u0003כת חמישית, אמר: הללו בעלי כוסות\u0004 שהם קטנים אף מלגינין. מש \u0003התחילו כת ששית לצאת,\u0004 קשה היה הדבר בעיניו שמותירים את בית המדרש מרוקן כמעט מיושביו ו\u0003אמר: הללו בעלי מארה\u0004 (קללה), כלומר: להם אין בבית ולא כלום, ואם כן מה הם יוצאים?","\u0003נתן עיניו בתלמידים\u0004 שנותרו בבית המדרש, מיד \u0003התחילו פניהם משתנין\u0004 מחמת הבושה, שחששו שמא להם הוא מתכוון, שמא לא היו צריכים להתעכב אלא רמז להם שייצאו כפי שיצאו האחרים. \u0003אמר להם: בני, לא לכם\u0004 (עליכם) \u0003אני אומר\u0004 כינוי זה, \u0003אלא להללו שיצאו,\u0004 וכל זאת משום \u0003שמניחים חיי עולם\u0004 של תורה \u0003ועוסקים בחיי שעה\u0004 של אכילה.","\u0003בשעת פטירתן\u0004 (פרידתם) של התלמידים שנותרו בבית המדרש ממנו לאחר שסיים דרשתו, \u0003אמר להם\u0004 כלשון הכתוב: \u0003\"\u0004ויאמר להם \u0003לכו אכלו משמנים ושתו ממתקים ושלחו מנות לאין נכון לו כי קדוש היום לאדנינו ואל תעצבו כי חדות ה' היא מעזכם\"\u0004 (נחמיה ח, י).","ומעתה מבררים את דברי הברייתא הזו. \u0003אמר מר\u0004 \u0005[החכם]\u0006 בדבריו \u0003\"שמניחין חיי עולם ועוסקין בחיי שעה\",\u0004 ותוהים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003שמחת יום טוב\u0004 עצמה הלא \u0003מצוה היא,\u0004 ואם כן אף היא בכלל חיי עולם! ומשיבים: \u0003ר' אליעזר לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 ש\u0003אמר: שמחת יום טוב\u0004 אינה אלא \u0003רשות.\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' אליעזר אומר: אין לו לאדם ביום טוב\u0004 שיקיים מצוותו כראוי, \u0003אלא, או אוכל ושותה\u0004 ומקיים מצוות שמחה בענייני הגוף, \u0003או יושב ושונה\u0004 בלימוד התורה. ואלה שלא עסקו בתורה כל צרכם — לא יפה עשו. \u0003ר' יהושע אומר:\u0004 אין צורך לעשות דווקא כך, אלא \u0003חלקהו; חציו לה'\u0004 ללימוד תורה, \u0003וחציו לכם\u0004 — לאכילה, שתיה ושאר מיני תענוג.","\u0003אמר ר' יוחנן: ושניהם מקרא אחד דרשו\u0004 בצורות שונות, וממנו למדו כשיטתם. כיצד? \u0003כתוב אחד אומר: \"עצרת לה' אלהיך\"\u0004 (דברים טז, ח), ממנו משמע כי על החג להיות מוקדש לה' ולעבודתו, \u0003וכתוב אחד אומר: \"עצרת תהיה לכם\"\u0004 (במדבר כט, לה), וממנו משמע שתכלית החג צריכה להיות \"לכם\", כלומר: בשבילכם ולהנאתכם. \u0003הא כיצד\u0004 מתיישבים שני כתובים אלה? \u0003ר' אליעזר סבר: או כולו לה'\u0004 כדברי כתוב אחד, \u0003או כולו לכם. ור' יהושע סבר: חלקהו,\u0004 כך שיהיה \u0003חציו לה' וחציו לכם\u0004 ועל ידי כך יתקיימו שני הכתובים.","כיון שהוזכר בברייתא הכתוב מספר נחמיה שואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]:\u0006 \"שלחו מנות \u0003לאין נכון לו\"? אמר רב חסדא: למי\u0004 שאין לו בשבת שלאחר יום טוב אוכל מוכן משלו, כיון \u0003שלא הניח ערובי תבשילין,\u0004 ולכן צריכים אחרים לדאוג לו. \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שכך אמר: למי צריכים לדאוג למזון — ל\u0003מי שלא\u0004 היתה \u0003לו\u0004 מסיבה כלשהי אפשרות \u0003להניח ערובי תבשילין\u0004 בערב החג, \u0003אבל מי שהיה לו\u0004 אפשרות \u0003להניח ערובי תבשילין ולא הניח\u0004 — \u0003פושע\u0004 (רשלן) \u0003הוא,\u0004 ואין חובה לדאוג לו.","ועוד: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 הכתוב \u0003\"כי חדות ה' היא מעזכם\"? אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' אליעזר בר' שמעון: אמר להם הקדוש ברוך הוא לישראל: בני, לוו עלי\u0004 (בשבילי, על חשבוני) \u0003וקדשו קדושת היום\u0004 של שבת ויום טוב ביין, \u0003והאמינו בי ואני פורע\u0004 הלוואה זו.","כיוון שנזכרו דברי ר' יוחנן בשם ר' אליעזר בר' שמעון מביאים דבר אחר ש\u0003אמר ר' יוחנן משום ר' אליעזר בר' שמעון: הרוצה שיתקיימו נכסיו\u0004 ולא ייגזלו — \u0003יטע בהן\u0004 את העץ הקרוי \u0003אדר.\u0004 ורמז לדבר, ממה \u0003שנאמר: \"אדיר במרום ה'\"\u0004 (תהלים צג, ד), שמשמעות \"אדר\" כמו משמעות \"אדיר\" מרמזת על קיום וחוזק.","\u0003אי נמי\u0004 \u0005[או גם כן]\u0006 \u0003אדרא כשמיה\u0004 \u0005[אדר כשמו],\u0006 \u0003כדאמרי אינשי\u0004 \u0005[כמו שאומרים בני אדם]:\u0006 \u0003מאי אדרא\u0004 \u0005[מה\u0006 פירוש \u0005אדר]\u0006 \u0003— דקיימא לדרי דרי\u0004 \u0005[ש\u0006הוא \u0005עומד לדורי דורות].\u0006 \u0003תניא נמי הכי\u0004 \u0005[שנויה ברייתא גם כן כך]:\u0006 \u0003שדה שיש בה אדר אינה נגזלת ואינה נחמסת\u0004 משום שהאדר נעשה סימן מובהק לשדה זה ולבעליו, \u0003ופירותיה משתמרין\u0004 משום שפירות האדר מבריחים באמצעות ריחם המיוחד את החרקים.","ושוב לענין ראשון: \u0003תני\u0004 \u0005[שנה]\u0006 \u0003רב תחליפא אחוה\u0004 \u0005[אחיו]\u0006 של \u0003רבנאי חוזאה:\u0004"],["\u0003כל מזונותיו של אדם קצובים לו מראש השנה ועד יום הכפורים,\u0004 שבאותם ימים, כאשר נגזר דינו של אדם, נקבע במדוייק גם כמה ממון ירויח לכל הוצאותיו באותה שנה, ואם יוציא לדבר אחד יותר ממה שנקבע לו — יחסר לו מדבר אחר, \u0003חוץ מהוצאת שבתות, והוצאת יום טוב, והוצאת\u0004 (שכר לימוד) \u0003בניו לתלמוד תורה\u0004 שבאלה לא נקבע סכום מסויים מתחילת השנה, אלא \u0003שאם פחת\u0004 — \u0003פוחתין לו, ואם הוסיף\u0004 — \u0003מוסיפין לו\u0004 כדי שיוכל להשלים. ולכן יכול אדם ללוות ולהוסיף, משום שמובטח לו שיהיה לו כדי סיפוקו.","\u0003אמר ר' אבהו: מאי קראה\u0004 \u0005[מהו הכתוב]\u0006 המלמד על כך שמזונותיו של אדם נקצבים לו מראש השנה — שנאמר: \u0003\"תקעו בחדש שופר בכסה ליום חגנו\"\u0004 (תהלים פא, ד) — \u0003איזהו חג שהחדש\u0004 (הירח החדש) \u0003מתכסה בו\u0004 ואינו נראה — \u0003הוי אומר זה ראש השנה,\u0004 החל בראשית החודש. שהרי בשאר החגים החלים כרגיל באמצע החודש, הירח נראה. \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 שם: \u0003\"כי חק לישראל הוא משפט לאלהי יעקב\"\u0004 (תהלים פא, ה).","ומסבירים: \u0003מאי משמע\u0004 \u0005[מה המשמעות,\u0006 מהיכן נובע\u0005]\u0006 \u0003דהאי \"חק\" לישנא דמזוני\u0004 \u0005[ש\"חק\" זה לשון מזונות]\u0006 \u0003הוא — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ואכלו את חקם אשר נתן להם פרעה\"\u0004 (בראשית מז, כב). \u0003מר זוטרא אמר: מהכא\u0004 \u0005[מכאן]\u0006 למדים ש\"חק\" הוא מזון, שנאמר: \u0003\"הטריפני לחם חקי\"\u0004 (משלי ל, ח).","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003אמרו עליו על שמאי הזקן,\u0004 ש\u0003כל ימיו היה אוכל לכבוד שבת.\u0004 כיצד? \u0003מצא בהמה נאה, אומר:\u0004 הרי \u0003זו לשבת. מצא\u0004 לאחר מכן \u0003אחרת נאה הימנה\u0004 — \u0003מניח את השניה ואוכל את הראשונה.\u0004 נמצא שסיבת אכלו את הראשונה היתה, כדי שתהא השניה שהיא יפה ממנה נאכלת בשבת, הרי שכל מאכלו היה לכבוד השבת.","\u0003אבל הלל הזקן מדה אחרת היתה לו, שכל מעשיו\u0004 אפילו בימות החול \u0003לשם שמים, שנאמר: \"ברוך ה' יום יום יעמס לנו האל ישועתנו סלה\"\u0004 (תהלים סח, כ), שלכל יום נותן הקדוש ברוך הוא ברכה לעצמו. \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]\u0006 בדרך כללית יותר ש\u0003בית שמאי אומרים: מחד שביך לשבתיך\u0004 \u0005[מאחד בשבת,\u0006 מיום ראשון, הכן כבר \u0005לשבתך]\u0006 \u0003ובית הלל אומרים: \"ברוך ה' יום יום\".\u0004","אגב הדברים שאמרו בכבוד השבת, מביאים מאמר אחר הקשור בנושא זה. \u0003אמר ר' חמא בר' חנינא: הנותן מתנה לחברו אין צריך להודיעו\u0004 שנתן לו, ואינו צריך לחשוש שמא לא יידע המקבל ממי קיבלה. \u0003שנאמר: \"ומשה לא ידע כי קרן עור פניו\"\u0004 (שמות לד, כט), הרי שניתנה לו מתנה מבלי שידע על כך.","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]:\u0006 הלא נאמר: \"אך את שבתותי תשמורו כי אות היא ביני וביניכם לדורותיכם \u0003לדעת כי אני ה' מקדשכם\"\u0004 (שמות לא, יג), ודרשו חכמים: \u0003אמר לו הקדוש ברוך הוא למשה: משה! מתנה טובה יש לי בבית גנזי ושבת שמה, ואני מבקש\u0004 (רוצה) \u0003ליתנה לישראל, לך והודיע אותם\u0004 על כוונתי זו. \u0003ומכאן אמר רבן שמעון בן גמליאל: הנותן פת\u0004 במתנה \u0003לתינוק, צריך להודיע לאמו\u0004 שנתן לו מתנה זו, כדי שידעו הוריו על חיבתו להם ובכך ירבה חיבה ורעות בישראל, והרי זה היפך דברי ר' חמא!","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין זה קשה];\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאינו צריך להודיע הוא \u0003במתנה דעבידא לאגלויי\u0004 \u0005[שעשויה להתגלות],\u0006 כגון קירון עור פני משה שהכל מספרים לו על כך, \u0003הא\u0004 \u0005[זו]\u0006 שצריך להודיע הוא \u0003במתנה דלא עבידא לאגלויי\u0004 \u0005[שאינה עשויה להתגלות]\u0006 מעצמה. ומקשים: \u0003שבת נמי\u0004 \u0005[גם כן]\u0006 הלא \u0003מתנה דעבידא לאגלויי\u0004 \u0005[שעשויה להתגלות]\u0006 היא, שהרי סוף סוף יודיע להם מתי השבת ומה עניינה! ומשיבים: מכל מקום \u0003מתן שכרה לא עבידא לאגלויי\u0004 \u0005[אינו עשוי להתגלות],\u0006 ולכן אמר ה' למשה להודיע שה' נותן להם את השבת, ופירט מה שכרה של שבת.","\u0003אמר מר\u0004 \u0005[החכם],\u0006 \u0003מכאן אמר רבן שמעון בן גמליאל: הנותן פת לתינוק צריך להודיע לאמו.\u0004 ושואלים: \u0003מאי עביד ליה\u0004 \u0005[מה עושה הוא לו],\u0006 כלומר כיצד מודיע לאמו? \u0003שייף ליה משחא\u0004 \u0005[מורח עליו שמן]\u0006 \u0003ומלי ליה כוחלא\u0004 \u0005[וצובע עיניו בכחול]\u0006 וכשמגיע הביתה שואלת אמו מי משח אותו כך, ומספר שאדם פלוני משח זאת, ואף נתן לו פת. ומעירים: \u0003והאידנא דחיישינן\u0004 \u0005[ועכשיו שחוששים אנו]\u0006 \u0003לכשפים\u0004 ויש לחשוש שמא התכווין הנותן בצביעת עיני הקטן בכחול למעשה כשפים, \u0003מאי\u0004 \u0005[מה\u0006 עושים\u0005]?\u0006 \u0003אמר רב פפא: שייף ליה\u0004 \u0005[מושח עליו]\u0006 מעט \u0003מאותו המין\u0004 שנותן לו, (כגון חמאה או גבינה) ועל ידי כך מבחינה האם שקיבל התינוק מתנה.","ועוד בענין נתינת השבת לישראל, \u0003אמר ר' יוחנן משום ר' שמעון בן יוחאי: כל מצוה שנתן להם הקדוש ברוך הוא לישראל\u0004 — \u0003נתן להם בפרהסיא\u0004 (בגילוי ובפרסום) \u0003חוץ משבת שנתן\u0004 אותה \u0003להם בצנעא. שנאמר: \"ביני ובין בני ישראל אות היא לעלם\"\u0004 (שמות לא, יז), כלומר הריהו כעין סוד בין ה' וישראל.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שנתנה בצינעה ולא ידעו הכל על כך, ש\u0003לא לענשו\u0004 \u0005[יענשו]\u0006 \u0003גויים עלה\u0004 \u0005[עליה],\u0006 על שלא רצו לקבל מצוה זו כשם שעשויים הם להיענש על שלא רצו לקבל את שאר מצוות התורה? ומשיבים: עצם ענין ה\u0003שבת אודועי אודעינהו\u0004 \u0005[הודיע להם]\u0006 הקדוש ברוך הוא, אולם \u0003מתן שכרה\u0004 של קיום מצוה זו \u0003לא אודעינהו\u0004 \u0005[הודיעם].\u0006 \u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003מתן שכרה נמי אודעינהו\u0004 \u0005[גם כן הודיע להם]\u0006 לגויים, אולם את דבר ה\u0003נשמה\u0004 ה\u0003יתירה\u0004 שבאה לו לאדם בשבת — דבר זה \u0003לא אודעינהו\u0004 \u0005[הודיעם].\u0006","ש\u0003אמר ר' שמעון בן לקיש: נשמה יתירה נותן הקדוש ברוך הוא באדם בערב שבת, ולמוצאי שבת נוטלין אותה הימנו, שנאמר: \"שבת וינפש\"\u0004 (שמות לא, יז), ודרש: \u0003כיון ששבת\u0004 ועברה השבת \u0003ווי אבדה נפש\u0004 (\"וי־נפש\"), אותה נשמה יתירה שניטלת ממנו.","שנינו במשנה ש\u0003עושה אדם תבשיל מערב יום טוב\u0004 וסומך עליו לשבת לעירוב תבשילין. \u0003אמר אביי: לא שנו\u0004 שיש בעירוב תבשילין כדי להועיל לענין בישול מיום טוב לשבת, \u0003אלא\u0004 כשעושה אותו מ\u0003תבשיל, אבל פת\u0004 — \u0003לא.\u0004","ושואלים: \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 \u0003פת דלא\u0004 \u0005[שאיננה]\u0006 ראויה לכך? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 כי \u0003מידי\u0004 \u0005[\u0006ל\u0005דבר]\u0006 שהוא \u0003מלפת,\u0004 כלומר שהוא נותן טעם, \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 \u0003ו\u0004ה\u0003פת\u0004 עצמה \u0003לא מלפתא\u0004 \u0005[איננה מלפתת,\u0006 אינה נותנת טעם\u0005]\u0006 \u0003— והא\u0004 \u0005[והרי]\u0006 \u0003דייסא נמי לא מלפתא\u0004 \u0005[גם כן אינה מלפתת,\u0006 אינה נותנת טעם\u0005],\u0006 שהרי כבר \u0003אמר ר' זירא: הני בבלאי טפשאי דאכלי נהמא בנהמא\u0004 \u0005[אותם הבבליים הטפשים שאוכלים לחם בלחם],\u0006 כלומר שנוהגים היו לאכול לחם עם דייסא, משמע שדייסא אינה עדיפה מלחם בענין זה. ובכל זאת \u0003אמר רב נחומי בר זכריה משמיה\u0004 \u0005[משמו]\u0006 של \u0003אביי: מערבין בדייסא! אלא\u0004 כך יש לומר: \u0003מידי דלא שכיח\u0004 \u0005[דבר שאינו מצוי]\u0006 \u0003בעינן\u0004 \u0005[צריכים אנו],\u0006 שיהיה ברור שמניח אותו לצורך העירוב, \u0003ופת שכיחא\u0004 \u0005[מצויה],\u0006 \u0003ודייסא לא שכיחא\u0004 \u0005[מצויה].\u0006","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 סוגיה זו בגירסה אחרת. \u0003אמר אביי: לא שנו\u0004 שמועיל עירוב תבשילין \u0003אלא\u0004 כשעושהו מ\u0003תבשיל, אבל פת\u0004 — \u0003לא.\u0004 ושאלו \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003אילימא דמידי דלא שכיח בעינן\u0004 \u0005[אם תאמר שדבר שאינו מצוי צריכים אנו]\u0006 \u0003ופת שכיחא\u0004 \u0005[מצויה],\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 ה\u0003דייסא לא שכיחא\u0004 \u0005[מצויה\u0006 כל כך] ובכל זאת \u0003אמר רב נחומי בר זכריה משמיה\u0004 \u0005[משמו]\u0006 של \u0003אביי: אין מערבין\u0004 עירובי תבשילין \u0003בדייסא! אלא\u0004 כך יש לומר: \u0003מידי\u0004 ש\u0003מלפת,\u0004 שהוא נותן טעם \u0003בעינן\u0004 \u0005[צריכים אנו],\u0006 \u0003ופת לא מלפתא\u0004 \u0005[מלפתת]\u0006 \u0003ו\u0004ה\u0003דייסא נמי\u0004 \u0005[גם כן]\u0006 \u0003לא מלפתא\u0004 \u0005[מלפתת].\u0006 ש\u0003אמר ר' זירא: הני בבלאי טפשאי דאכלי נהמא בנהמא\u0004 \u0005[אותם הבבליים הטפשים שאוכלים לחם בלחם],\u0006 ומדבריו למדים שהדייסה כמו הלחם עצמו איננה מלפתת.","שנה \u0003ר' חייא: עדשים\u0004 שנותרו בערב יום טוב \u0003בשולי קדרה\u0004 — \u0003סומך עליהן משום ערובי תבשילין.\u0004 שאף על פי שלא הוכנו לשם כך, מכל מקום בכלל תבשיל הם. \u0003והני מילי\u0004 \u0005[ודברים אלו\u0006 אמורים\u0005]\u0006 דווקא \u0003דאית בהו\u0004 \u0005[שיש בהם]\u0006 בכולם \u0003כזית.\u0004 כיוצא בו \u0003אמר רב יצחק בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהודה: שמנונית\u0004 בשר וכיוצא בו \u0003שעל גבי הסכין\u0004 — \u0003גוררו\u0004 (מגרד אותו) מעל גבי הסכין \u0003וסומך עליו משום עירובי תבשילין. והני מילי\u0004 \u0005[ודברים אלה]\u0006 אמורים דווקא \u0003דאית בהו\u0004 \u0005[כשיש בהם,\u0006 בכל אותה שמנונית\u0005]\u0006 \u0003כזית.\u0004","\u0003אמר רב אסי אמר רב: דגים קטנים מלוחים אין בהם משום בשולי גויים\u0004 לפי שראויים לאכילה במלחם, ובישולם לא עשאם ראויים לאכילה יותר מכפי שהיו ראויים טרם בישולם. \u0003אמר רב יוסף: ואם צלאן\u0004 אפילו \u0003גוי\u0004 — \u0003סומך עליהם\u0004 ישראל \u0003משום ערובי תבשילין,\u0004 שהרי אינם בהם משום בישולי גויים וראויים הם איפוא לאכילה. אולם \u0003אי עבדינהו\u0004 \u0005[אם עשה אותם]\u0006 ה\u0003גוי כסא דהרסנא\u0004 \u0005[מטוגנים בשמן ובקמח]\u0006 \u0003אסור\u0004 משום בישולי גויים, שהוא כבר נדון כמאכל חשוב.","ומקשים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו שכך הוא הדבר\u0005]!\u0006 ומשיבים: יש בכך חידוש כי \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006"],["\u0003הרסנא\u0004 \u0005[שומן הדגים]\u0006 הוא ה\u0003עיקר\u0004 וזה הרי מותר לאוכלו גם בבישולי גויים, \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 כי \u0003קמחא\u0004 \u0005[הקמח]\u0006 הוא ה\u0003עיקר,\u0004 ויש כאן מין תבשיל חדש וחשוב.","\u0003אמר ר' אבא: ערובי תבשילין צריכין\u0004 שיהיה בהם \u0003כזית. איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 שאלה זו ללומדים: האם צריך שיהיה \u0003כזית אחד לכולן\u0004 לכל בני הבית הסומכים על עירוב זה, \u0003או דלמא\u0004 \u0005[שמא]\u0006 שיהיה \u0003כזית לכל אחד ואחד\u0004 מבני הבית? \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ש\u0003אמר ר' אבא אמר רב: ערובי תבשילין צריכין\u0004 שיהיה בהם \u0003כזית בין\u0004 שמבשל \u0003ל\u0004אדם \u0003אחד, בין\u0004 שמבשל \u0003למאה\u0004 אנשים.","ומעירים: \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003אכלו\u0004 לעירוב התבשילין שהכין \u0003או שאבד\u0004 — \u0003לא יבשל עליו בתחלה\u0004 בים טוב לצורך השבת, ואם \u0003שייר ממנו כל שהוא\u0004 — \u0003סומך עליו לשבת.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003כל שהוא? לאו אף על גב דליכא\u0004 \u0005[האם לא אף על פי שאין]\u0006 בו \u0003כזית\u0004 ואין צורך בשיעור כלל? ודוחים: \u0003לא,\u0004 \"כל שהוא\" זה, כוונתו \u0003דאית ביה\u0004 \u0005[שיש\u0006, שנותר \u0005בו]\u0006 אף לאחר שאכל ממנו, \u0003כזית.\u0004","ומנסים להביא ראיה אחרת, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]:\u0006 \u0003תבשיל\u0004 שאמרו בעירוב תבשילין — \u0003זה צלי,\u0004 אבל \u0003אפילו כבוש\u0004 או \u0003שלוק\u0004 (מבושל הרבה) או \u0003מבושל\u0004 כרגיל, וכן \u0003קולייס האספנין\u0004 (מין דג רך) \u0003שנתן עליו\u0004 מים \u0003חמין מערב יום טוב\u0004 ואז הוא כמוכן ומבושל — הרי זה בכלל תבשיל. לענין \u0003תחלתו וסופו\u0004 (כלומר, בין שיעורו לכתחילה, ובין שיעורו כשנתמעט ואבד או שאכל חלק ממנו) של עירוב זה — \u0003אין לו שיעור. מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה \u0003אין לו שיעור כלל\u0004 אפילו בכלשהו? ודוחים: \u0003לא,\u0004 הכוונה היא ש\u0003אין לו שיעור למעלה,\u0004 כלומר: אין לו שיעור עליון שאין להוסיף עליו, \u0003אבל יש לו שיעור למטה,\u0004 שאין פוחתים ממנו, ושיעור זה הוא בכזית.","\u0003אמר רב הונא אמר רב: ערובי תבשילין צריכין דעת\u0004 שיש צורך בידיעה על העירוב כדי שיחול ויועיל. ומעירים: \u0003פשיטא\u0004 \u0005[פשוט\u0006 הוא ומובן מאליו\u0005],\u0006 כי את \u0003דעת מניח\u0004 העירוב ודאי \u0003בעינן\u0004 \u0005[צריכים אנו],\u0006 והשאלה היא: האם את \u0003דעת מי שהניחו לו\u0004 (עבורו) עירוב, \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 \u0003או לא בעינן\u0004 \u0005[צריכים אנו]?\u0006","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 הוכחה לדבר: \u0003דאבוה\u0004 \u0005[שאביו]\u0006 של \u0003שמואל\u0004 היה \u0003מערב אכולה\u0004 \u0005[עבור כל]\u0006 העיר \u0003נהרדעא,\u0004 ו\u0003ר' אמי ור' אסי מערבי אכולה טבריא\u0004 \u0005[היו מערבים\u0006 עבור \u0005כל\u0006 העיר \u0005טבריה].\u0006 וכן היה \u0003מכריז ר' יעקב בר אידי: מי שלא הניח\u0004 והכין \u0003ערובי תבשילין\u0004 עבור עצמו, \u0003יבא ויסמוך על\u0004 העירוב \u0003שלי.\u0004 ושואלים: \u0003ועד כמה\u0004 יכול לסמוך? כלומר עד לאיזה מרחק יכולים לסמוך על עירוב שאדם מזכה בו לאחרים? \u0003אמר רב נחומי בר זכריה משמיה\u0004 \u0005[משמו]\u0006 של \u0003אביי: עד תחום שבת.\u0004","מסופר: \u0003ההוא סמיא דהוה מסדר מתניתא קמיה\u0004 \u0005[עוור אחד שהיה מסדר משניות לפני]\u0006 \u0003מר שמואל, חזייה דהוה עציב\u0004 \u0005[ראהו\u0006 שמואל \u0005שהוא עצוב],\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אמאי עציבת\u0004 \u0005[מדוע אתה עצוב]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 ש\u0003לא אותיבי\u0004 \u0005[הנחתי]\u0006 \u0003ערובי תבשילין. אמר ליה\u0004 \u0005[לו]:\u0006 \u0003סמוך אדידי\u0004 \u0005[על\u0006 העירוב \u0005שלי].\u0006 \u0003לשנה\u0004 הבאה שוב \u0003חזייה דהוה עציב\u0004 \u0005[ראה שהוא עצוב],\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אמאי עציבת\u0004 \u0005[מדוע אתה עצוב]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 ש\u0003לא אותיבי\u0004 \u0005[הנחתי]\u0006 \u0003ערובי תבשילין. אמר ליה\u0004 \u0005[לו]\u0006 מר שמואל: אם כך \u0003פושע\u0004 (רשלן) \u0003את\u0004 \u0005[אתה],\u0006 שרואים שהתעצלת והתרשלת בדבר. ולכן \u0003לכולי עלמא שרי\u0004 \u0005[לכל העולם מותר],\u0006 שכל מי ששכח להניח עירובי תבשילין, מותר לו לסמוך על העירוב שלי ולבשל מיום טוב לשבת, אולם \u0003לדידך\u0004 \u0005[בשבילך]\u0006 \u0003אסור,\u0004 לפי שאנשים כמותך לא התכוונתי להוציא בעירוב שלי.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003יום טוב שחל להיות בערב שבת\u0004 — \u0003אין מערבין\u0004 בו ביום \u0003לא ערובי תחומין ולא ערובי חצרות\u0004 לשבת, ואם לא תיקנום מערב יום טוב — אינו יכול לעשות כן ביום טוב.","\u0003רבי אומר: מערבין\u0004 ביום טוב שחל להיות בערב שבת \u0003ערובי חצרות, אבל לא ערובי תחומין.\u0004 וטעמו: \u0003מפני שאתה אוסרו בדבר האסור לו, ואי\u0004 \u0005[ואין]\u0006 \u0003אתה אוסרו בדבר המותר לו,\u0004 שכיון שביום טוב עצמו אסור לצאת מחוץ לתחום — \u0003על כן גם אסור לו לעשות בו עירוב תחומין. אולם כיון שביום טוב אין כל איסור להוציא מרשות לרשות\u0004 — על כן מותר לעשות עירוב חצירות ביום טוב.","\u0003אתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בפסק ההלכה בענין זה, \u0003רב אמר: הלכתא\u0004 \u0005[ההלכה]\u0006 \u0003כתנא קמא\u0004 \u0005[כדברי התנא הראשון],\u0006 שאמר שהכל אסור. \u0003ושמואל אמר: הלכה כרבי,\u0004 שמותר לערב עירובי חצירות.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 ללומדים שאלה זו: האם \u0003הלכה כרבי לקולא\u0004 \u0005[להקל]\u0006 \u0003או לחומרא\u0004 \u0005[להחמיר]?\u0006 ותוהים: \u0003פשיטא דלקולא קאמר\u0004 \u0005[פשוט שלהקל אמר]!\u0006 ומשיבים: \u0003משום דשלח\u0004 \u0005[ששלח]\u0006 \u0003ר' אלעזר\u0004 מארץ ישראל \u0003לגולה: לא כ\u0004גירסה זו \u0003שאתם שונין בבבל\u0004 בברייתא זו ש\u0003רבי מתיר וחכמים אוסרין, אלא\u0004 צריך להפוך ולגרוס כי \u0003רבי אוסר וחכמים מתירין.\u0004 ואם כן השאלה היא \u0003מאי\u0004 \u0005[מה\u0006 פסק ההלכה\u0005]\u0006 האם להקל או להחמיר?","ומנסים להביא ראיה: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ש\u0003רב תחליפא בר אבדימי עבד עובדא כותיה\u0004 \u0005[עשה מעשה כשיטתו]\u0006 של \u0003שמואל\u0004 שפסק הלכה כרבי, \u0003ואמר רב\u0004 על כך בכעס: \u0003תחלת הוראה דהאי צורבא מרבנן\u0004 \u0005[של תלמיד חכם זה]\u0006 שהורה לרבים — \u0003לקלקולא\u0004 \u0005[לקלקול]\u0006 היא. ומעתה נברר: \u0003אי אמרת בשלמא לקולא קאמר\u0004 \u0005[נניח אם אומר אתה\u0006 שרבי \u0005להקל אמר]\u0006 — \u0003היינו קלקולא\u0004 \u0005[זהו הקלקול\u0006 בדבר\u0005]\u0006 ועל כך כעס רב שהתלמיד סמך על עצמו ופסק להקל בדבר השנוי במחלוקת. \u0003אלא אי אמרת לחומרא\u0004 \u0005[אם אומר אתה\u0006 שדעת רבי היא \u0005להחמיר]\u0006 — \u0003מאי קלקולא איכא\u0004 \u0005[מה קלקול יש\u0006 בכך\u0005]?\u0006","ומשיבים: \u0003כיון דמקלקלי בה\u0004 \u0005[שמתקלקלים בכך]\u0006 \u0003רבים\u0004 שאם אינם עושים עירוב חצירות, יכולים הם להיכשל ולטלטל בטעות בלא עירוב,"],["\u0003היינו קלקולא\u0004 \u0005[\u0006ו\u0005הרי זה הקלקול],\u0006 בכך שאסר לערב מאתמול, ואין איפוא להוכיח מכאן. \u0003אמר רבא אמר רב חסדא אמר רב הונא: הלכה כרבי, ולאסור\u0004 שאין מערבין לא לתחומים ולא לחצירות. שפסק הלכה בנושא זה כשיטת רב רבו וכגירסת ר' אליעזר.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003יום טוב שחל להיות בשבת, בית שמאי אומרים: מתפלל שמנה\u0004 ברכות בתפילת עמידה, שמוסיף שתי ברכות אמצעיות על שלוש ראשונות ושלוש אחרונות ואותן שתי ברכות אמצעיות ש\u0003אומר,\u0004 הרי הן, ברכה אחת \u0003של שבת בפני עצמה, ו\u0004ברכה אחת נוספת \u0003של יום טוב בפני עצמה. ובית הלל אומרים: מתפלל שבע\u0004 ברכות בלבד, שלוש ראשונות ושלוש אחרונות ואחת באמצע, אשר בה הוא \u0003מתחיל בשל שבת ומסיים בשל שבת, ואומר קדושת היום\u0004 של אותו חג \u0003באמצע. רבי אומר: אף חותם בה\u0004 בברכה זו מעין שבת ויום טוב יחד: \u0003\"מקדש השבת, ישראל והזמנים\".\u0004","\u0003תני תנא קמיה\u0004 \u0005[שנה חוזר המשניות לפני]\u0006 \u0003רבינא\u0004 נוסח זה: \u0003\"מקדש ישראל והשבת והזמנים\". אמר ליה\u0004 \u0005[לו]\u0006 רבינא לאותו תנא: \u0003אטו\u0004 \u0005[וכי]\u0006 את ה\u0003שבת ישראל מקדשי ליה\u0004 \u0005[\u0006הם ש\u0005מקדשים אותה]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 ה\u0003שבת מקדשא וקיימא\u0004 \u0005[מקודשת ועומדת]\u0006 מששת ימי בראשית, שכל יום שביעי הוא מעצמו שבת, ואין השבת מתקדשת על ידי החלטת ישראל. \u0003אלא אימא\u0004 \u0005[אמור,\u0006 תקן\u0005]\u0006 בנוסח זה: \u0003\"מקדש השבת, ישראל והזמנים\",\u0004 שאכן ישראל הם המקדשים את הזמנים — ראשי חדשים ומועדים. \u0003אמר רב יוסף: הלכה כרבי\u0004 לענין סיום הברכה, \u0003וכדתריץ\u0004 \u0005[וכפי שיישב,\u0006 קבע\u0005]\u0006 \u0003רבינא.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שבת שחל להיות בראש חדש או בחולו של מועד,\u0004 תפילות \u0003ערבית ושחרית ומנחה\u0004 של שבת \u0003מתפלל\u0004 כרגיל \u0003שבע\u0004 ברכות, \u0003ואומר מעין המאורע\u0004 (\"יעלה ויבוא\") בברכת ה\u0003עבודה\u0004 (\"רצה\"). \u0003ואם לא אמר\u0004 — \u0003מחזירין אותו\u0004 ויתפלל שנית. \u0003רבי אליעזר אומר:\u0004 מעין המאורע אומר \u0003ב\u0004תפילת \u0003הודאה\u0004 (\"מודים\"). \u0003ו\u0004אילו \u0003ב\u0004תפילת ה\u0003מוספין\u0004 משנה את נוסח הברכה עצמה: \u0003מתחיל בשל שבת ומסיים בשל שבת, ואומר קדושת היום\u0004 — ראש חודש או חול המועד — \u0003באמצע.\u0004","\u0003רבן שמעון בן גמליאל ור' ישמעאל בנו של ר' יוחנן בן ברוקא אומרים: כל מקום שהוזקק לשבע\u0004 ברכות, לאו דווקא בתפלת המוספים, אלא בכל תפילות היום אף בשחרית מנחה וערבית, \u0003מתחיל בשל שבת ומסיים בשל שבת ואומר קדושת היום באמצע. אמר רב הונא: אין הלכה כאותו הזוג,\u0004 אלא כשיטת התנא הראשון שבשחרית מנחה וערבית מתפלל שבע ברכות ואומר מעין המאורע בעבודה.","\u0003אמר רב חייא בר אשי אמר רב: מניח אדם עירובי תחומין מיום טוב לחברו\u0004 ליום טוב שני של גלויות, \u0003ומתנה,\u0004 ואומר כך: אם היום הוא אכן יום טוב אם כן למחר יום חול הוא, ומותר הרי ללכת בו כמה שארצה לכל צד. ואם היום חול הוא ומחר יום טוב — הרי אני מניח עירוב תחומין למחר. וכן יתנה למחרת על אותה פת.","\u0003אמר רבא: מניח אדם ערובי תבשילין מיום טוב לחבירו, ומתנה\u0004 ואומר: אם היום חול ומחר קודש — עירובי עירוב ובשלו אהיה מותר לבשל למחר לצורך השבת, ואם היום קודש ולמחר חול — הרי מותר אני בבישול כבשאר ימות החול.","ומעירים: \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר\u0004 דין זה בענין \u0003עירובי תחומין כל שכן\u0004 שהוא מתיר לעשות כן \u0003בעירובי תבשילין, ומאן\u0004 \u0005[ומי]\u0006 ש\u0003אמר\u0004 דין זה בענין \u0003עירובי תבשילין\u0004 — \u0003אבל\u0004 ב\u0003עירובי תחומין לא\u0004 הותר הדבר. \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]\u0006 — \u0003דלמקני\u0004 \u0005[שלקנות]\u0006 \u0003שביתה בשבתא\u0004 \u0005[ב\u0006יום \u0005של שבתון]\u0006 \u0003לא\u0004 התירו אפילו במקום ספק. אבל בעירוב תבשילין שבעצם הוא רק לסימן בלבד — משום כבוד השבת התירוהו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אין אופין\u0004 פת \u0003מיום טוב לחבירו\u0004 יום טוב שני של גלויות. אף על פי כן, \u0003באמת אמרו\u0004 הלכה קבועה: \u0003ממלאה אשה\u0004 את \u0003כל הקדרה בשר\u0004 לבשל ביום טוב, \u0003אף על פי שאינה צריכה\u0004 באותו יום \u0003אלא לחתיכה אחת,\u0004 והשאר יהא למחר. וכן \u0003ממלא נחתום חבית של מים\u0004 לחמם אותם \u0003אף על פי שאינו צריך אלא לקיתון\u0004 (כלי קטן) \u0003אחד\u0004 של מים חמים. \u0003אבל לאפות\u0004 — \u0003אינו אופה אלא מה שצריך לו\u0004 לאותו יום בלבד.","\u0003ר' שמעון בן אלעזר אומר: ממלאה אשה\u0004 את \u0003כל התנור פת\u0004 אף על פי שאינה צריכה את כל הכמות לאותו היום, \u0003מפני שהפת נאפה יפה בזמן שהתנור מלא,\u0004 שכל כמה שהתנור מלא יותר, מתמעט חללו וחומו רב יותר. ונמצא שמילוי התנור משמש לא רק להוסיף פת למחר, אלא ליופיה של הפת לאותו יום. \u0003אמר רבא: הלכה כר' שמעון בן אלעזר.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 לחכמים שאלה זו: \u0003מי שלא הניח עירובי תבשילין,\u0004 האם \u0003הוא נאסר\u0004 לבשל ליום השבת ואף \u0003קמחו נאסר,\u0004 שכל המזונות שבידו אסור להשתמש בהם לצורך השבת. \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003הוא נאסר\u0004 לעשות מלאכה זו \u0003ואין קמחו נאסר?\u0004","ושואלים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מכאן]\u0006 הבדל, הלכה למעשה? ומסבירים: \u0003לאקנויי\u0004 \u0005[ל\u0006ענין \u0005הקניית]\u0006 \u0003קמחו לאחרים. אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 כי \u0003הוא נאסר וקמחו נאסר — צריך לאקנויי\u0004 \u0005[להקנות]\u0006 את \u0003קמחו לאחרים\u0004 כדי שיוכלו אחרים לאפות לצורכו, אם ירצו. \u0003ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 כי \u0003הוא נאסר ואין קמחו נאסר — לא צריך לאקנויי\u0004 \u0005[להקנות]\u0006 \u0003קמחו לאחרים,\u0004 אלא אחרים יכולים לאפות לצורכו אף בלא שייחשב הקמח כשלהם. ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 אכן הדין\u0005]?\u0006","ומשיבים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 \u0003פתרון לדבר ממה שנאמר בברייתא: מי שלא הניח עירובי תבשילין\u0004 בערב יום טוב — \u0003הרי זה לא יאפה ולא יבשל ולא יטמין\u0004 ביום טוב לצורך השבת החלה למחרת, \u0003לא לו ולא לאחרים, ולא אחרים אופין ומבשלין לו. כיצד הוא עושה\u0004 שיוכל בכל זאת לאכול בשבת — \u0003מקנה קמחו לאחרים ואופין לו ומבשלין לו.\u0004 ומלשון \"מקנה קמחו לאחרים\" \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003הוא נאסר וקמחו נאסר\u0004 ולכן צריך להקנותו. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 לחכמים\u0005]\u0006 השאלה הבאה: \u0003עבר ואפה\u0004 ביום טוב לשבת בלא שעשה עירוב תבשילין בערב יום טוב, \u0003מאי\u0004 \u0005[מה\u0006 דינו\u0005]?\u0006 האם מותר או אסור לאכול מפתו ותבשילו? ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר, ממה ששנינו בברייתא: \u0003מי שלא הניח עירובי תבשילין, כיצד הוא עושה\u0004 — \u0003מקנה קמחו לאחרים, ואחרים אופין לו ומבשלין לו\u0004."],["\u0003ואם איתא\u0004 \u0005[יש\u0006 מקום להנחה זו\u0005]\u0006 שאם עבר ואפה, מותר לו לאכול בשבת את שאפה, אם כן \u0003ליתני\u0004 \u0005[שישנה]:\u0006 \u0003עבר ואפה מותר! אמר רב אדא בר מתנה:\u0004 מכאן אין ראיה, כי ה\u0003תנא, תקנתא דהיתרא\u0004 \u0005[תקנה של\u0006 דבר שנעשה ב\u0005היתר]\u0006 — \u0003קתני\u0004 \u0005[שנה],\u0006 אולם \u0003תקנתא דאסורא\u0004 \u0005[תקנה\u0006 לדבר \u0005של איסור]\u0006 \u0003לא קתני\u0004 \u0005[שנה],\u0006 ולא סבר שיש ללמדנו שאפשר לעשות גם באופן זה.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 ראיה ממה ששנינו בברייתא אחרת: \u0003מי שהניח עירובי תבשילין\u0004 — \u0003הרי זה אופה ומבשל\u0004 מיום טוב לשבת \u0003ומטמין\u0004 חמין מיום טוב לשבת, \u0003ואם רצה לאכול את עירובו\u0004 ביום השבת — \u0003הרשות בידו\u0004 לאוכלו. אבל אם \u0003אכלו\u0004 ביום טוב \u0003עד שלא אפה\u0004 או \u0003עד שלא הטמין\u0004 — \u0003הרי זה לא יאפה ולא יבשל ולא יטמין, לא לו ולא לאחרים. ו\u0004כן \u0003לא אחרים אופין ומבשלין לו.\u0004","\u0003אבל\u0004 גם בלא עירוב \u0003מבשל הוא ליום טוב\u0004 עצמו, \u0003ואם הותיר\u0004 ממה שבישל — \u0003הותיר לשבת, ובלבד שלא יערים\u0004 ויאמר שכוונתו במה שמבשל כמות גדולה, לאורחים נוספים ליום טוב, ובעצם יבשל לצורך השבת. \u0003ואם הערים\u0004 — \u0003אסור\u0004 לו לאוכלו, מגזירת חכמים. משמע מכאן שהמבשל באיסור מיום טוב לשבת אסור באכילה!","\u0003אמר רב אשי:\u0004 אין זו ראיה, כי \u0003הערמה קא אמרת\u0004 \u0005[אומר אתה]\u0006 — \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003הערמה דאחמירו\u0004 \u0005[שהחמירו]\u0006 \u0003בה רבנן\u0004 \u0005[חכמים]\u0006 \u0003טפי\u0004 \u0005[יותר]\u0006 \u0003מ\u0004כפי שהחמירו במבשל ביום טוב ב\u0003מזיד\u0004 לצורך השבת. לפי שהמזיד יודע שהוא חוטא, ויש לקוות כי מתוך ידיעתו יחזור בתשובה ולא יוסיף לחטוא עוד בכגון זה ולא ילמדו אחרים ממעשיו, אולם המערים, נדמה לו שבהיתר הוא עושה, ויש לחשוש שיוסיף לחטוא באופן זה וילמדו אחרים ממעשיו ועשויה תורת עירוב להיעקר.","\u0003רב נחמן בר יצחק אמר\u0004 טעם אחר מדוע אין להוכיח מברייתא זו: \u0003הא מני\u0004 \u0005[\u0006ברייתא \u0005זו\u0006 כשיטת \u0005מי היא]\u0006 — כשיטת \u0003חנניה היא, ואליבא\u0004 \u0005[ועל פי שיטת]\u0006 \u0003בית שמאי. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003חנניה אומר, בית שמאי אומרים: אין אופין\u0004 פת ביום טוב לצורך השבת, \u0003אלא אם כן ערב\u0004 מערב יום טוב \u0003בפת\u0004 דווקא, \u0003ואין מבשלין\u0004 תבשיל כלשהו \u0003אלא אם כן ערב בתבשיל, ואין טומנין אלא אם כן היה חמין טמונין מערב יום טוב.\u0004","\u0003ובית הלל אומרים: מערב בתבשיל אחד, ועושה בו כל צרכו\u0004 — לאפות, לבשל ולהטמין. וכיון שקיימת שיטה מחמירה של חנניה לדעת בית שמאי, מן הסתם מחמירים הם גם בדיעבד, ועל כן אין להביא משם ראיה.","ומציעים עוד: \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 אם עבר אדם על איסור חכמים והוא \u0003מעשר פירותיו בשבת,\u0004 אם עישרם \u0003בשוגג\u0004 — \u0003יאכל\u0004 מהם, \u0003במזיד\u0004 — \u0003לא יאכל.\u0004 משמע שאסור לאדם ליהנות מאיסור שעשה! ודוחים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 ולא נאמרה הלכה זו אלא באופן \u0003דאית ליה פירי אחריני\u0004 \u0005[שיש לו פירות אחרים],\u0006 שאין הדבר מטרידו במיוחד. אבל מי שלא עירב עירוב תבשילין ואין לו כלל מה לאכול — שמא התירו לו חכמים.","ומציעים עוד, \u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 ראיה ממקום אחר: \u0003המטביל כליו בשבת\u0004 אף שאסרו חכמים להטביל כלי טמא ביום שבתון משום שבכך הוא כמתקנו, אם הטבילם \u0003בשוגג\u0004 — \u0003ישתמש בהן, במזיד\u0004 — \u0003לא ישתמש בהן.\u0004 הרי שכל שנעשה באיסור — אסור.","ודוחים: מכאן אין ראיה, \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא \u0003דאית ליה מאני אחריני\u0004 \u0005[שיש לו כלים אחרים]\u0006 ואינו מוכרח להשתמש דווקא באלה. \u0003אי נמי\u0004 \u0005[או גם כן],\u0006 \u0003אפשר בשאלה,\u0004 שהרי יכול לשאול כלים מאחרים. אבל מי שלא עשה עירוב תבשילין, כיון שקשה לקבל מזון מאחרים בשבת, יש אולי לומר שאם עבר ובישל ביום טוב לצורך השבת — מותר.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 ראיה אחרת, ממה ששנינו: \u0003המבשל בשבת,\u0004 אם \u0003בשוגג\u0004 בישל — \u0003יאכל, במזיד\u0004 — \u0003לא יאכל.\u0004 הרי הוכחה שהעבריין במזיד אסור לו ליהנות ממה שעשה! ודוחים: מכאן אין ראיה, \u0003אסורא\u0004 \u0005[איסור]\u0006 של חילול \u0003שבת\u0004 ממש, \u0003שאני\u0004 \u0005[שונה],\u0006 לפי שיש בו איסור כרת ומיתת בית דין, אבל אין זו הוכחה לגבי בישול ביום טוב. ואם כן לא נפתרה בעייתנו.","נאמר במשנה: \u0003בית שמאי אומרים\u0004 שעירוב תבשילין הוא דווקא ב\u0003שני תבשילין,\u0004 ובית הלל אומרים: אף באחד. ומעירים: \u0003מתניתין דלא כי האי תנא\u0004 \u0005[משנתנו אינה כשיטת תנא זה]\u0006 השנויה בתוספתא, \u0003אמר ר' שמעון בן אלעזר: מודים בית שמאי ובית הלל על שני תבשילין שצריך, על מה נחלקו\u0004 — \u0003על דג\u0004 מטוגן \u0003וביצה שעליו, שבית שמאי אומרים שני תבשילין\u0004 ממש צריך, ודג זה אינו נחשב כשנים. \u0003ובית הלל אומרים: תבשיל אחד\u0004 כגון זה, שיש בו שני דברים, נחשב כשנים וראוי לעירוב. \u0003ושוין\u0004 שניהן, \u0003שאם פרפר\u0004 (חתך) \u0003ביצה\u0004 מבושלת \u0003ונתן לתוך הדג, או שרסק קפלוטות\u0004 (מין כרישין, כרתי) \u0003ונתן לתוך הדג, שהן\u0004 נחשבים כ\u0003שני תבשילין.\u0004","\u0003אמר רבא: הלכתא כתנא דידן\u0004 \u0005[הלכה\u0006 כדעת \u0005התנא שלנו\u0006 במשנה\u0005],\u0006 \u0003ואליבא\u0004 \u0005[ועל פי שיטת]\u0006 \u0003בית הלל,\u0004 שדי בתבשיל אחד.","נאמר במשנה שאם \u0003אכלו\u0004 את מה שהכין כעירוב תבשילין, \u0003או שאבד\u0004 — \u0003הרי זה לא יבשל עליו\u0004 (מחמתו) ביום טוב לצורך השבת. \u0003אמר אביי: נקטינן\u0004 \u0005[מוחזקים אנו]\u0006 כי אם עשה עירוב תבשילין כדין, ו\u0003התחיל\u0004 ביום טוב ללוש את \u0003עיסתו\u0004 לצורך השבת \u0003ו\u0004בינתיים \u0003נאכל עירובו\u0004 — \u0003גומר\u0004 ואופה את הפת, שכיון שהתחיל בהיתר — התירו לו אף לסיים ולאפותה.","\u0003חל\u0004 החג \u0003להיות אחר השבת\u0004 (ביום ראשון) ורוצה אדם לנהוג כהלכה ולטהר עצמו וכליו לכבוד החג — \u0003בית שמאי אומרים: מטבילין את הכל מלפני השבת. ובית הלל אומרים: כלים\u0004 חייבים להטביל \u0003מלפני השבת, ואדם\u0004 עצמו יכול לטבול אפילו \u0003בשבת.\u0004","\u0003ושוין\u0004 בית שמאי ובית הלל בדעתם \u0003שמשיקין את המים בכלי אבן לטהרן.\u0004 שיש דרך לטהר מים טמאים על ידי שמכניסים אותם בתוך כלי שאינו מקבל טומאה (כגון בכלי אבן) ומכניסים את המים עם הכלי למקוה, וכאשר נוגעים המים הללו במי המקוה הרי הם נטהרים, ודבר זה אף שאינו נחשב כטבילה ממש, מכל מקום אפשר לטהרם כך. \u0003אבל לא מטבילין\u0004 את הכלים הטמאים לטהרם אגב השקת המים. וכן \u0003מטבילין\u0004 ביום טוב \u0003מגב לגב ומחבורה לחבורה\u0004 כאשר יבואר בגמרא.","\u0003דכולי עלמא מיהת\u0004 \u0005[לדעת הכל, על כל פנים]\u0006 \u0003כלי בשבת לא\u0004 מטבילים, ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]\u0006 שאסור להטביל כלי בשבת, וכי איזו מלאכה יש בכך? \u0003אמר רבה: גזרה\u0004 היא"],["\u0003שמא יטלנו\u0004 את הכלי הזה \u0003בידו, ויעבירנו ארבע אמות ברשות הרבים\u0004 למקום שיש בו מקוה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 ומי \u0003שיש לו בור\u0004 של מקוה מים \u0003בחצירו, מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה: \u0003גזירה\u0004 גזרו חכמים לאסור להטביל כלי אף ב\u0003בור\u0004 מים הקיים \u0003בחצירו, אטו\u0004 \u0005[משום]\u0006 \u0003בור\u0004 הקיים \u0003ברשות הרבים.\u0004","הקשה לו עוד: \u0003התינח\u0004 \u0005[נניח]\u0006 שגוזרים גזירה זו \u0003בשבת,\u0004 אולם \u0003ביום טוב\u0004 שאין בו איסור הוצאה מרשות לרשות, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 והשיב: \u0003גזרו\u0004 אף ב\u0003יום טוב אטו\u0004 \u0005[משום]\u0006 \u0003שבת.\u0004","ושואלים: \u0003ומי גזרינן\u0004 \u0005[האם גוזרים אנו]\u0006 בכגון אלה? \u0003והא תנן\u0004 \u0005[והרי שנינו]\u0006 במשנתנו: \u0003ושוין\u0004 בית שמאי ובית הלל \u0003שמשיקין את המים\u0004 הטמאים \u0003בכלי אבן\u0004 כדי \u0003לטהרן, אבל לא מטבילין\u0004 אותם בעצמם. \u0003ואי איתא\u0004 \u0005[ואם יש]\u0006 מקום לומר שגוזרים — \u0003נגזור\u0004 אם כן גם שם \u0003השקה אטו\u0004 \u0005[משום]\u0006 \u0003הטבלה!\u0004","את הקושיה הזו דוחים: \u0003ותסברא\u0004 \u0005[וכי יכול אתה לסבור]\u0006 שיש ממש בקושיה זו? הלא \u0003אי אית ליה\u0004 \u0005[אם יש לו]\u0006 לאותו אדם \u0003מים יפים\u0004 לשתיה, \u0003הני\u0004 \u0005[אלה]\u0006 המים הטמאים \u0003למה לי\u0004 (לו) \u0003למעבד להו\u0004 \u0005[לעשות להם]\u0006 \u0003השקה? אלא\u0004 על כרחך, עליך לומר \u0003דלית ליה\u0004 \u0005[שאין לו]\u0006 מים טובים לשתיה, \u0003וכיון דלית ליה\u0004 \u0005[שאין לו]\u0006 \u0003— מזהר זהיר בהו\u0004 \u0005[הוא זהיר בהם]\u0006 שלא יטמאו. ואם כן בהכרח עלינו לפרש שמדובר כאן במקרה יוצא דופן, שעל אף הזהירות נטמאו המים, ובמקרה כגון זה לא גזרו חכמים.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 אביי: \u0003מדלין\u0004 (דולין מים) \u0003בדלי טמא\u0004 מתוך מעין או מקוה מים, \u0003והוא\u0004 הדלי נעשה על ידי כך \u0003טהור,\u0004 שהרי תוך שדלה מים גם הוטבל הדלי במקוה, \u0003ואי איתא\u0004 \u0005[ואם יש]\u0006 מקום לגזור, אם כן \u0003נגזור דלמא אתי לאטבוליה בעיניה\u0004 \u0005[שמא יבוא להטבילו בעינו,\u0006 בעצמו\u0005]!\u0006 והשיב רבה: \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 \u0003מתוך שלא הותרה לו\u0004 טבילת הדלי סתם \u0003אלא על ידי דליו\u0004 (בדרך דליית מים) — \u0003זכור הוא\u0004 שאסור להטביל כלים, ואין לגזור בכך.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 ממקור אחר, ששנינו: \u0003כלי שנטמא מערב יום טוב\u0004 — \u0003אין מטבילין אותו ביום טוב,\u0004 אבל כלי שנטמא \u0003ביום טוב\u0004 עצמו — \u0003מטבילין אותו ביום טוב. ואם איתא\u0004 \u0005[יש]\u0006 מקום לגזירות בענין זה \u0003נגזור\u0004 בכלי שנטמא ב\u0003יום טוב אטו\u0004 \u0005[משום]\u0006 כלי שנטמא ב\u0003ערב יום טוב!\u0004 ומשיבים: \u0003טומאה ביום טוב\u0004 עצמו, שהכל טהורים בו, \u0003מלתא דלא שכיחא היא\u0004 \u0005[דבר שאינו מצוי הוא]\u0006 וכלל בידינו: \u0003מלתא דלא שכיחא\u0004 \u0005[דבר שאינו מצוי]\u0006 \u0003לא גזרו בה רבנן\u0004 \u0005[חכמים].\u0006","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 ממה ששנינו: \u0003כלי שנטמא באב הטומאה\u0004 — \u0003אין מטבילין אותו ביום טוב,\u0004 אולם אם נטמא רק \u0003בולד הטומאה,\u0004 כלומר, שנגע הכלי בדבר שנטמא על ידי אב הטומאה (שהוא ראשון לטומאה), ונעשה איפוא \"שני לטומאה\" וטומאה זו בכלים אינה אלא מדברי סופרים — \u0003מטבילין אותו ביום טוב. ואם איתא\u0004 \u0005[יש]\u0006 מקום לגזור, אם כן \u0003נגזור הא\u0004 \u0005[זה]\u0006 שנטמא בולד הטומאה \u0003אטו הא\u0004 \u0005[משום זה]\u0006 שנטמא באב הטומאה!","והשיב לו: כל שנטמא ב\u0003ולד הטומאה היכי משכחת לה\u0004 \u0005[היכן מוצא אתה]\u0006 שהאנשים מקפידים לטהרו, רק באופן אחד — \u0003גבי\u0004 \u0005[כהנים]\u0006 \u0003כהנים,\u0004 כיון שהם אוכלים תרומה, והתרומה נטמאת גם על ידי כלי שנטמא רק מולד הטומאה. אבל סתם אדם האוכל חולין אינו חושש לטהר כלי כזה לפי שאין חולין נטמאים אלא מולד הטומאה עצמו ולא משני לטומאה, וכיון שמדובר בכהנים — \u0003כלל בידינו כי\u0004 — \u0003כהנים זריזין הן\u0004 ונזהרים מאד שלא יבואו כליהם לידי טומאה, ולכך טומאה זו נחשבת אצלם כדבר שאינו מצוי ולא גזרו חכמים בכגון זה.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת, ממה ש\u0003אמר רב חייא בר אשי אמר רב: נדה שאין לה בגדים\u0004 טהורים ללובשם, שכל בגדיה נטמאו, ואותו יום שבת או יום טוב הוא, ואין היא יכולה להטבילם —הריהי \u0003מערמת\u0004 (מערימה) \u0003וטובלת בבגדיה,\u0004 שהרי היא עצמה מותרת לטבול, וכשהיא טובלת בבגדיה נטהרים בכך אף בגדיה. \u0003ואם איתא\u0004 \u0005[יש]\u0006 מקום לגזור, \u0003נגזור\u0004 אם כן \u0003דלמא אתי לאטבולי בעינייהו\u0004 \u0005[שמא תבוא להטביל\u0006 את הבגדים \u0005בעצמם]!\u0006","ומשיבים: \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 \u0003מתוך שלא הותרה לה\u0004 הטבלת הבגדים \u0003אלא על ידי\u0004 באופן שהם נתונים עליה בתור \u0003מלבוש\u0004 — \u0003זכורה היא\u0004 ואינה באה לכלל איסור. עד כאן נשאנו ונתנו בטעמו של רבה שהאיסור בהטבלת כלים בשבת הוא גזירה שמא יבוא לטלטל ברשות הרבים.","ואילו \u0003רב יוסף אמר\u0004 טעם אחר: אין מטבילים כלים בשבת, \u0003גזרה משום סחיטה.\u0004 שכלים שונים, כגון בגדים, לאחר שמטבילים אותם, יש לחשוש שמא יבוא לסוחטם, וסחיטה אסורה משום תולדה של מלאכה האסורה מן התורה (דש).","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: תינח\u0004 \u0005[נניח]\u0006 \u0003בכלים\u0004 ש\u0003בני סחיטה נינהו\u0004 \u0005[הם],\u0006 כגון בגדים, אולם \u0003כלים דלאו\u0004 \u0005[שלא]\u0006 \u0003בני סחיטה נינהו\u0004 \u0005[הם],\u0006 \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף: \u0003גזרה\u0004 גזרו חכמים ב\u0003הני\u0004 \u0005[ב\u0006כלים \u0005אלה]\u0006 שאינם בני סחיטה, \u0003אטו הני\u0004 \u0005[משום\u0006 כלים \u0005אלה]\u0006 שהם בני סחיטה. \u0003איתיביה כל הני תיובתא ושני ליה כדשנינן\u0004 \u0005[הקשה לו\u0006 אביי לרב יוסף \u0005כל אותן הקושיות\u0006 שהקשה לרבה להוכיח שאין גוזרים \u0005ותירץ לו כפי שתירצנו]\u0006 בשם רבה.","\u0003רב ביבי אמר\u0004 טעם אחר: \u0003גזרה שמא ישהא.\u0004 שאם יתירו לו להטביל כלים ביום טוב, יש לחשוש שמא ישהה את כל הכלים הטמאים וימתין עד ליום טוב, שאז זמנו פנוי, ואז יטביל אותם. וכיון שישארו ברשותו כלים טמאים למשך זמן רב יש לחשוש שמא יגרום הדבר לטמא דברים שאסור לטמאם, כגון תרומה. ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רב ביבי: כלי שנטמא מערב יום טוב\u0004 — \u0003אין מטבילין אותו ביום טוב, גזרה שמא ישהא\u0004 בביתו כלים טמאים כדי להטבילם ביום טוב.","\u0003רבא אמר\u0004 טעם אחר: אין טובלים כלי בשבת \u0003מפני שנראה\u0004 על ידי הטבילה \u0003כמתקן\u0004 את ה\u0003כלי,\u0004 שהרי קודם לכן לא היה הכלי ראוי לשימוש ולאחר שהטבילו נעשה ראוי, ודומה הדבר למלאכת תיקון כלי האסורה מן התורה. ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003אדם נמי\u0004 \u0005[גם כן]\u0006 ייאסר לטבול, משום שנראה כמתקן עצמו! ומשיבים: \u0003אדם נראה כמיקר,\u0004 שאינו נראה בוודאות שהוא טובל לטהרתו שהרי יתכן שטובל במים משום שרוצה לקרר את עצמו, ולכן אין לגזור בו.","ומקשים: \u0003הא תינח\u0004 \u0005[זה נוח]\u0006 לגבי טבילה ב\u0003מים יפים\u0004 ונקיים שנעים לו לאדם להצטנן בתוכם, אולם אם טובל ב\u0003מים רעים,\u0004 שלפעמים מי המקוה אינם נקיים כל צרכם, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 \u0003אמר רב נחמן בר יצחק:\u0004 גם אז אין מעשהו מוכיח שכוונתו לטהרה, שהרי \u0003פעמים שאדם בא\u0004"],["\u0003בשרב\u0004 (ביום חום) \u0003ורוחץ\u0004 עצמו \u0003אפילו במי משרה\u0004 (מים שבהם שרו את הפשתן) שהם מסריחים ביותר, לפי שהחום מציק לו.","ומוסיפים להקשות: \u0003תינח\u0004 (נניח) \u0003בימות החמה,\u0004 אולם \u0003בימות הגשמים\u0004 שאין נוהגים לרחוץ במים כדי להצטנן, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 \u0003אמר רב נחמן בר יצחק: פעמים שאדם בא מן השדה\u0004 כשהוא \u0003מלוכלך בטיט ובצואה ורוחץ אפילו בימות הגשמים.\u0004","ומקשים: \u0003תינח\u0004 \u0005[נניח\u0006 כל זה\u0005]\u0006 \u0003בשבת,\u0004 יום שבו מותר לרחוץ, ולכן אפשר לומר שאין טבילתו ניכרת כתיקון עצמו בטבילה, אולם \u0003ביום הכפורים\u0004 שאסורה בו כל רחיצה, ומותרת טבילת מצוה, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 שהרי מעשיו מוכיחים שהתכוין לטבילה והריהו לכאורה כמתקן עצמו!","\u0003אמר רבא:\u0004 אין אפשרות לאסור טבילה ביום הכיפורים בלבד, כי \u0003מי איכא מידי\u0004 \u0005[האם יש דבר]\u0006 שנחשב כמלאכה ש\u0003בשבת שרי\u0004 \u0005[\u0006הוא \u0005מותר]\u0006 \u0003וביום הכפורים\u0004 אותו מעשה עצמו \u0003אסור,\u0004 שהרי איסור מלאכה בשבת חמור מאיסור מלאכה ביום הכיפורים? \u0003אלא הואיל ובשבת שרי\u0004 \u0005[מותר]\u0006 — \u0003ביום הכפורים נמי שרי\u0004 \u0005[גם כן מותר].\u0006 שלא גזרו חכמים איסור ביום הכיפורים באופן שתהא בו חומרה יותר מבשבת. ומתוך שהתירו לאדם לטבול בשבת משום שנראה שרוחץ מפני החום או מחמת הזוהמה ולא דווקא כטובל לטהרה, כך לא אסרוה ביום הכיפורים, אף שודאי ניכר שטובל לטהרתו.","ותוהים: \u0003ומי אית ליה\u0004 \u0005[והאם יש לו]\u0006 \u0003לרבא,\u0004 האם הוא מקבל את הנימוק של \u0003\"הואיל\"? והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003החושש\u0004 (סובל כאב) \u0003בשיניו\u0004 — \u0003לא יגמע בהן את החומץ,\u0004 שנחשב למועיל לריפוי השיניים, \u0003אבל מטבל הוא\u0004 לחם בחומץ \u0003כדרכו\u0004 בשעת אכילה \u0003ואם נתרפא\u0004 על ידי החומץ שבלחם — \u0003נתרפא,\u0004 לפי שאין עושים דברים לשם רפואה בשבת. \u0003ורמינן עלה\u0004 \u0005[והשלכנו,\u0006 הראנו סתירה \u0005על\u0006 משנה \u0005זו]\u0006 ממקום אחר, ששנינו: \u0003לא יגמע\u0004 חומץ \u0003ופולט\u0004 אותו מיד לאחר מכן, שאז מוכח שעושה זאת לרפואה בלבד, \u0003אבל מגמע\u0004 חומץ \u0003ובולע,\u0004 שנראה כשותה, ומותר גם אם לא עשה בדרך טיבול!","\u0003ואמר אביי: כי תנן נמי מתניתין\u0004 \u0005[כאשר שנינו גם כן במשנתנו]\u0006 לאסור שתיית חומץ, הכוונה היא ל\u0003מגמע ופולט\u0004 דווקא. \u0003ורבא אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 שמדובר כשהיה \u0003מגמע ובולע, ולא קשיא\u0004 \u0005[ואינו קשה];\u0006 \u0003כאן\u0004 שהותר לו לגמוע חומץ, מדובר שעושה כן \u0003קודם טבול, כאן\u0004 שנאסר עליו לגמוע חומץ, מדובר \u0003לאחר טבול,\u0004 שהרי אז ניכר שאינו תאב עוד לחומץ לשתיה, אלא כדי להתרפא.","\u0003ואם איתא\u0004 \u0005[יש]\u0006 מקום לסברה זו של \"הואיל\", \u0003נימא\u0004 \u0005[שיאמר]:\u0006 \u0003הואיל וקודם טבול שרי\u0004 \u0005[מותר]\u0006 לגמוע חומץ — \u0003לאחר טבול נמי שרי\u0004 \u0005[גם כן מותר]!\u0006 ומשיבים: \u0003הדר ביה\u0004 \u0005[חזר בו]\u0006 \u0003רבא מ\u0004שיטתו \u0003ההיא\u0004 לענין חומץ, והוא מפרש כאביי, ואף הוא מקבל את נימוק \"הואיל\".","ושואלים: \u0003וממאי דמההיא הדר ביה, דלמא מהא הדר ביה\u0004 \u0005[ומנין שמההיא חזר בו, שמא מזו\u0006 לענין יום כיפור \u0005חזר בו]?\u0006 ומשיבים: \u0003לא סלקא דעתך\u0004 \u0005[יעלה על דעתך]\u0006 שמזו חזר, \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003כל חייבי טבילות טובלין כדרכן, בין בתשעה באב בין ביום הכפורים,\u0004 אף שנאסרה בהם הרחיצה. וכיון שכך, ודאי התאים שיטתו לדברי הברייתא המפורשים.","שנינו במשנה: \u0003ושוין\u0004 בית שמאי ובית הלל \u0003שמשיקין את המים בכלי אבן\u0004 כדי לטהרם, אבל אין מטבילים. ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אבל לא מטבילין\"\u0004 שנאמר במשנה? \u0003אמר שמואל: אין מטבילין את הכלי\u0004 הטמא \u0003על גב\u0004 (אגב) \u0003מימיו לטהרו ביום טוב!\u0004 שלא התירו הטבלת —השקת מים אלא בכלי אבן וכיוצא בו שאינו מקבל טומאה, אבל לא בכלי טמא הנטהר על ידי הטבלה זו.","ושואלים: אם כן אתה מפרש, \u0003מני מתניתין\u0004 \u0005[\u0006לפי זה כשיטת \u0005מי היא משנתנו\u0006 זו\u0005]?\u0006 — \u0003לא\u0004 כדעת \u0003רבי ולא\u0004 כדעת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בתוספתא]: \u0003אין מטבילין את הכלי על גב מימיו\u0004 כדי \u0003לטהרו ואין משיקין את המים בכלי אבן\u0004 כדי \u0003לטהרן,\u0004 אלו \u0003דברי רבי. וחכמים אומרים: מטבילין כלי על גב מימיו\u0004 כדי \u0003לטהרו, ומשיקין את המים בכלי אבן\u0004 כדי \u0003לטהרן.\u0004","ואם כן, משנתנו \u0003מני\u0004 \u0005[\u0006של \u0005מי היא]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 תאמר שהיא כשיטת \u0003רבי — קשיא\u0004 \u0005[קשה]\u0006 מענין \u0003השקה,\u0004 ששיטת רבי בתוספתא לאסור אף השקה ובמשנה שנינו שהיא מותרת, \u0003אי רבנן\u0004 \u0005[אם\u0006 כשיטת \u0005חכמים],\u0006 \u0003קשיא\u0004 \u0005[קשה]\u0006 מענין \u0003הטבלה\u0004 שבמשנתנו, שפירש שמואל שהיא אסורה ואילו דעת חכמים בתוספתא להתיר!","ומשיבים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 שהוא כשיטת \u0003רבי, איבעית אימא רבנן\u0004 \u0005[אם תרצה אמור\u0006 שהוא כשיטת \u0005חכמים].\u0006 כיצד? \u0003אי בעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 שמשנתנו כשיטת \u0003רבי,\u0004 אלא \u0003רישא\u0004 \u0005[ראשה]\u0006 של אותה \u0003ברייתא,\u0004 כלומר, בתחילת דברי רבי בתוספתא, מדובר \u0003ביום טוב\u0004 ובזו אמר שאין מטבילים את הכלי על גב מימיו לטהרו, אבל השקה תהיה אכן מותרת, \u0003וסיפא\u0004 \u0005[וסופה]\u0006 שאסר גם בהשקה מדובר \u0003בשבת\u0004 שחמורים איסוריה. \u0003ו\u0004אילו \u0003כולה מתניתין\u0004 \u0005[כל משנתנו]\u0006 מדברת \u0003ב\u0004ענין \u0003יום טוב,\u0004 שביום טוב מותר להשיק את המים לטהרם."],["\u0003ואיבעית אימא רבנן\u0004 \u0005[ואם תרצה אמור\u0006 שמשנתנו \u0005כשיטת חכמים\u0006 היא\u0005]\u0006 וביום טוב מותר אף להטביל, \u0003וכולה מתניתין\u0004 \u0005[וכל משנתנו]\u0006 היא \u0003בשבת\u0004 ובשבת לדעתם אסור להטביל, אף כי מותר להשיק.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כלי שנטמא מערב יום טוב\u0004 — \u0003אין מטבילין אותו בין השמשות\u0004 בשעת הדמדומים בסוף היום שהוא ספק חול ספק יום טוב, מפני ספק איסור טבילת כלי בחג.","\u0003ר' שמעון שזורי אומר: אף בחול אין מטבילין אותו\u0004 בשעה זו \u0003מפני שצריך\u0004 הכלי \u0003הערב שמש.\u0004 כי כלי שנטמא והוטבל, נטהר רק לאחר השקיעה ביום הטבילה, ובמקרה זה צריך להמתין עוד יום שלם, עד שיעריב שמשו של יום המחרת. ואם מטבילו בין השמשות — מן הסתם כוונתו שמיד יטהר הכלי ויוכל להשתמש בו, ומאחר שבין השמשות הוא ספק לילה, לכך צריך יהיה להמתין מספק עוד יום אחד, ומוטב שלא יבוא לחשש שימוש בכלי קודם טהרתו.","ושואלים: \u0003ו\u0004כי ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 \u0003לא בעי\u0004 \u0005[צריך]\u0006 שיהיה \u0003הערב שמש?\u0004 הלא ברור שצריך! \u0003אמר רבא: אשכחתינהו לרבנן דבי\u0004 \u0005[מצאתי את החכמים של בית]\u0006 מדרשו של \u0003רב דיתבי וקא אמרי\u0004 \u0005[שיושבים ואומרים]\u0006 באותו נושא, ש\u0003ב\u0004בעיה האם מקבלים את העיקרון ש\u0003מחשבתו\u0004 של אדם \u0003נכרת מתוך מעשיו\u0004 או לא, \u0003קמפלגי\u0004 \u0005[חלוקים הם].\u0006 \u0003והיכי דמי\u0004 \u0005[וכיצד בדיוק הדבר]\u0006 — \u0003כגון דנקיט מנא בידיה ורהיט ואזיל\u0004 \u0005[שהוא מחזיק כלי בידו ורץ והולך]\u0006 \u0003בין השמשות לאטבוליה\u0004 \u0005[להטבילו].\u0006","\u0003מר\u0004 \u0005[חכם\u0006 זה, חכמים\u0005]\u0006 \u0003סבר: האי דקא רהיט ואזיל\u0004 \u0005[זה שהוא רץ והולך]\u0006 — \u0003מידע ידע דבעי\u0004 \u0005[יודע הוא שצריך]\u0006 \u0003הערב שמש,\u0004 ואם מגיע לטבול בשעה מאוחרת יותר יודע הוא שצריך להמתין יום נוסף, ואין חוששים שישתמש בכלי בו ביום. ולכן, בבין השמשות של ערב יום טוב, כיון שלא יוכל להשתמש בכלי הזה אלא למחרת, הרי שהטבלתו היום שלא לצורך היא וכהכנה מיום טוב לחול היא ואסורה, אבל אם מטבילו ביום חול — מותר.","\u0003ומר\u0004 \u0005[וחכם\u0006 זה, ר' שמעון שזורי\u0005]\u0006 \u0003סבר:\u0004 אינו כן, אלא \u0003מחמת מלאכתו\u0004 שלא הספיק לעשות דברים בזמנם \u0003הוא דקרהיט\u0004 \u0005[שרץ]\u0006 ואינו יודע שצריך הערב שמש, וחושב שיוכל להשתמש בו מיד, ולכן גזרו שלא יטביל כלל בין השמשות.","\u0003ואמינא להו אנא\u0004 \u0005[ואמרתי אני,\u0006 רבא, \u0005להם]:\u0006 \u0003במחשבתו נכרת מתוך מעשיו — דכולי עלמא לא פליגי\u0004 \u0005[הכל אינם חלוקים]\u0006 שאפשר לסמוך על כך. \u0003כי פליגי\u0004 \u0005[כאשר נחלקו];\u0006 \u0003כגון דאיטמי\u0004 \u0005[שנטמא]\u0006 אצל אותו אדם כלי \u0003ב\u0004שרץ שהוא \u0003פחות מ\u0004שיעור \u0003כעדשה, ואתא לקמיה דרבנן לשיולי\u0004 \u0005[ובא\u0006 אותו אדם \u0005לפני חכמים לשאול]\u0006 האם \u0003בפחות מכעדשה איטמי\u0004 \u0005[נטמא]\u0006 הכלי \u0003אי\u0004 \u0005[או]\u0006 \u0003לא? מר\u0004 \u0005[חכם\u0006 זה, ר' שמעון שזורי\u0005]\u0006 \u0003סבר: מדהא\u0004 \u0005[כיון ש\u0006דבר \u0005זה]\u0006 שאין שרץ מטמא בפחות מכעדשה \u0003לא גמיר\u0004 \u0005[למד]\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 דין \u0003הערב שמש, נמי\u0004 \u0005[גם כן]\u0006 \u0003לא גמיר\u0004 \u0005[למד]\u0006 ולכך יש לאסור עליו אף ביום חול, \u0003ומר\u0004 \u0005[וחכם\u0006 זה, חכמים המתירים ביום חול\u0005]\u0006 \u0003סבר: הא\u0004 \u0005[\u0006דבר \u0005זה\u0006] לגבי שיעור כעדשה \u0003הוא\u0004 ש\u0003לא גמיר\u0004 \u0005[שלא למד],\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 דין \u0003הערב שמש גמיר\u0004 \u0005[למד],\u0006 שהרי דין זה מפורש בתורה.","שנינו במשנה ש\u0003מטבילין\u0004 ביום טוב \u0003מגב לגב\u0004 ומחבורה לחבורה. פירוש הדברים הללו לא היה ברור, ועל כן מסבירים: \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כיצד מגב לגב? הרוצה לעשות גתו,\u0004 כלומר, לתקן ולהטביל לצורך הגת, \u0003על גב\u0004 (אגב) טיהור \u0003כדו\u0004 הטמא, שמתחילה חשב להטביל את כדו הטמא ונמלך בדעתו לעשות את גתו ומתוך חשש רוצה להטביל שנית לצורך הגת, או לעשות","\u0003כדו על גב גתו,\u0004 שרצה לעשות גתו ובתוך כך נמלך וטבל אגב זה את כדו ומתוך שמסתפק אם עשה כדין, רוצה להטביל בשנית — \u0003עושה.\u0004 שכיון שהטבילה בשנית אינה מטהרת ואין בה משום חובה — אינה נחשבת כטבילה, ולפיכך לא גזרו בה איסור אף ביום טוב.","וכן \u0003כיצד מחבורה לחבורה? היה אוכל בחבורה זו\u0004 של עושי קרבן פסח והיה טמא וטבל לטהרתו, או שהיו כליו טמאים והטבילם לדעת כן, ונמלך בדעתו \u0003ורוצה לאכול בחבורה אחרת\u0004 ורצונו בשל כך לטבול או להטביל כליו מחדש לשם החבורה השניה — \u0003הרשות בידו\u0004 אף בחג, ואין גוזרים איסור על כך, שהרי אינו חייב בטבילה זו מעיקר הדין ולפיכך אינה נחשבת כטבילה.","\u0003בית שמאי אומרים: מביאין שלמים\u0004 לקרבן ביום טוב \u0003ואין סומכין עליהן,\u0004 כי הסמיכה יש בה משום עבודה בבעלי חיים, וזו אסורה ביום טוב משום שבות. \u0003אבל לא\u0004 מביאים \u0003עולות\u0004 נדבה פרט לאלה הקבועות (כגון תמידים ומוספים), לפי שהעולות אינן נאכלות לאדם, ואסור לשחוט שחיטה שאינה צריכה לאכילה של אדם. \u0003ובית הלל אומרים: מביאין שלמים ו\u0004גם \u0003עולות, ו\u0004אף \u0003סומכין עליהן.\u0004","\u0003אמר עולא: מחלוקת\u0004 זו היא \u0003בשלמי חגיגה\u0004 (שחובה להביאם בחג) רק לענין \u0003לסמוך\u0004 עליהם, אבל לענין הבאתם למקדש אף בית שמאי מודים שמותר, שהרי הן מחובת היום, \u0003ובעולת ראייה\u0004 (שחובה להקריבה בימות הרגל), המחלוקת לענין \u0003ליקרב,\u0004 כלומר, אם הותרה הבאתם כלל הבאתם למקדש. ש\u0003בית שמאי סברי\u0004 \u0005[סבורים],\u0006 שמדברי הכתוב \u0003\"וחגתם אתו חג לה'\u0004 שבעת ימים בשנה\" (ויקרא כג, מא) יש לדייק: \u0003חגיגה\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 יש להביא, אולם \u0003עולת ראיה\u0004 — \u0003לא. ובית הלל סברי\u0004 \u0005[סבורים]:\u0006 \u0003\"לה'\"\u0004 — \u0003כל\u0004 דבר שהוא קרבן \u0003לה'\u0004 מותר להביאו כל ימי החג, ואף ביום טוב עצמו.","\u0003אבל נדרים ונדבות\u0004 שאינם חובת היום — \u0003דברי הכל אין קרבין\u0004 (אין מביאים אותם) \u0003ביום טוב,\u0004 אפילו לדעת בית הלל. \u0003וכן אמר רב אדא בר אהבה: נדרים ונדבות אין קריבין ביום טוב.\u0004","\u0003מתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]:\u0006 \u0003אמר ר' שמעון בן אלעזר, לא נחלקו בית שמאי ובית הלל על עולה שאינה של יום טוב,\u0004 כנדר או נדבה — \u0003שאינה קריבה ביום טוב, ועל שלמים שהן של יום טוב,\u0004 כחגיגה או שלמי שמחה — \u0003שקרבין ביום טוב,\u0004 שהרי יום טוב הוא זמנם המיוחד, ואם לא יביאום, מתוך שעבר זמנו — בטל קרבנו.","\u0003על מה נחלקו\u0004 — \u0003על עולה שהיא של יום טוב,\u0004 כתמידים ומוספים, \u0003ועל שלמים שאינן של יום טוב,\u0004 כנדרים ונדבות. \u0003שבית שמאי אומרים: לא יביא, ובית הלל אומרים: יביא.\u0004 ושיטה זו נוגדת את דברי עולא שאמר כי נדרים ונדבות אינם קרבים בחג לדעת הכל!","ומשיבים: \u0003תריץ ואימא הכי\u0004 \u0005[ישב,\u0006 תקן, \u0005ואמור כך]:\u0006 \u0003אמר ר' שמעון בן אלעזר, לא נחלקו בית שמאי ובית הלל על עולה ושלמים שאינן של יום טוב\u0004 כנדרים ונדבות, שבודאי \u0003אין קרבין ביום טוב, ועל שלמים שהן של יום טוב,\u0004 כחגיגה ושמחה \u0003שקרבין ביום טוב. על מה נחלקו\u0004 — \u0003על עולה שהיא של יום טוב,\u0004 כתמידים ומוספים \u0003שבית שמאי אומרים: לא יביא, ובית הלל אומרים: יביא.\u0004","\u0003רב יוסף אמר:\u0004 זו אינה קושיה מעיקרה, וכי \u0003תנאי שקלת מעלמא\u0004 \u0005[האם את התנאים הוצאת מן העולם]?!\u0006 \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא\u0004 ודעת ר' שמעון בן אלעזר לא דעת הכל היא. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא אחרת\u0005]:\u0006 \u0003שלמים הבאים מחמת יום טוב ביום טוב,\u0004 כחגיגה ושמחה, \u0003בית שמאי אומרים: סומך עליהן מערב יום טוב, ושוחטן ביום טוב. ובית הלל אומרים: סומך עליהן ביום טוב\u0004 עצמו \u0003ושוחטן ביום טוב.\u0004"],["\u0003אבל נדרים ונדבות\u0004 — \u0003דברי הכל אין קרבין ביום טוב\u0004 ממש כדעת עולא ורב אדא בר אהבה.","ומעירים: \u0003והני תנאי כהני תנאי\u0004 \u0005[ותנאים אלה\u0006 שנחלקו בדבר הם \u0005כתנאים אחרים]\u0006 שנחלקו כבר בו. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אין מביאין\u0004 קרבן \u0003תודה בחג המצות, מפני חמץ שבה\u0004 שהרי יש בקרבן התודה גם חלות חמץ ואלה אסור לאוכלן בפסח. \u0003ולא\u0004 מביאים קרבן תודה \u0003בעצרת\u0004 (שבועות) — \u0003מפני שהוא יום טוב,\u0004 וביום טוב אסור להקריב כל קרבן (אפילו קרבן נאכל) שאינו מחובת החג. \u0003אבל מביא אדם תודתו בחג הסוכות\u0004 בימי חול המועד.","\u0003ר' שמעון אומר: הרי הוא אומר \"בחג המצות ובחג השבעות ובחג הסכות\"\u0004 (דברים טז, טז) ללמדנו: \u0003כל\u0004 קרבן \u0003שבא בחג המצות\u0004 — \u0003בא בחג השבועות ובחג הסוכות, וכל שלא בא בחג המצות אינו בא\u0004 גם \u0003בחג השבועות ו\u0004גם \u0003בחג הסוכות. ר' אלעזר בר' שמעון אומר: מביא אדם תודתו בחג הסוכות, ויוצא בה ידי חובתו משום שמחה,\u0004 שהרי יש מצות שמחה בחג, ושמחה זו באכילת בשר הקרבנות היא, ויכול לצאת ידי חובה זו בקרבן תודה. אבל \u0003ואין יוצא\u0004 בתודה \u0003משום\u0004 חובת הבאת קרבן \u0003חגיגה.\u0004","מעתה מבררים את דברי הברייתא, \u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא: \u0003אין מביאין תודה בחג המצות מפני חמץ שבה.\u0004 ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 הלא חמץ הוא, והחמץ אסור בפסח! \u0003אמר רב אדא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יצחק, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב שמואל בר אבא: הכא\u0004 \u0005[כאן]\u0006 \u0003בארבעה עשר\u0004 בניסן \u0003עסקינן\u0004 \u0005[עוסקים אנו]\u0006 \u0003וקסבר\u0004 \u0005[וסבור]\u0006 אותו חכם ש\u0003אין מביאין קדשים לבית הפסול.\u0004 שהרי בערב הפסח עצמו מותר החמץ באכילה רק בשעות הבוקר הראשונות, ומחצי היום ואילך הוא אסור, וכיון שזמן אכילת קרבן תודה ולחמיו הוא יום ולילה, ובמקרה מסויים זה יש לבער את הלחם קודם לכן — \u0003נמצא שהוא מקרב את שעת הפסול של לחמי הקרבן, ואסור להביא קדשים למצב שבו יפסלו.\u0004","עוד שנינו בברייתא: \u0003ולא בעצרת מפני שהוא יום טוב.\u0004 ומסבירים: \u0003קסבר\u0004 \u0005[סבור]\u0006 תנא זה: \u0003נדרים ונדבות אין קרבין ביום טוב.\u0004","עוד שנינו בברייתא\u0003: אבל מביא אדם תודתו בחג הסוכות,\u0004 ושואלים: \u0003אימת\u0004 \u0005[מתי]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שמביאה \u0003ביום טוב\u0004 של סוכות \u0003עצמו — והא אמרת\u0004 \u0005[והרי אמרת]:\u0006 \u0003ולא בעצרת מפני שהוא יום טוב,\u0004 הרי שאין מביאים קרבן תודה ביום טוב עצמו, והוא הדין אם כן לחג הסוכות! \u0003אלא\u0004 יש לפרש שמביא \u0003בחולו של מועד.\u0004","עוד שנינו בברייתא, ש\u0003ר' שמעון אומר: הרי הוא אומר: \"בחג המצות ובחג השבועות ובחג הסוכות\"\u0004 — \u0003כל שבא בחג המצות\u0004 — \u0003בא בחג השבועות ובחג הסוכות, וכל שלא בא בחג המצות\u0004 — \u0003אינו בא בחג השבועות ובחג הסוכות.\u0004 ולכאורה נובע מדבריו שאסור להביא קרבן תודה בכל חג. \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003ר' זירא: השתא סלתי\u0004 \u0005[הרי לקצוץ]\u0006 עצים לצורך חול המועד בחול המועד עצמו \u0003מסלתינן\u0004 \u0005[אנו קוצצים],\u0006 ואם כן \u0003נדרים ונדבות מבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]\u0006 שמותר להקריבם בחול המועד? וכיצד אפשר לומר שר' שמעון אוסר הבאת קרבן תודה בחול המועד של סוכות?!","\u0003אמר אביי: בהקרבה\u0004 של קרבנות אלה בחול המועד \u0003— כולי עלמא לא פליגי דשרי\u0004 \u0005[הכל אינם חלוקים שמותר].\u0006 \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 היה זה לא לענין דיני יום טוב כלל, אלא לשאלה \u0003למיקם עליה\u0004 \u0005[לעמוד,\u0006 לעבור \u0005עליו\u0006 על נדר\u0005]\u0006 משום \u0003\"בל תאחר\".\u0004 שאם נדר אדם להקריב קרבן ומתעכב מלהביאו, כמה זמן יעבור עד שיהיה עובר על האיסור של \"לא תאחר לשלמו\".","ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 \u0003סבר\u0004 ש\u0003שלש רגלים אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 \u0003אפילו שלא כסדרן\u0004 שהוא לפי חדשי השנה בתורה: פסח, שבועות, סוכות. ואם עברו שלושה רגלים כלשהם מיום שנדר ולא הביא את נדרו — הרי זה עובר משום בל תאחר. ולכך לדעת תנא קמא כדאי לנודר קרבן תודה להקדים ולהביאו בחג הסוכות אפילו שהוא הרגל הראשון הסמוך לזמן הנדר ואין זה כסדר ההרגלים האמור בתורה, שאם לא כן ייאלץ לבוא בשל כך לירושלים במיוחד. שהרי לא יוכל להקריבו בפסח משום הלחם שבו ולא בשבועות לפי שאין בו חול המועד,","\u0003ו\u0004אילו \u0003ר' שמעון סבר: כסדרן\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003שלא כסדרן\u0004 — \u0003לא.\u0004 ואם נדר למשל בין חג המצות לחג השבועות יכול להמתין עוד עד חג הסוכות של השנה הבאה ואינו צריך לבוא בשל כך באופן מיוחד.","עוד שנינו בברייתא כי \u0003ר' אלעזר בר' שמעון אומר: מביא אדם תודתו בחג הסוכות.\u0004 ושואלים: \u0003אימת\u0004 \u0005[מתי]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שכוונתו \u0003בחולו של מועד\u0004 — אם כן \u0003היינו\u0004 \u0005[זהו]\u0006 שיטת ה\u0003תנא קמא\u0004 \u0005[הראשון].\u0006 \u0003אלא\u0004 תפרש שכוונתו \u0003ביום טוב\u0004 עצמו, \u0003וקסבר\u0004 \u0005[וסבור הוא]\u0006 ש\u0003נדרים ונדבות קריבין ביום טוב.\u0004","ושואלים: אם כן \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 דווקא \u0003חג הסוכות דנקט\u0004 \u0005[ש\u0006אותו \u0005תפס],\u0006 כדוגמה? ומשיבים: \u0003ר' אלעזר בר' שמעון לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 ואף דבר זה קשור לדין \"בל תאחר\". \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' שמעון אומר: לא יאמר\u0004 הפסוק ויזכיר את \u0003\"חג הסוכות\" שבו\u0004 הרי \u0003הכתוב מדבר\u0004 קודם לכן באותה פרשה, ולא הוצרך להוסיף אלא רגלים אחרים, ואם כן \u0003למה נאמר\u0004 \"חג הסוכות\" — \u0003לומר שזה\u0004 חג הסוכות הוא \u0003אחרון\u0004 לענין \"בל תאחר\", שאין עובר אלא על שלושה רגלים כסדרם.","ואילו \u0003ר' אלעזר בר' שמעון אומר: לומר שזה גורם.\u0004 שלדעתו אין \"בל תאחר\" תלוי במספר הרגלים, אלא שבחג הסוכות שהוא אחרון הרגלים לפי סדר הזמנים שבתורה, חייב לסיים להביא את כל מה שנדר באותה שנה. ואפילו נדר סמוך לחג — זהו סוף הזמן לשלם נדרו.","שנינו באותה ברייתא: \u0003ויוצא בה\u0004 בקרבן תודה שמביא בחג, \u0003משום שמחה ואינו יוצא בה משום חגיגה.\u0004 ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 הלא קרבן חגיגה \u0003דבר שבחובה הוא\u0004 שחייב כל עולה לרגל להביאו, וכלל בידינו: \u0003כל דבר שבחובה אינו בא אלא מן החולין\u0004 ואינו יכול לצאת ידי חובה בקרבן תודה שהוא חובה עליו מסיבה אחרת, שהרי כבר הקדישו לתודה ואינו חולין!","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא \u0003דאף על גב דפריש\u0004 \u0005[שאף על פי שפירש]\u0006 בשעת נדרו שכוונתו להקדיש את תודתו בתנאי שייצא בה גם חובת קרבן חגיגה, בכל זאת אינו יוצא.","\u0003כדבעא מניה\u0004 \u0005[כפי ששאל]\u0006 \u0003ר' שמעון בן לקיש מר' יוחנן: האומר\u0004 בנדרו: \u0003הרי עלי תודה ואצא בה\u0004 גם \u0003ידי\u0004 חובת \u0003חגיגה,\u0004 או שאומר: \u0003הריני נזיר\u0004"],["\u0003ואגלח,\u0004 כלומר: אביא את קרבן הנזירות שמביאים בשעת תגלחת השערות \u0003ממעות מעשר שני\u0004 שממילא חייב אני להביאם לירושלים לאכלם שם ואקנה את קרבנותי מכספים אלה, \u0003מהו? אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן: לענין התודה \u0003נדור,\u0004 כלומר, חייב להביא תודה, אבל \u0003אינו יוצא\u0004 בה משום חגיגה, לפי שאין יוצאים בחגיגה אלא מן החולין. וכן מי שנדר בנזירות הרי זה \u0003נזיר ואינו מגלח\u0004 ממעות מעשר שני. כיון שהבאנו מקרה שאדם אומר דבר על תנאי, ואילו אנו מקבלים רק חלק מדבריוו, מסופר על מקרה הדומה קצת לזה.","\u0003ההוא גברא דאמר להו\u0004 \u0005[אדם אחד שאמר להם]\u0006 לעומדים עליו, בצוואה: \u0003הבו ליה\u0004 \u0005[תנו לו]\u0006 \u0003ארבע מאה\u0004 \u0005[מאות]\u0006 \u0003זוזי\u0004 \u0005[זוז]\u0006 \u0003לפלוני, ולנסיב ברתי\u0004 \u0005[ושישא את בתי\u0006 לאשה\u0005].\u0006 \u0003אמר רב פפא: ארבע מאה\u0004 \u0005[מאות]\u0006 — \u0003שקיל\u0004 \u0005[\u0006הוא \u0005נוטל],\u0006 \u0003וברתיה\u0004 \u0005[ואת בתו]\u0006 — \u0003אי בעי\u0004 \u0005[אם רוצה]\u0006 — \u0003נסיב\u0004 \u0005[ישא],\u0006 \u0003אי בעי\u0004 \u0005[אם רוצה]\u0006 — \u0003לא נסיב\u0004 \u0005[ישא].\u0006","מעירים: \u0003טעמא\u0004 \u0005[הטעם]\u0006 דווקא משום ש\u0003אמר\u0004 בלשון זו: \u0003הבו ליה\u0004 \u0005[תנו לו]\u0006 \u0003ולנסיב\u0004 \u0005[ושישא],\u0006 שהקדים את ענין המתנה לתנאי, \u0003אבל אי\u0004 \u0005[אם]\u0006 הקדים את התנאי לענין המתנה ו\u0003אמר; לנסיב\u0004 \u0005[שישא]\u0006 את הבת \u0003והבו ליה\u0004 \u0005[ותנו לו]\u0006 — \u0003אי נסיב\u0004 \u0005[אם\u0006 הוא \u0005נושא]\u0006 \u0003— שקיל\u0004 \u0005[\u0006הריהו \u0005נוטל],\u0006 \u0003ואי לא נסיב\u0004 \u0005[ואם אינו נושא]\u0006 \u0003— לא שקיל\u0004 \u0005[אינו נוטל].\u0006","מסופר: \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003מרימר וקאמר להא שמעתא משמיה דנפשיה\u0004 \u0005[ואמר את ההלכה הזו משם עצמו],\u0006 שאמר את מסקנת ההלכה לגבי המתנה על קרבן תודה, מבלי להזכיר את שם אומרה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא למרימר: אתון הכי מתניתו לה\u0004 \u0005[אתם כך אתם שונים\u0006 את ההלכה \u0005הזו]\u0006 ללא שם אומרה, ואילו \u0003אנן\u0004 \u0005[אנחנו]\u0006 \u0003כדבעא מיניה\u0004 \u0005[\u0006באופן \u0005ששאל ממנו]\u0006 \u0003ריש לקיש מר' יוחנן מתנינן לה\u0004 \u0005[שונים אנו אותה].\u0006","\u0003תני תנא\u0004 \u0005[שנה חוזר המשניות]\u0006 \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003ר' יצחק בר אבא\u0004 את הברייתא הבאה: מן הכתוב בפרשת המילואים בענין העולה שנצטווה אהרן להקריב \u0003\"ויקרב את העלה ויעשה כמשפט\"\u0004 (ויקרא ט, טז) למדים, שדין עולת חובה \u0003כמשפט עולת נדבה. למד על עולת חובה\u0004 שאף היא \u0003טעונה סמיכה,\u0004 שדבר זה לא נאמר במפורש בעולת חובה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יצחק לאותו תנא: \u0003דאמר\u0004 \u0005[שאמר]\u0006 \u0003לך,\u0004 שלימד אותך את שיטת ברייתא זו, שלדבר זה צריך ראיה מפורשת מן הכתוב \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי היא\u0006 סבורה לדעתו\u0005]\u0006 — כשיטת \u0003בית שמאי היא, דלא גמרי\u0004 \u0005[שאינם לומדים]\u0006 דין של \u0003שלמי חובה משלמי נדבה\u0004 בדרך בנין אב, שהרי מחלקים הם בענין חובת סמיכה על שלמים שמביאים בחג, ולשיטתם יש להביא ראיה מיוחדת לכל פרט, \u0003דאי\u0004 \u0005[שאם]\u0006 כשיטת \u0003בית הלל\u0004 היא, \u0003כיון דגמרי\u0004 \u0005[שהם למדים]\u0006 דין \u0003שלמי חובה מ\u0004דין \u0003שלמי נדבה,\u0004 ולשיטתם הכל בכלל שלמים ואין לחלק, אם כן \u0003עולת חובה נמי\u0004 \u0005[גם כן]\u0006 \u0003לא תבעי קרא\u0004 \u0005[תצטרך כתוב]\u0006 מיוחד כדי ללמד על כך, \u0003דגמרי\u0004 \u0005[ש\u0006הם \u0005למדים]\u0006 \u0003מעולת נדבה\u0004 בדרך של \"בנין אב\".","ושואלים: \u0003וממאי\u0004 \u0005[וממה]\u0006 מוכיח אתה ש\u0003בית הלל שלמי חובה משלמי נדבה גמרי\u0004 \u0005[למדים]?\u0006 \u0003דלמא\u0004 \u0005[שמא]\u0006 לדעתם אין ללמוד חובה מנדבה, אלא חובה מחובה ובאמת מצוות סמיכה בשלמי חובה \u0003מעולת חובה גמרי\u0004 \u0005[למדים\u0006 הם\u0005],\u0006 שכשם שעולת חובה טעונה סמיכה אף שלמי חובה טעונים סמיכה, \u0003ועולת חובה גופא\u0004 \u0005[עצמה]\u0006 \u0003בעי קרא\u0004 \u0005[צריכה כתוב\u0006 מפורש\u0005]\u0006 ללמוד בה הלכה זו, ושמא למדו אף הם מן הכתוב \"ויעשה כמשפט\".","ומקשים על הסבר זה: \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 שלמי חובה שאותם \u0003משלמי נדבה דלא גמרי\u0004 \u0005[שאין למדים]\u0006 \u0003שכן\u0004 שלמי נדבה \u0003מצויים\u0004 יותר, ושמא יש להם דין שונה. אם כן שלמי חובה \u0003מעולת חובה נמי\u0004 \u0005[גם כן]\u0006 \u0003לא גמרי\u0004 \u0005[ילמדו]\u0006 \u0003שכן\u0004 העולה היא \u0003כליל,\u0004 (נשרפת כולה לקרבן), מה שאין כן בשלמים!","ומתרצים: \u0003אלא אתיא מבינייא\u0004 \u0005[בא,\u0006 נלמד הדבר \u0005מביניהם]\u0006 שכיון שמפורש גם בעולת חובה וגם בשלמי נדבה שצריכים סמיכה, אפשר ללמוד משניהם יחד חובת סמיכה גם לשלמי חובה: שאם תרצה לומר שהטעם הוא מפני שהוא כליל —שלמי נדבה יוכיחו, ואם משום שאינו מצוי — עולת חובה תוכיח. ואם כן אין איפוא ראיה לשיטת הלימוד של בית הלל, ויתכן שגם הם סומכים על הראיה מן הכתוב \"ויעשה משפט\".","ושואלים לגופו של דבר: \u0003וסברי\u0004 \u0005[ו\u0006כי \u0005סברו]\u0006 \u0003בית שמאי\u0004 כי \u0003שלמי חובה לא בעו\u0004 \u0005[צריכים]\u0006 \u0003סמיכה? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אמר ר' יוסי: לא נחלקו בית שמאי ובית הלל על הסמיכה עצמה\u0004 של השלמים \u0003שצריך\u0004 לעשותה. \u0003על מה נחלקו\u0004 על הדין של \u0003\"תכף לסמיכה שחיטה\", שבית שמאי אומרים: אינו צריך\u0004 להקפיד על כך, ואפשר לעשות סמיכה הרבה קודם לשחיטה עוד בערב יום טוב. \u0003ובית הלל אומרים: צריך,\u0004 ולכן חייבים לסמוך ביום החג!","ומשיבים: \u0003הוא\u0004 ש\u0003אמר\u0004 את דבריו \u0003כי האי תנא\u0004 \u0005[כ\u0006שיטת \u0005תנא זה],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא אחרת\u0005]:\u0006 \u0003אמר ר' יוסי בר' יהודה: לא נחלקו בית שמאי ובית הלל על תכף לסמיכה שחיטה שצריך, על מה נחלקו\u0004 — \u0003על הסמיכה עצמה, בית שמאי אומרים: אינו צריך, ובית הלל אומרים צריך\u0004.","ושוב חוזרים לעיקר המחלוקת בין בית שמאי ובית הלל. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מעשה בהלל הזקן שהביא עולתו לעזרה לסמוך עליה ביום טוב. חברו עליו\u0004 (התאספו סביבו) \u0003תלמידי שמאי הזקן, אמרו לו: מה טיבה של בהמה זו\u0004 שאתה מביא? וכיון שהיה הלל ענו ושפל ברך, לא רצה לבוא עמם לידי ויכוח וסכסוך במקדש, ולכן שינה מפני השלום, \u0003אמר להם: נקבה היא, ולזבחי שלמים הבאתיה,\u0004 שהרי עולה אינה קריבה אלא זכר ו\u0003כשכש להם בזנבה\u0004 (הניע את זנבה) שלא יראו היטב אם זכר או נקבה היא, \u0003והלכו להם.\u0004","וכיון שנודע מעשה זה, נראה היה שאף הלל ביטל את דעתו מפני דעת שמאי, \u0003ואותו היום גברה ידם של בית שמאי על בית הלל, ובקשו לקבוע הלכה\u0004 קבועה \u0003כמותן\u0004 בענין זה. \u0003והיה שם זקן אחד\u0004 שהיה \u0003מתלמידי שמאי הזקן, ובבא בן בוטא שמו, שהיה יודע שהלכה כבית הלל\u0004 בענין זה, \u0003ושלח\u0004"],["\u0003והביא כל צאן קדר\u0004 (שהיה משובח ביותר) שהיה \u0003בירושלים והעמידן בעזרה, ואמר: כל מי שרוצה לסמוך\u0004 — \u0003יבא ויסמוך, ואותו היום גברה ידן של בית הלל וקבעו\u0004 בענין זה \u0003הלכה כמותן, ולא היה שם אדם שערער בדבר כלום.\u0004","\u0003שוב\u0004 היה לאחר מכן \u0003מעשה\u0004 נוסף \u0003בתלמיד אחד מתלמידי בית הלל שהביא עולתו לעזרה לסמוך עליה\u0004 ביום טוב, \u0003מצאו תלמיד אחד מתלמידי בית שמאי, אמר לו: מה זו סמיכה?\u0004 כלומר, מדוע סומך אתה, ועובר על דברי בית שמאי? \u0003אמר לו: מה זו שתיקה?\u0004 מדוע אינך שותק? שהרי אין הלכה כמותכם! \u0003שתקו בנזיפה, והלך לו\u0004 בשתיקה.","ומכאן \u0003אמר אביי: הלכך\u0004 \u0005[על כן],\u0006 \u0003האי צורבא מרבנן דאמר ליה חבריה מלתא\u0004 \u0005[תלמיד חכם שאומר לו חבירו דבר\u0006 של נזיפה או גנאי\u0005]\u0006 \u0003לא להדר ליה מלתא טפי ממאי דאמר ליה חבריה\u0004 \u0005[שלא יחזיר לו דבר יותר ממה שאמר לו חבירו]\u0006 ולא יוסיף במחלוקת, \u0003דאיהו\u0004 \u0005[ש\u0006הרי \u0005הוא]\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003\"מה זו סמיכה\", וקא מהדר ליה\u0004 \u0005[\u0006ש\u0005הוא\u0006 \u0005חזר\u0006 וענה \u0005לו\u0006 בדיוק כלשונו\u0005]:\u0006 \u0003\"מה זו שתיקה\".\u0004","ולגופה של מחלוקת זו. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמרו להם בית הלל לבית שמאי: ומה במקום שאסור להדיוט\u0004 לשחוט, כגון בשבת — \u0003מותר\u0004 לשחוט קרבנות במקדש \u0003לגבוה,\u0004 כגון תמידים ומוספים, \u0003מקום שמותר להדיוט\u0004 ביום טוב, \u0003אינו דין שמותר לגבוה?\u0004 ובכלל זה אף עולת ראייה! \u0003אמרו להם בית שמאי:\u0004 אין זו הוכחה, \u0003נדרים ונדבות יוכיחו, שמותר להדיוט\u0004 לשחוט לעצמו בהמות לאכילה אף בחג \u0003ואסור\u0004 לשחוט נדרים ונדבות בחג \u0003לגבוה!\u0004","\u0003אמרו להם בית הלל: מה לנדרים ונדבות\u0004 — \u0003שאין קבוע להם זמן,\u0004 ואין חייב לשחטם בחג דווקא, \u0003תאמר בעולת ראיה\u0004 — \u0003שקבוע לה זמן\u0004 בחג. \u0003אמרו להם בית שמאי: אף זו אין קבוע לה זמן, דתנן\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003מי שלא חג\u0004 (לא הביא את קרבן החג) \u0003ביום טוב\u0004 ה\u0003ראשון של חג\u0004 — \u0003חוגג\u0004 (מקריב) \u0003והולך כל הרגל כולו, ויום טוב האחרון של חג.\u0004 הרי שאף לעולת ראיה לא נקבע זמנה דווקא לחג!","\u0003אמרו להם בית הלל:\u0004 בכל זאת, למרות שאין זו חובה ליום מסויים בחג, מכל מקום \u0003אף זו קבוע לה זמן,\u0004 אף שהוא רחב יותר. \u0003דתנן\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003עבר הרגל ולא חג\u0004 — \u0003אינו חייב באחריותו.\u0004 כלומר: אינו צריך להביא קרבן אחר, שכבר עברה ובטלה מצותו, נמצא שקרבן זה יש לו זמן מוגבל דווקא בתוך ימי החג, ואינו דומה לנדרים ונדבות.","\u0003אמרו להם בית שמאי\u0004 והביאו אף הם ראיה לדבריהם: \u0003והלא כבר נאמר\u0004 \"כל אשר יאכל לכל נפש הוא לבדו יעשה \u0003לכם\"\u0004 (שמות יב, טז) ויש ללמוד מההדגשה \"לכם\" — \u0003ולא לגבוה. אמרו להם בית הלל: והלא כבר נאמר\u0004 \"וחגותם אותו חג \u0003לה'\"\u0004 (ויקרא כג, מא), משמע \u0003כל\u0004 מה שנעשה \u0003לה'\u0004 — מותר להקריב. \u0003אם כן, מה תלמוד לומר \"לכם\",\u0004 כוונתו, \u0003לכם\u0004 — \u0003ולא לגויים, לכם\u0004 — ולא לכלבים.","אותה מחלוקת היה \u0003אבא שאול אומרה בלשון אחרת,\u0004 שכך אמרו בית הלל: \u0003ומה במקום שכירתך סתומה,\u0004 כלומר: בשבת שאסור לאדם לבשל לעצמו — \u0003כירת רבך פתוחה,\u0004 שמותר להדליק אש על גבי המזבח ולהקטיר קרבנות עליו, \u0003במקום שכירתך פתוחה\u0004 ביום טוב, שמותר לך לבשל כדי אוכל נפש — \u0003אינו דין שכירת רבך\u0004 תהא \u0003פתוחה? וכן\u0004 הוא \u0003בדין\u0004 (מסברה); \u0003שלא יהא שולחנך מלא ושולחן רבך\u0004 (המזבח, שהוא השולחן לפני ה') \u0003ריקן.\u0004","ושואלים: \u0003במאי קא מפלגי\u0004 \u0005[במה הם חלוקים],\u0006 החכם הראשון ואבא שאול, שהביאו שתי נוסחאות לדברי בית הלל? ומסבירים: \u0003מר\u0004 \u0005[חכם זה,\u0006 אבא שאול\u0005]\u0006 \u0003סבר,\u0004 שלדעת בית הלל \u0003נדרים ונדבות קרבין ביום טוב\u0004 ולכן לא יכלו אנשי בית שמאי להשתמש בנימוק שהוזכר בברייתא הראשונה, להוכיח ממה שאין מקריבים נדרים ונדבות, \u0003ו\u0004אילו \u0003מר\u0004 \u0005[חכם זה,\u0006 החכם הראשון\u0005]\u0006 \u0003סבר,\u0004 שלשיטת בית הלל נדרים ונדבות \u0003אין קרבין ביום טוב,\u0004 ובשל כך אכן השתמשו אנשי בית שמאי בנימוק זה.","\u0003אמר רב הונא: לדברי האומר\u0004 כי \u0003נדרים ונדבות אין קרבין ביום טוב, לא תימא מדאורייתא מחזא חזו\u0004 \u0005[אל תאמר שמן התורה\u0006 באמת \u0005ראויים הם]\u0006 ו\u0003רבנן הוא דגזרו בהו\u0004 \u0005[\u0006ו\u0005חכמים הם שגזרו בהם]\u0006 שלא יקריבום בחג \u0003גזרה שמא ישהה\u0004 אותם בביתו ולא יקריבם בזמנם וידחה את הקרבתם עד הרגל ושמא יעבור בשל כך על איסור \"בל תאחר\" — לא זה הטעם,","\u0003אלא\u0004 לשיטה זו \u0003אפילו מדאורייתא נמי לא חזו\u0004 \u0005[מן\u0006 ה\u0005תורה גם כן אינם ראויים]\u0006 להקרבה ביום טוב. \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003שתי הלחם\u0004 ש\u0003חובת היום\u0004 של חג השבועות \u0003נינהו\u0004 \u0005[הם]\u0006 להביאם, \u0003וליכא למגזר\u0004 \u0005[ואין לגזור]\u0006 באלה \u0003שמא ישהה,\u0004 שהרי זמנם קבוע רק לחג הזה, ועם זאת, אפייתם והכנתם \u0003אינו דוחה לא את השבת ולא את יום טוב.\u0004 שלשיטה זו כל דבר שאין הכרח לעשותו בחג עצמו — אסור אכן לעשותו בחג.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 ללומדים שאלה זו: \u0003לדברי האומר\u0004 כי \u0003נדרים ונדבות אין קרבין ביום טוב,\u0004 אם \u0003עבר ושחט\u0004 נדרים ונדבות אלה ביום טוב \u0003מאי\u0004 \u0005[מה]\u0006 יעשה אז? \u0003רבא אמר: זורק את הדם\u0004 של קרבנות אלה על המזבח \u0003על מנת להתיר בשר באכילה.\u0004 ואילו \u0003רבה בר רב הונא אמר: זורק את הדם על מנת\u0004 שיוכל \u0003להקטיר אימורין\u0004 (החלב ושאר החלקים העולים למזבח) \u0003לערב.\u0004","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם]\u0006 הלכה למעשה? שהרי שניהם הסכימו שזורק את הדם? ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל למעשה; כגון אם \u0003נטמא\u0004 ה\u0003בשר או שאבד,\u0004 שלדעת \u0003רבא\u0004 שהטעם הוא משום התרת הבשר באכילה, אם כן \u0003לא זריק\u0004 \u0005[זורק]\u0006 את הדם (אף שאין בכך משום איסור תורה אלא שבות), לפי שאין בכך משום צורך החג, ואילו \u0003לרבה בר רב הונא\u0004 שסבור שעושים זאת לשם התרת הקרבת החלבים — \u0003זריק\u0004 \u0005[זורק]\u0006 את הדם אפילו אם אין בכך היתר לבשר.","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 ממה ששנינו: \u0003כבשי עצרת\u0004 (כבשים של שלמי צבור שמקריבים בחג השבועות) \u0003ששחטן שלא לשמן,\u0004 כגון ששחטם לשם קרבן אחר \u0003או ששחטן\u0004 שלא בזמן הקבוע להם, \u0003בין לפני זמנן בין לאחר זמנן,\u0004 ואף שקרבנות אלה לא יצא בהם ידי חובה, מכל מקום כשרים הם לעצמם. מה יעשו בהם? \u0003הדם יזרק והבשר יאכל. ואם היתה\u0004 אותו יום שבו שחט את הכבשים \u0003שבת\u0004 ובגלל זה אסור לבשל או לצלות את הבשר, ומתוך שאי אפשר לאכול מהם אין אם כן בזריקה זו כל הכרח, לא למצוותם ולא לענין אחר — \u0003לא יזרוק\u0004 את הדם. ומכל מקום, \u0003ואם זרק\u0004 בכל זאת —"],["\u0003הורצה,\u0004 וזאת \u0003על מנת\u0004 (כלומר, וצריך) \u0003להקטיר אימורין לערב\u0004 ולא ביום. ולענייננו, מלשון הברייתא אנו למדים שאם אי אפשר לאכול את הבשר בו ביום נאמר על כך הלשון \u0003אם זרק,\u0004 כלומר: \u0003דיעבד — אין\u0004 \u0005[כן]\u0006 מותר, אולם \u0003לכתחלה\u0004 — \u0003לא\u0004 יזרוק! \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003רבא ניחא\u0004 \u0005[נוח\u0006 הדבר\u0005],\u0006 \u0003אלא ל\u0004שיטת \u0003רבה בר רב הונא קשיא\u0004 \u0005[קשה]!\u0006 ומעירים: אכן \u0003קשיא\u0004 \u0005[קשה].\u0006 \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 ותרץ כך: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003שבות שבת משבות יום טוב,\u0004 שבשבת החמירו חכמים בדבריהם יותר מכפי שהחמירו ביום טוב.","\u0003בעא מניה\u0004 \u0005[שאל אותו]\u0006 \u0003רב אויא סבא\u0004 \u0005[הזקן]\u0006 \u0003מרב הונא\u0004 שאלה זו: \u0003בהמה\u0004 של שותפים, \u0003חציה של גוי וחציה של ישראל, מהו לשחטה ביום טוב? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מותר. אמר ליה\u0004 \u0005[לו]:\u0006 \u0003וכי מה בין זה לנדרים ונדבות,\u0004 שהרי קרבנות נדרים ונדבות אף הם נחשבים כבהמת השותפים, שהרי חלק מן הבהמה עולה למזבח ואת החלק האחר אוכלים הבעלים והכהנים, ומדוע לא נאמר שאף הם יהיו מותרים בשחיטה ביום טוב? לא ענה לו רב הונא על שאלתו, אלא \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003עורבא פרח\u0004 \u0005[\u0006ראה \u0005עורב פורח,\u0006 עף בשמים\u0005]!\u0006 שרצה להסיח דעתו מן הדבר, ולא ענה לשאלה.","\u0003כי נפק\u0004 \u0005[כאשר יצא]\u0006 רב אויא \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבה בריה\u0004 \u0005[בנו]\u0006 של רב הונא לאביו: \u0003לאו היינו\u0004 \u0005[וכי אין זה]\u0006 \u0003רב אויא סבא\u0004 \u0005[הזקן]\u0006 \u0003דמשתבח ליה מר בגויה דגברא רבה\u0004 \u0005[שמשתבח בו אדוני שאדם גדול]\u0006 \u0003הוא?\u0004 ואם כן מדוע התנהגת בו כך, ולא ענית על שאלתו? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ומה אעביד ליה\u0004 \u0005[אעשה לו],\u0006 \u0003אני היום\u0004 במצב שאפשר לומר עליו כלשון הכתוב: \u0003\"סמכוני באשישות רפדוני בתפוחים\"\u0004 (שיר השירים ב, ה), כלומר: עייף אני ונרגש מפני טורח הרבים שהיה עלי, \u0003ובעא מינאי מלתא דבעיא טעמא\u0004 \u0005[ושאל אותי דבר שצריך טעם]\u0006 ועיון מדוקדק בו, ולכן לא יכולתי לענות מיד.","ושואלים: \u0003וטעמא מאי\u0004 \u0005[והטעם,\u0006 אכן \u0005מהו]?\u0006 ומסבירים את ההבדל: \u0003בהמה\u0004 ש\u0003חציה של נכרי וחציה של ישראל מותר לשחטה ביום טוב,\u0004 והטעם הוא משום ש\u0003אי אפשר לכזית בשר בלא שחיטה,\u0004 ואם רוצה ישראל לאכול אפילו מעט — בהכרח עליו לשחוט בהמה שלימה אף כי אינו משתמש בכולה, ולכן אין הדבר מעכב אם חלקה האחר שייך לגוי. \u0003אבל נדרים ונדבות אסור לשחטן ביום טוב\u0004 משום שכאן אין כלל שותפות בבהמת הקרבן, כיון שה\u0003כהנים כי קא זכו\u0004 \u0005[כאשר הם זוכים]\u0006 בחלק מבשר הקרבן, וכן ישראל האוכלים מן הקרבן — \u0003משלחן גבוה,\u0004 של הקדוש ברוך הוא, \u0003קא זכו\u0004 \u0005[הם זוכים].\u0006 כלומר, הקרבן בעצם שייך כולו לה', ואנשים האוכלים ממנו הם כסמוכים על שולחנו, והרי אמרנו שלצורך גבוה אין שוחטים.","\u0003בהמשך לאותו דיון אמר רב חסדא: בהמה\u0004 ש\u0003חציה של גוי וחציה של ישראל\u0004 — \u0003מותר לשחטה ביום טוב,\u0004 והטעם: ש\u0003אי אפשר לכזית בשר בלא שחיטה.\u0004 אולם \u0003עיסה\u0004 של בצק ש\u0003חציה של גוי וחציה של ישראל\u0004 — \u0003אסור לאפותה ביום טוב — דהא\u0004 \u0005[שהרי]\u0006 \u0003אפשר ליה למפלגה\u0004 \u0005[לו לחלק אותה]\u0006 \u0003בלישה,\u0004 והחלק האחד, של ישראל — יאפה, וחלקה השני השייך לגוי לא יאפה.","\u0003מתיב\u0004 \u0005[מקשה\u0006 על כך\u0005]\u0006 \u0003רב חנא בר חנילאי\u0004 ממה ששנינו: \u0003עיסת כלבים\u0004 עיסה שבוללים בקמח עוד חומרים שונים ונותנים אותה לכלבים \u0003בזמן\u0004 שטיבה כזה שאף \u0003הרועין אוכלין ממנה\u0004 — הרי היא נחשבת כלחם לכל דבר ו\u0003חייבת\u0004 בהפרשת \u0003חלה\u0004 ממנה \u0003ומערבין בה\u0004 עירובי תחומין וחצירות, \u0003ומשתתפין בה\u0004 לצורך שיתוף מבואות, \u0003ומברכין עליה\u0004 ברכה ראשונה ואחרונה, \u0003ומזמנין עליה\u0004 לברכת המזון אם אכלו אותה שלושה אנשים כאחד, \u0003ו\u0004אף היא \u0003נאפת ביום טוב\u0004 כשאר מאכל אדם, \u0003ואדם יוצא בה ידי חובתו בפסח\u0004 אם לא החמיצה.","ולגבי היתר אפייתה; \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 נאפת היא ביום טוב? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אפשר ליה למפלגה\u0004 \u0005[לו לחלק אותה]\u0006 את העיסה הזאת \u0003ב\u0004שעת \u0003לישה,\u0004 וחלק האדם יאפה וחלק הכלבים לא יאפה! ומשיבים: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003עיסת כלבים, הואיל ואפשר לפייסן בנבלה,\u0004 כלומר, הלא יתכן שתמות אחת הבהמות ואז יתנו את הנבילה לכלבים, ותמצא עיסה זו כולה למאכל אדם.","על התירוץ הזה תוהים: \u0003מי אית ליה\u0004 \u0005[האם יש לו,\u0006 מקבל\u0005]\u0006 \u0003רב חסדא\u0004 את הנימוק הזה של \u0003\"הואיל\"?\u0004 לומר, שכיון שהואיל ויש אפשרות שישתנה המצב אין לקבוע הלכה לפי מצב הדברים עכשיו? \u0003והא אתמר\u0004 \u0005[והרי נאמר]\u0006 שנחלקו אמוראים בשאלה מה הדין אם \u0003אופה\u0004 אדם במזיד \u0003מיום טוב לחול. רב חסדא אמר: לוקה\u0004 על חילול יום טוב, \u0003רבה אמר: אינו לוקה.\u0004","וטעמם, \u0003רב חסדא אמר: לוקה,\u0004 כי לשיטתו \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 \u0003הואיל ומקלעי ליה\u0004 \u0005[ואם מזדמנים לו]\u0006 \u0003אורחים\u0004 ויצטרך לפת מרובה, \u0003חזי ליה\u0004 \u0005[יהיה ראוי לו]\u0006 אף ליום טוב עצמו, על כן \u0003השתא נמי חזי ליה\u0004 \u0005[עכשיו גם כן,\u0006 גם כשאין אורחים \u0005ראוי לו],\u0006 ואם כן בשעת מעשה אין זה נחשב כעבירה גמורה, ואי אפשר להתרות ולהלקות עליה. ואילו \u0003רבה אמר: אינו לוקה,\u0004 כי לשיטתו \u0003אמרינן\u0004 \u0005[אומרים אנו]\u0006 \u0003\"הואיל\".\u0004 וכיון שרב חסדא איננו מקבל את הנימוק של \"הואיל\", כיצד אפשר להשתמש בו כתירוץ לקושיה שעליו?","\u0003אלא\u0004 יש לבטל את הדברים שאמרנו, ו\u0003לא תימא\u0004 \u0005[אל תאמר]\u0006 שהיה כאן ענין של \u0003\"הואיל ואפשר\", אלא\u0004 פה מדובר \u0003כגון דאית ליה\u0004 \u0005[שיש לו]\u0006 \u0003נבלה\u0004 מוכנה, ש\u0003ודאי אפשר לפייסן בנבלה.\u0004 ולכן כאשר אופים הרועים את העיסה ישנה סבירות גבוהה לכך שתיאכל כולה על ידי הרועים עצמם.","\u0003בעו מניה\u0004 \u0005[שאלו אותו]\u0006 את \u0003רב הונא\u0004 שאלה זו: \u0003הני בני באגא דרמו עלייהו קמחא דבני חילא\u0004 \u0005[אותם\u0006 יהודים \u0005בני הכפרים שהטילו עליהם\u0006 מן המלכות חובה לספק \u0005קמח\u0006 ולחם \u0005לאנשי הצבא\u0006 שבאזור\u0005]\u0006 \u0003מהו לאפותה ביום טוב? אמר להו\u0004 \u0005[להם]\u0006 רב הונא לשואלים: \u0003חזינא\u0004 \u0005[רואים אנו]\u0006 \u0003אי יהבי ליה רפתא לינוקא ולא קפדי\u0004 \u0005[אם נותנים\u0006 האנשים מאותה מכסה שהוקצבה לחיילים \u0005פת לתינוק ואין\u0006 החיילים \u0005מקפידים\u0006 על כך\u0005],\u0006 אם כן \u0003כל חדא וחדא חזיא לינוקא\u0004 \u0005[כל אחת ואחת\u0006 מן הככרות, נמצא \u0005שהיא ראויה לתינוק]\u0006 מישראל, ולכן \u0003שרי\u0004 \u0005[מותר]\u0006 לאפותה. \u0003ואי לאו\u0004 \u0005[ואם לא]\u0006 שאינם מניחים לאחר לאכול מפת זו — \u0003אסור\u0004 לאפות ביום טוב עבור גויים.","על ההיתר הזה של רב הונא מקשים, \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מעשה בשמעון התימני\u0004 (מהמקום תמנת) \u0003שלא בא אמש\u0004 (בלילה) של יום טוב \u0003לבית המדרש, בשחרית מצאו ר' יהודה בן בבא. אמר לו: מפני מה לא באת אמש לבית המדרש? אמר לו: בלשת\u0004 (קבוצת חיילים שבאו לעשות חיפוש) \u0003באה לעירנו, ובקשה לחטוף את כל העיר, ושחטנו להם עגל\u0004 כדי לפייסם \u0003והאכלנום\u0004 בו \u0003ופטרנום לשלום.\u0004","\u0003אמר לו\u0004 ר' יהודה בן בבא: \u0003תמה אני אם לא יצא שכרכם\u0004 שהרווחתם שלא לקחו אנשי החייל מרכושכם \u0003בהפסדכם\u0004 של חילול יום טוב. \u0003שהרי אמרה\u0004 ה\u0003תורה:\u0004 \"את אשר יאכל לכל נפש הוא לבדו יעשה לכם\" (שמות יב, טז), ומשמע \u0003\"לכם\" — ולא לגויים. ואמאי\u0004 \u0005[ומדוע]\u0006 אמר כך ר' יהודה בן בבא? \u0003הא חזי למיכל מיניה\u0004 \u0005[הרי ראוי\u0006 עגל זה \u0005לאכול ממנו]\u0006 משהו גם לישראל. והמסקנה איפוא שגם אם ישראל יכולים לאכול ממנו, כיון שעושה עבור גויים, הרי זה אסור!","\u0003אמר רב יוסף:\u0004 באותו מקרה \u0003עגל טרפה הואי\u0004 \u0005[היה]\u0006 זה, שלא היה ראוי כלל לישראל. ומקשים: \u0003והא חזי\u0004 \u0005[והרי ראוי]\u0006 הוא להאכילו \u0003לכלבים\u0004 ויכול אתה לומר ששחטו עבור כלבי ישראל!","ומשיבים: \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא\u0004 אם מותר לעשות מלאכה ביום טוב עבור הכלבים. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 נאמר: \u0003\"אך אשר יאכל לכל נפש הוא לבדו יעשה לכם\", ממשמע שנאמר \"לכל נפש\" שומע\u0004 (לומד) \u0003אני\u0004 כי \u0003אפילו נפש בהמה במשמע,\u0004 ו\u0003כענין שנאמר: \"ומכה נפש בהמה ישלמנה\"\u0004 (ויקרא כד, יח), משמע שנפש בהמה אף היא קרוייה נפש, על כן \u0003תלמוד לומר\u0004 ההדגשה בכתוב \u0003\"לכם\"\u0004"],["\u0003\"לכם\"\u0004 — \u0003ולא לכלבים,\u0004 אלו \u0003דברי ר' יוסי הגלילי. ר' עקיבא אומר:\u0004 מה שנאמר \"כל נפש\" — \u0003אפילו נפש בהמה במשמע. אם כן מה תלמוד לומר\u0004 בהדגשה \u0003\"לכם\"\u0004 — כוונתו: \u0003לכם ולא לגויים.\u0004","ושואלים: \u0003ומה ראית לרבות את הכלבים\u0004 שמותר לעשות מלאכה עבורם ביום טוב \u0003ולהוציא את הגויים?\u0004 ומסבירים: \u0003מרבה אני את הכלבים\u0004 שהרי \u0003מזונותן עליך\u0004 וחייב אתה לפרנסם כשאר בני הבית, \u0003ומוציא אני את הגויים שאין מזונותן עליך.\u0004","ביחס לברייתא זו \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב יוסף: ולר' יוסי הגלילי\u0004 ש\u0003אמר\u0004 כי מן הכתוב \u0003\"לכם\"\u0004 יש ללמוד \u0003ולא לכלבים, הני סופלי\u0004 \u0005[אותם גרעיני תמרים]\u0006 \u0003לחיותא היכי שדינן להו\u0004 \u0005[לחיות\u0006 ולבהמות, \u0005איך נותנים אנו אותם]\u0006 \u0003ביום טוב?\u0004 שהרי למאכל אדם אינם ראויים ולתיתם לחיות לפי שיטה זו גם כן אסור, אם כן הרי הם בכלל מוקצה ואסורים בטלטול!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף: כיון שמותר לטלטלם \u0003הואיל וחזו\u0004 \u0005[הואיל וראויים]\u0006 הגרעינים \u0003להסקה,\u0004 לכן אפשר לתת אותם גם לבהמות. והקשה לו: \u0003תינח ביבשתא, ברטיבתא מאי איכא למימר\u0004 \u0005[נניח\u0006 דבר זה \u0005ב\u0006גרעינים \u0005יבשים,\u0006 אולם \u0005ברטובים\u0006 שאינם ראויים להסקה, \u0005מה אפשר לומר]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003חזו\u0004 \u0005[ראויים הם]\u0006 \u0003להיסק גדול.\u0004 שבמדורה גדולה הם מתייבשים, ואחר כך הם עצמם בוערים היטב.","הקשה לו: \u0003תינח\u0004 \u0005[נניח]\u0006 כל זה \u0003ביום טוב\u0004 שמותר להסיק בו, אולם \u0003בשבת מאי איכא למימר\u0004 \u0005 [מה\u0006 יש לומר\u0005]?\u0006 איך הותרו בטלטול? והשיב לו: \u0003מטלטלינן להו\u0004 \u0005[מטלטלים אנו אותם]\u0006 \u0003אגב ריפתא\u0004 \u0005[\u0006ככר \u0005לחם],\u0006 שמניחים אותם על הככר ואגב הככר מטלטלים גם את הגרעינים. וכדברי \u0003שמואל,\u0004 ש\u0003אמר שמואל: עושה אדם כל צרכו בפת\u0004 ואין אומרים שיש בכך משום בזיון לאוכל.","ומעירים: \u0003ופליגא\u0004 \u0005[וחלוקה]\u0006 הלכה זו שקבע רב הונא, שאם נותנים הגויים רשות לישראל לאכול מקצת הפת מותר לאפות בשבילם, על דעת \u0003ר' יהושע בן לוי,\u0004 ש\u0003אמר ר' יהושע בן לוי: מזמנין את הגוי\u0004 לסעודה \u0003בשבת,\u0004 שודאי לא יבשלו עבורו בו ביום, ומותר לתת לגוי לאכול מהמאכלים שהוכנו מבעוד יום, \u0003ואין מזמנין את הגוי\u0004 לסעודה \u0003ביום טוב, גזרה שמא ירבה בשבילו\u0004 ויבשל לו. משמע שאף אם מרבה בלבד הרי זה אסור, למרות שעיקר הסעודה עבור ישראל.","\u0003רב אחא בר יעקב אמר: אפילו בשבת נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 יזמין את הגוי, \u0003משום שיורי כוסות\u0004 היין. שכיון ששתה הגוי בכוס הרי היין דינו כיין נסך ואסור להשתמש בו, וממילא הוא מוקצה, ויש חשש שיבוא לטלטל מוקצה זה בשבת. ושואלים: \u0003אי הכי, דידן נמי\u0004 \u0005[אם כך\u0006 שאתה חושש למוקצה, הכוסות \u0005שלנו גם כן]\u0006 ייאסרו, שהרי יש בהם שיורי יין שאינם ראויים לכל שימוש! ומשיבים: \u0003דידן חזו\u0004 \u0005[\u0006השיירים \u0005שלנו ראויים]\u0006 \u0003לתרנגולין.\u0004 ומקשים: \u0003דידהו נמי חזו\u0004 \u0005[שלהם,\u0006 של הגויים, \u0005גם כן ראויים]\u0006 \u0003לתרנגולין!\u0004 ודוחים: \u0003דידהו\u0004 \u0005[שלהם]\u0006 \u0003איסורי הנאה נינהו\u0004 \u0005[הם]\u0006 ולכן אסור להשתמש בהם כלל.","ושואלים: \u0003ולטלטלינהו אגב כסא\u0004 \u0005[ושיטלטלם אגב הכוס],\u0006 שהכוס היא כלי המותר בטלטול, ואותם שיירים יתבטלו לגביה. \u0003מי\u0004 \u0005[האם]\u0006 \u0003לא אמר רבא: מטלטלין כנונא\u0004 \u0005[מחתה]\u0006 \u0003אגב קטמיה\u0004 \u0005[האפר שלה]\u0006 \u0003אף על גב דאיכא עליה\u0004 \u0005[אף על פי שיש עליה]\u0006 \u0003שברי עצים,\u0004 משמע שמותר לטלטל מוקצה אגב דבר המותר בטלטול!","ודוחים: בכל זאת יש הבדל, \u0003התם\u0004 \u0005[שם]\u0006 — \u0003לאו\u0004 \u0005[לא]\u0006 \u0003איסורי הנאה נינהו\u0004 \u0005[הם],\u0006 אלא מוקצה בלבד, ואילו \u0003הכא\u0004 \u0005[כאן]\u0006 בשיירי יין ששתה ממנו הגוי — \u0003איסורי הנאה נינהו\u0004 \u0005[הם]\u0006 וחמור איסורם יותר.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא מדפתי לרבינא\u0004 באופן אחר: \u0003ולהוי כגרף של רעי\u0004 \u0005[ושיהא\u0006 זה \u0005כמו כלי של צואה]\u0006 שמותר להוציאו מפני המיאוס, ואף שיורי כוסות אלה, כיון שאין ראוי להשאירם על השולחן, יהא מותר לזורקם מפני טעם זה! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 אכן, אם יש שיורים כאלה מותר להשליכם, אולם \u0003וכי עושין גרף של רעי לכתחלה?\u0004 ולכן אמרו שלא יזמין את הגוי מלכתחילה ולא יבוא לידי בעיה.","ולסיכום ההלכה מסופר: \u0003אדבריה\u0004 \u0005[הרשה]\u0006 והורה לו \u0003רבא ל\u0004חכם מבית ראש הגולה \u0003מר שמואל, ודרש\u0004 מר שמואל ברבים: \u0003מזמנין את הגוי בשבת, ואין מזמנין את הגוי ביום טוב, גזרה שמא ירבה בשבילו.\u0004 מסופר: \u0003מרימר ומר זוטרא, כי הוה מקלע להו\u0004 \u0005[כאשר היה מזדמן להם]\u0006 \u0003גוי ביום טוב, אמרו ליה\u0004 \u0005[היו אומרים לו]:\u0006 \u0003אי ניחא לך במאי דטריחא לן\u0004 \u0005[אם נוח לך במה שטרחנו לעצמנו]\u0006 \u0003— מוטב, ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 — \u0003טרחא יתירא אדעתא דידך לא טרחינן\u0004 \u0005[בגללך אין אנו טורחים].\u0006","\u0003בית שמאי אומרים: לא יחם אדם חמין\u0004 לרחוץ את \u0003רגליו\u0004 בהם \u0003אלא אם כן ראויין\u0004 הם \u0003לשתיה.\u0004 שלדעתם מותרת ביום טוב רק מלאכה לצורך אוכל בלבד. \u0003ובית הלל מתירין.\u0004 שלדעתם, כל הנאה בכלל ההיתר. \u0003עושה אדם מדורה\u0004 גדולה של אש \u0003ומתחמם כנגדה.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 ללומדים: \u0003האי\u0004 \u0005[\u0006הלכה \u0005זו]\u0006 בענין \u0003מדורה מאן קתני לה\u0004 \u0005[מי שנה,\u0006 למד, \u0005אותה]?\u0006 האם \u0003דברי הכל היא\u0004 ואף כדעת בית שמאי, \u0003ושני להו\u0004 \u0005[ושונה להם]\u0006 \u0003לבית שמאי\u0004 לענין הלכה \u0003בין הנאת כל גופו להנאת אבר אחד,\u0004 ואף הם מודים שהנאת כל גופו דינה כאוכל, ולכן הותרה הסקת מדורה שכל גופו נהנה ממנה, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003בית הלל קתני לה\u0004 \u0005[שנו,\u0006 למדו \u0005אותה],\u0006 \u0003אבל בית שמאי לא שני להו\u0004 \u0005[אין שונה להם]\u0006 ואינם מבדילים, והתירו רק הנאת אכילה בלבד?","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר מברייתא מפורשת, ששנינו בה, \u0003בית שמאי אומרים: לא יעשה אדם מדורה ויתחמם כנגדה. ובית הלל מתירין.\u0004 ומוכח מכאן שהלכה זו במשנתנו דווקא כשיטת בית הלל היא.","\u0003שלשה דברים\u0004 היה \u0003רבן גמליאל מחמיר\u0004 בהם \u0003כדברי בית שמאי.\u0004 וכך היה אומר: \u0003אין טומנין את החמין לכתחלה ביום טוב,\u0004 עבור השבת אלא יש לטומנם מערב החג, \u0003ואין זוקפין\u0004 (מקימים, מעמידים) \u0003את המנורה\u0004 העשוייה מתכת שנפלה \u0003ביום טוב, ואין אופין פתין גריצין\u0004 (עבים) \u0003אלא רקיקין\u0004 (דקים), מפני הטירחה הרבה שיש באפיית פת עבה. \u0003אמר רבן גמליאל: מימיהן של בית אבא לא היו אופין\u0004 ביום טוב \u0003פתין גריצין אלא רקיקין. אמרו לו\u0004 חכמים: \u0003מה נעשה לבית אביך שהיו מחמירין על עצמן,\u0004 אולם היו \u0003מקילין לכל ישראל להיות אופין פתין גריצין וחררין\u0004 \u0005[עוגות שאופים על גחלים].\u0006","על מה שנאמר במשנתנו שלא היה מתיר רבן גמליאל לכתחילה לטמון חמין ביום טוב, שואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אי דאנח\u0004 \u0005[אם\u0006 מדובר באופן \u0005שהניח]\u0006 \u0003עירובי תבשילין — מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003בית שמאי\u0004 שאוסרים? \u0003ואי דלא אנח\u0004 \u0005[ואם\u0006 מדובר באופן \u0005שלא הניח]\u0006 \u0003עירובי תבשילין,\u0004 אם כן \u0003מאי טעמא\u0004 \u0005[מהו הטעם]\u0006 של \u0003בית הלל\u0004 שהתירו? \u0003אמר רב הונא: לעולם אימא לך\u0004 \u0005[אומר לך]\u0006 שמדובר באופן \u0003שלא הניח עירובי תבשילין,\u0004 וטעמם של בית הלל, משום שלהניח משהו שאינו שיעור סעודה גדולה אלא \u0003כדי חייו\u0004 בלבד, \u0003שרו ליה רבנן\u0004 \u0005[התירו לו חכמים].\u0006","ומעירים: \u0003ורב הונא לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 ש\u0003אמר רב הונא: מי שלא הניח עירובי תבשילין\u0004 מערב יום טוב, מכל מקום \u0003אופין לו פת אחת, ומבשלין לו קדרה אחת\u0004 של תבשיל,"],["\u0003ומדליקין לו את הנר, משום ר' יצחק אמרו: אף צולין לו דג קטן. תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]\u0006 \u0003מי שלא הניח ערובי תבשילין\u0004 — \u0003אופין לו פת אחת, וטומנין לו קדרה אחת, ומדליקין לו את הנר, ומחמין לו\u0004 (ומחממים עבורו) \u0003קיתון\u0004 (כלי קטן) \u0003אחד\u0004 של מים, \u0003ויש אומרים אף צולין לו דג קטן.\u0004","\u0003רבא אמר: לעולם\u0004 תפרש \u0003שהניח\u0004 עירוב תבשילין, ובכל זאת אם לא הטמין מערב החג לצורך השבת — לא יטמין בחג עצמו, כי \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003הטמנה, דמוכחא מלתא דאדעתא\u0004 \u0005[שמוכח הדבר שעל דעת]\u0006 ה\u0003שבת קעביד\u0004 \u0005[הוא עושה]\u0006 ולא לצורך יום טוב, ולדעת בית שמאי יש בכך משום חילול קדושת יום טוב.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003אביי\u0004 מברייתא, שבה שנינו, \u0003חנניה אומר: בית שמאי אומרים: אין אופין\u0004 בחג לצורך שבת העתידה לחול למחרת \u0003אלא אם כן ערב בפת, ואין מבשלין אלא אם כן ערב בתבשיל, ואין טומנין\u0004 בשביל שבת \u0003אלא אם כן היו לו חמין טמונין מערב יום טוב.\u0004 ומכאן נסיק: \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003היו לו חמין טמונין — מיהא עביד\u0004 \u0005[בכל אופן עושה]\u0006 וטומן חמין לשבת, \u0003ואף על גב דמוכחא מלתא דאדעתא\u0004 \u0005[ואף על פי שמוכח הדבר שעל דעת]\u0006 ה\u0003שבת קעביד\u0004 \u0005[הוא עושה],\u0006 ומשמע שאף לדעת חנניה, שהחמיר בשיטת בית שמאי, מכל מקום מותר להטמין מיום טוב לשבת!","\u0003אלא אמר אביי:\u0004 כאן מדובר \u0003כגון שערב לזה,\u0004 כלומר, שאפה ובישל מבעוד יום לשם עירוב \u0003ולא ערב לזה,\u0004 שלא הטמין חמין מבעוד יום, \u0003ו\u0004דבר זה כשיטת \u0003חנניה היא, ואליבא\u0004 \u0005[ועל פי שיטת]\u0006 \u0003בית שמאי.\u0004 ובית רבן גמליאל החמירו על עצמם בענין זה.","נאמר במשנה שאחד משלושת הדברים בהם היה מחמיר רבן גמליאל כדברי בית שמאי הוא ש\u0003אין זוקפין\u0004 ביום טוב \u0003את המנורה\u0004 שנפלה. ושואלים: \u0003מאי קא עביד\u0004 \u0005[מה הוא עושה],\u0006 מה איסור יש בזקיפת המנורה? \u0003אמר רב חיננא בר ביסנא: הכא\u0004 \u0005[כאן]\u0006 \u0003במנורה של חליות\u0004 (שמתפרקת) \u0003עסקינן\u0004 \u0005[עוסקים אנו],\u0006 \u0003דמחזי\u0004 \u0005[שנראה]\u0006 \u0003כבונה,\u0004 אם זוקף אותה מחדש. ש\u0003בית שמאי סברי\u0004 \u0005[סבורים]\u0006 כי \u0003יש\u0004 דין \u0003בנין בכלים\u0004 ולכן אסור לדעתם לזוקפה מחדש, \u0003ובית הלל סברי\u0004 \u0005[סבורים]\u0006 כי \u0003אין\u0004 דין \u0003בנין בכלים, ואין\u0004 דין \u0003סתירה בכלים,\u0004 ולכן אם נפלה — מותר לזוקפה.","אגב כך מסופר: \u0003עולא איקלע לבי\u0004 \u0005[הזדמן לבית]\u0006 \u0003רב יהודה, קם שמעיה זקף לה לשרגא\u0004 \u0005[עמד שמשו\u0006 של עולא \u0005וזקף את נר\u0006 השמן\u0005]\u0006 ועל ידי כך פנה רוב השמן לצד אחד, ונתכוון השמש שלא יגיע השמן לפתילה ועל ידי כך ימהר הנר לכבות. \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב יהודה לעולא:\u0004 הלא שנינו \u0003הנותן שמן בנר\u0004 בשבת — \u0003חייב משום מבעיר\u0004 בשבת \u0003והמסתפק\u0004 (והלוקח) מן השמן הזה בשבת — \u0003חייב משום מכבה\u0004 לפי שהוא מחיש את הכיבוי. משמע שכל פעולה המזרזת את כיבוי הנר, אפילו לא נעשתה במישרין, נחשבת ככיבוי, ואף כאן, כיון שזקף השמש את הנר, נמצא כמכבה ביום טוב, והדבר אסור! \u0003אמר ליה\u0004 \u0005[לו]\u0006 עולא: אכן צודק אתה, \u0003לאו אדעתאי\u0004 \u0005[לא\u0006 נעשה הדבר \u0003על דעתי].\u0004","בדין זה של חשש לכיבוי ביום טוב, \u0003אמר רב: קנבא שרי\u0004 \u0005[מותר\u0006 לשבור את \u0005ראש הפתילה]\u0006 שנעשה פחם, כדי שתבער יפה, ואין בכך משום כיבוי.","ועוד לענין כיבוי ביום טוב, \u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003אבא בר מרתא מאביי: מהו לכבות\u0004 ביום טוב \u0003את הנר\u0004 שבחדר \u0003מפני דבר אחר\u0004 (תשמיש)? שכיון שאסור לאדם לשמש מיטתו במקום שהנר דולק בו, האם מותר לכבות את הנר לצורך זה? \u0003אמר לו:\u0004 לא יכבה, כי \u0003אפשר\u0004 לשמש מיטתו \u0003בבית\u0004 (חדר) \u0003אחר.\u0004","אמר לו: ומי ש\u0003אין לו בית אחר מאי\u0004 \u0005[מה\u0006 יעשה\u0005]?\u0006 אמר לו: \u0003אפשר לעשות לו מחיצה\u0004 על ידי סדינים לנר, וישמש מיטתו מעבר למחיצה. חזר ושאל: כש\u0003אין לו\u0004 סדינים כדי \u0003לעשות מחיצה מאי\u0004 \u0005[מה\u0006 יעשה\u0005]?\u0006 אמר לו: \u0003אפשר לכפות\u0004 (להפוך) \u0003עליו\u0004 (על הנר) \u0003את הכלי\u0004 ולא ייראה האור. ושאל עוד: \u0003אין לו כלי מאי\u0004 \u0005[מה\u0006 יעשה\u0005]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אסור\u0004 ואין היתר לכבות.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 ממה ששנינו: \u0003אין מכבין את הבקעת\u0004 (חתיכת עץ) \u0003כדי לחוס עליה\u0004 שלא תכלה לחנם, \u0003ואם בשביל שלא יתעשן הבית או הקדרה\u0004 — \u0003מותר,\u0004 הרי שמותר לכבות ביום טוב אם היה זה לצורך אדם! \u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: \u0003ההיא\u0004 \u0005[אותה\u0006 ברייתא\u0005]\u0006 כדעת \u0003ר' יהודה היא,\u0004 המתיר גם מלאכות שיש בהם משום הנאה לאדם אף שאינן צורך אוכל נפש, \u0003כי קאמינא אנא לרבנן\u0004 \u0005[כאשר אומר אני\u0006 הרי זה \u0005ל\u0006שיטת \u0005חכמים].\u0006","ועוד בענין כיבוי, \u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003אביי מרבה: מהו לכבות את הדלקה ביום טוב?\u0004 והוא מסביר את שאלתו: \u0003היכא דאיכא\u0004 \u0005[במקום שיש]\u0006 \u0003סכנת נפשות\u0004 בדליקה זו — \u0003לא קא מבעיא לי\u0004 \u0005[אין אני מסופק],\u0006 ש\u0003אפילו בשבת שרי\u0004 \u0005[מותר]\u0006 בכגון זה. \u0003כי קמבעיא לי\u0004 \u0005[כאשר נסתפק לי]\u0006 הרי זה כשיש בכך \u0003משום אבוד ממון, מאי\u0004 \u0005[מה\u0006 הדין\u0005]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אסור.\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 ממה ששנינו: \u0003אין מכבין את הבקעת כדי לחוס עליה, ואם בשביל שלא יתעשן הבית או הקדרה\u0004 — \u0003מותר,\u0004 הרי שאפילו בשביל הפסד מועט מותר! ענה לו: הברייתא \u0003ההיא\u0004 כדעת \u0003ר' יהודה היא, כי קאמינא אנא\u0004 \u0005[כאשר אומר אני]\u0006 את דברי, הרי זה לשיטת \u0003רבנן\u0004 \u0005[חכמים].\u0006","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רב אשי מאמימר: מהו לכחול\u0004 (למשוח) \u0003את העין ביום טוב\u0004 בסממני רפואה? והוא מסביר את השאלה: \u0003היכא דאיכא\u0004 \u0005[במקום שיש]\u0006 \u0003סכנה\u0004 לעין \u0003כגון\u0004 המחלות הקרויות \u0003רירא, דיצא, דמא, דמעתא, וקדחתא,\u0004 או \u0003תחלת אוכלא\u0004 \u0005[הדלקת]\u0006 \u0003— לא מבעיא\u0004 \u0005[אין ספק]\u0006 \u0003לי\u0004 כי אז \u0003אפילו בשבת שרי\u0004 \u0005[מותר],\u0006 \u0003כי קמבעיא\u0004 \u0005[כאשר נסתפק]\u0006 \u0003לי\u0004 במחלות פחות קשות, כגון \u0003סוף אוכלא\u0004 \u0005[הדלקת]\u0006 \u0003ופצוחי עינא\u0004 \u0005[פקיחת העין]\u0006 להיטיב את הראיה \u0003מאי\u0004 \u0005[מה\u0006 הדין בו\u0005]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אסור,\u0004 שכיון שאין בכך סכנה לעין, אלא מיחוש בלבד — אין עושים רפואה ביום טוב.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 מאותה ברייתא: \u0003אין מכבים את הבקעת\u0004 וכו', \u0003ושני ליה כדשנין\u0004 \u0005[ותירץ לו כפי שתירצנו]\u0006 שברייתא זו כדעת ר' יהודה היא.","מסופר: \u0003אמימר שרי למכחל עינא\u0004 \u0005[התיר למשוח עין]\u0006 על ידי \u0003גוי בשבתא\u0004 \u0005[בשבת]\u0006 לצורך רפואה. \u0003איכא דאמרי\u0004 \u0005[יש אומרים]:\u0006 \u0003אמימר גופיה\u0004 \u0005[עצמו]\u0006 \u0003כחל עינא\u0004 \u0005[משח את עינו]\u0006 על ידי \u0003גוי בשבתא\u0004 \u0005[בשבת].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי לאמימר: מאי דעתיך\u0004 \u0005[מה דעתך]\u0006 בזה — שאתה סומך על מה ש\u0003אמר עולא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב עילאי\u0004 ש\u0003כל צרכי חולה עושין על ידי גוי בשבת,\u0004 וכן \u0003אמר רב המנונא: כל דבר שאין בו סכנה\u0004 של נפשות, אבל יש בו מחלה — \u0003אומר לגוי ועושה\u0004 עבורו.","אולם \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים, \u0003היכא דלא מסייע בהדיה\u0004 \u0005[במקום שאין\u0006 החולה או אדם אחר מישראל \u0005מסייע עמו]\u0006 עם הגוי ההוא, \u0003אבל מר קא מסייע בהדיה, דקא עמיץ ופתח\u0004 \u0005[אדוני הרי מסייע לו\u0006 בשעת המשיחה, \u0005שהוא סוגר ופותח\u0006 את העין\u0005]\u0006 שעל ידי זה נכנס הכחול לתוך העין, ודבר זה צריך היה לאסור! \u0003אמר ליה\u0004 \u0005[לו]\u0006 אמימר: \u0003איכא\u0004 \u0005[יש]\u0006 עוד את דעתו של \u0003רב זביד דקאי כותך\u0004 \u0005[שהוא עומד בשיטתך],\u0006 שאף הוא סבר שיש בכך משום סיוע לאיסור ויש לאוסרו בשל כך, \u0003ושניי ליה\u0004 \u0005[ו\u0006כבר \u0005תירצתי לו]:\u0006 \u0003מסייע אין בו ממש,\u0004 שכיון שעיקר הדבר נעשה על ידי הגוי, אין חוששים משום סיוע כלשהו שעושה הישראל.","מסופר עוד: \u0003אמימר שרא למכחל עינא\u0004 \u0005[התיר לכחול את העין]\u0006 \u0003ביום טוב שני של ראש השנה\u0004 כאשר העין כואבת, וזקוק לכך. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי לאמימר: והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבא: מת ביום טוב ראשון\u0004 — \u0003יתעסקו בו עממין\u0004 (גויים) לקבור אותו, מת \u0003ביום טוב שני\u0004 — \u0003יתעסקו בו ישראל,\u0004 ודין זה — \u0003ואפילו בשני ימים טובים של ראש השנה\u0004"],["\u0003מה שאין כן בביצה\u0004 שנולדה ביום טוב! ששני הימים נחשבים כקדושה אחת. הרי שרק לענין קבורת המת התירו, אבל בשאר דברים — שני ימים טובים של ראש השנה נחשבים כיום אחד!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 אמימר: \u0003אנא כנהרדעי סבירא לי\u0004 \u0005[אני כדעת\u0006 חכמי \u0005נהרדעא סבור אני],\u0006 \u0003דאמרי\u0004 \u0005[שאמרו]\u0006 דין זה \u0003אף בביצה\u0004 שנולדה, והוא הדין לשאר דברים, שאין הבדל בין שני ימי ראש השנה לשאר ימים טובים. \u0003ומאי דעתיך\u0004 \u0005[ומה דעתך]\u0006 למה חושש אתה — \u0003דלמא מעברי ליה\u0004 \u0005[שמא יעברו אותו]\u0006 את חודש \u0003אלול\u0004 ויתברר אז שהיום השני הוא אכן ראש השנה האמיתי — \u0003האמר\u0004 \u0005[הרי\u0006 כבר \u0005אמר]\u0006 \u0003רב חיננא בר כהנא: מימות עזרא ואילך לא מצינו\u0004 שיהא \u0003אלול מעובר,\u0004 ואם כן אין מקום לחשוש לכך.","שנינו במשנה: \u0003ואין אופין פתין גריצין אלא רקיקין. תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003בית שמאי אומרים: אין אופין פת עבה בפסח, ובית הלל מתירין. וכמה\u0004 שיעורה של \u0003פת עבה\u0004 שהתירו בית הלל — \u0003אמר רב הונא:\u0004 עוביה \u0003טפח. שכן מצינו\u0004 (מצאנו) \u0003בלחם הפנים\u0004 במקדש, שאף הוא אסור שיהא חמץ והיה עוביו \u0003טפח.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב יוסף: אם אמרו\u0004 היתר זה בכהנים שהם \u0003זריזין\u0004 ויכולים לאפות פת שעוביה טפח מבלי שיהיה בה חשש חימוץ — \u0003יאמרו\u0004 כמו כן \u0003ב\u0004שאר אנשים \u0003שאינן זריזין? אם אמרו בפת עמלה\u0004 (שנילושה היטב) — \u0003יאמרו\u0004 כמו כן אף \u0003בפת שאינה עמלה?\u0004","\u0003אם אמרו בעצים יבשים\u0004 שהיו משתמשים בהם בבית המקדש, שהם בוערים היטב ונאפה הלחם במהירות, \u0003יאמרו\u0004 כמו כן אף \u0003בעצים לחים,\u0004 שרוב בני אדם משתמשים בהם? \u0003אם אמרו בתנור חם\u0004 של המקדש \u0003יאמרו\u0004 כמו כן אף \u0003בתנור\u0004 של כל אדם שהוא בדרך כלל \u0003צונן\u0004 מזה של המקדש? \u0003אם אמרו בתנור של מתכת\u0004 שהיה במקדש, המתחמם מהר, \u0003יאמרו\u0004 כמו כן אף \u0003בתנור של חרס\u0004 שרוב בני האדם אופים בו לחמיהם?","\u0003אמר רב ירמיה בר אבא: שאלית\u0004 \u0005[שאלתי]\u0006 \u0003את רבי ביחוד\u0004 (ביני לבינו) \u0003ומנו\u0004 \u0005[ומי הוא]\u0006 רבי זה — \u0003רב,\u0004 ושאלתי היתה: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"פת עבה\"?\u0004 והסביר לי, שפירושו, \u0003פת מרובה.\u0004 ואין הטעם משום חשש חמץ, אלא משום שיש באופן אפייתה משום טירחה יתירה בחג.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 באופן זה \u0003אמר רב ירמיה בר אבא אמר רב: שאלית\u0004 \u0005[שאלתי]\u0006 דבר זה \u0003את רבי ביחוד, ומנו\u0004 \u0005[ומי הוא]\u0006 רבו של רב — \u0003רבינו הקדוש,\u0004 והסביר לי: \u0003מאי\u0004 \u0005[מה\u0006 הפירוש\u0005]\u0006 \u0003\"פת עבה\" — פת מרובה, ואמאי\u0004 \u0005[ומדוע]\u0006 \u0003קרו ליה\u0004 \u0005[קוראים לה]\u0006 \u0003פת עבה\u0004 — \u0003משום דנפישא\u0004 \u0005[ש\u0006היא \u0005מרובה]\u0006 \u0003ב\u0004שעת \u0003לישה\u0004 ובשעת לישתה הריהי נראית עבה ביותר. \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 \u0003באתריה דהאי תנא\u0004 \u0005[במקומו של תנא זה],\u0006 \u0003פת מרובה\u0004 — \u0003\"פת עבה\" קרו ליה\u0004 \u0005[קוראים לה].\u0006","ושואלים: \u0003מכדי\u0004 \u0005[הרי]\u0006 האיסור \u0003משום דקטרח\u0004 \u0005[שהוא טורח]\u0006 \u0003טרחא דלא צריך\u0004 \u0005[שאינו צריך]\u0006 \u0003הוא,\u0004 אם כן \u0003מאי אריא\u0004 \u0005[מה שייך]\u0006 מדוע דווקא, שנינו דין זה ב\u0003פסח? אפילו בשאר ימים טובים נמי\u0004 \u0005[גם כן]!\u0006 ומשיבים: \u0003אין הכי נמי\u0004 \u0005[כן, כך\u0006 הוא \u0005גם כן]\u0006 ואין דין מיוחד זה לפסח. \u0003ותנא\u0004 זה שאמר את הדברים, \u0003ביום טוב\u0004 של \u0003פסח קאי\u0004 \u0005[עמד]\u0006 וכיון שדן בשאר דברים השייכים לפסח אמר גם הלכה זו כאחד מדיני הפסח, אבל הוא הדין לחגים אחרים. ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך],\u0006 \u0003בית שמאי אומרים: אין אופין פת מרובה ביום טוב, ובית הלל מתירין.\u0004","\u0003אף הוא\u0004 רבן גמליאל \u0003אמר שלשה דברים להקל\u0004 כנגד דעת רוב החכמים: \u0003מכבדין\u0004 (מטאטאים) את \u0003בית המטות,\u0004 מקום שהיו יושבים בו לאכול כשהם מסובים על גבי מיטות, ואין חוששים שמא על יד כיבוד זה הריהו מיישר את הגומות שבאדמה. \u0003ו\u0004כמו כן \u0003מניחין את המוגמר\u0004 (מיני בשמים) על גבי גחלים בוערות כדי לבשם את הבית \u0003ביום טוב. ו\u0004כן \u0003עושין גדי מקולס\u0004 שצולים אותו בשלימות כשאבריו הפנימיים בסמוך לו \u0003בלילי פסחים\u0004 כדרך שהיו עושים במקדש. \u0003וחכמים אוסרין\u0004 בכל שלושת הדברים הללו, בכיבוד — משום חשש יישור גומות, בנתינת מוגמר על גבי גחלים — משום שאין בכך צורך אוכל נפש, ובגדי מקולס — משום שנראה כמקריב קדשים בחוץ.","\u0003אמר רב אסי: מחלוקת\u0004 זו במוגמר היא כאשר הוא מניחו \u0003לגמר,\u0004 כלומר: לבשם בגדים על ידי הבשמים הללו, \u0003אבל\u0004 כאשר מניחו כדי \u0003להריח\u0004 — \u0003דברי הכל מותר\u0004 שדבר זה הוא כשאר הנאות ובכלל אוכל נפש הוא.","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 ממה ששנינו בתוספתא: \u0003אין מכבדין\u0004 את \u0003בית המטות ביום טוב\u0004 מפני חשש יישור הגומות, \u0003ושל בית רבן גמליאל\u0004 היו \u0003מכבדין\u0004 ולא חששו לכך. \u0003אמר ר' אלעזר בר' צדוק: פעמים הרבה נכנסתי אחר אבא,\u0004 ר' צדוק, \u0003לבית רבן גמליאל ו\u0004ראיתי ש\u0003לא היו מכבדין\u0004 ממש את \u0003בית המטות ביום טוב, אלא\u0004 כך היו עושים: \u0003מכבדין אותן מערב יום טוב, ופורסין עליהם סדינין\u0004 כדי שלא יתלכלכו, ו\u0003למחר כש\u0004ה\u0003אורחים\u0004 היו \u0003נכנסין,\u0004 היו \u0003מסלקין את הסדינין ונמצא הבית מתכבד\u0004 (מתנקה) \u0003מאליו. אמרו לו: אם כן\u0004 — \u0003אף בשבת מותר לעשות כן,\u0004 ולא בזה נחלקו.","וכן \u0003ואין מניחין את המוגמר ביום טוב\u0004 על גבי גחלים בוערות, \u0003ושל בית רבן גמליאל\u0004 היו \u0003מניחין. אמר ר' אליעזר בר' צדוק: פעמים הרבה נכנסתי אחר אבא לבית רבן גמליאל, ולא היו מניחין את המוגמר ביום טוב\u0004 ממש, \u0003אלא\u0004 היו \u0003מביאין ערדסקאות\u0004 (מחתות נקובות) \u0003של ברזל ומעשנין אותן\u0004 (ממלאים אותם בעשן מבושם) \u0003מערב יום טוב, ופוקקין נקביהן מערב יום טוב\u0004 כדי שלא ייצא מתוכם ריח הבושם, ו\u0003למחר כש\u0004היו ה\u0003אורחים נכנסין\u0004 היו \u0003פותחין את נקביהן\u0004 והריח יוצא ומתפזר בבית, \u0003ונמצא הבית מתגמר\u0004 (מתבשם) \u0003מאליו.\u0004","\u0003אמרו לו: אם כן\u0004 — \u0003אף בשבת מותר לעשות כן.\u0004 ולענייננו למדנו שלא דובר כאן על בישום בגדים, אלא אף על הולדת הריח עצמו.","\u0003אלא\u0004 עלינו לחזור מן הדבר כפי שאמרנו, ו\u0003אי אתמר הכי אתמר\u0004 \u0005[\u0006ו\u0005אם נאמר\u0006 דבר בענין זה \u0005כך נאמר],\u0006 \u0003אמר רב אסי: מחלוקת\u0004 זו היא כשעושים כן כדי \u0003להריח, אבל\u0004 אם עשו כן כדי \u0003לגמר\u0004 (לבשם את הבגדים) — לדעת הכל \u0003אסור.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 השאלה: \u0003מהו\u0004 האם מותר \u0003לעשן\u0004 פירות ביום טוב בעשן בשמים בוערים כדי לבשם את ריחם? \u0003רב ירמיה בר אבא אמר\u0004 בשם \u0003רב: אסור,\u0004 לפי שאין בכך משום אוכל נפש. \u0003ושמואל אמר: מותר. רב הונא אמר: אסור, מפני שמכבה,\u0004 שכאשר מניחים את אבקת עצי הבושם על הגחלים הרי הן כבות מעט. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן: ונימא מר\u0004 \u0005[ושיאמר אדוני]\u0006 \u0003מפני שמבעיר,\u0004 שהרי אחר כך הבשמים מבעירים את הגחלים ביתר שאת, ומדוע אין אתה חושש להבערה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 אכן כך הוא, ושני איסורים יש בדבר — \u0003תחלתו מכבה וסופו מבעיר.\u0004","\u0003אמר רב יהודה:\u0004 להניח אבקת בשמים \u0003על גבי\u0004 ה\u0003גחלת\u0004 עצמה — \u0003אסור,\u0004 מפני הטעמים שהסברנו."],["אבל להניחה \u0003על גבי חרס\u0004 לוהט — \u0003מותר,\u0004 משום שאין בו חשש כיבוי והבערה.","\u0003ורבה אמר: על גבי חרס נמי\u0004 \u0005[גם כן]\u0006 \u0003אסור משום דקא מוליד ריחא\u0004 \u0005[שהוא מוליד ריח]\u0006 חדש בחרס, וביום טוב אסור ליצור דברים חדשים. ומעירים, כיוצא בו \u0003רבה ורב יוסף דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]\u0006 הלכה זו: \u0003סחופי כסא אשיראי ביומא טבא\u0004 \u0005[לכפות כוס\u0006 שיש בו בושם \u0005על בגדי משי ביום טוב]\u0006 — \u0003אסור, מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של איסור זה — \u0003משום דקמוליד ריחא\u0004 \u0005[שהוא מוליד ריח\u0006 חדש\u0005]\u0006 בבגד,","ושואלים: \u0003ומאי שנא\u0004 \u0005[ובמה שונה\u0006 הדבר\u0005]\u0006 \u0003ממוללו ומריח בו וקוטמו ומריח בו?\u0004 שהרי מותר לקחת עצי בשמים ולמלול (ללחוץ אותם בין האצבעות) ולהריח בהם, וכן לקטום אותם כדי שידיף מקום הקטימה ריח, הלא גם אז מוליד הוא ריח! ומשיבים: \u0003התם ריחא מיהא איתא, ואוסופי הוא דקא מוסיף ריחא\u0004 \u0005[שם ריח מכל מקום ישנו, והוספה הוא שמוסיף בו ריח],\u0006 שעל ידי המלילה או הקיטום נעשה הריח חריף וניכר יותר, אבל \u0003הכא\u0004 \u0005[כאן]\u0006 בכפיית כוס שיש בה בושם על גבי בגדים \u0003— אולודי הוא דקמוליד ריחא\u0004 \u0005[מוליד הוא ריח\u0006 חדש\u0005].\u0006 ואילו \u0003רבא אמר: על גבי גחלת נמי\u0004 \u0005[גם כן]\u0006 \u0003מותר\u0004 להניח אבקת בושם (לבונה), \u0003מידי דהוה אבשרא אגומרי\u0004 \u0005[כשם שהוא\u0006 מותר להניח \u0005בשר על גבי גחלים]\u0006 לצלותו, כך מותר להניח עליהם לבונה להריח.","מסופר, \u0003דרש רב גביהא מבי כתיל אפתחא דבי ריש גלותא\u0004 \u0005[על פתחו של בית ראש הגולה]:\u0006 \u0003קטורא שרי\u0004 \u0005[מותרת]\u0006 ביום טוב. בלשון זו אמר, ולא היו הדברים מובנים כל צרכם. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אמימר מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"קטורא\"\u0004 זו שאמרת? \u0003אי קטורא בידי\u0004 \u0005[אם\u0006 כוונתך \u0005לקשור ביד\u0006 עניבות של קישוט\u0005]\u0006 הלא דבר זה \u0003מעשה אומן הוא\u0004 ובודאי אסור ביום טוב. ואם כוונתך \"קטורא\" מלשון קטורת \u0003לעשן\u0004 — הרי אף זה \u0003אסור, דהא קא\u0004 \u0005[שהרי הוא]\u0006 \u0003מכבה! אמר רב אשי: לעולם\u0004 הכוונה \u0003לעשן, מידי דהוה אבשרא אגומרי\u0004 \u0005[\u0006ו\u0005בדרך שהוא בבשר על גחלים]\u0006 שמותר.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שלא כך היה המעשה, אלא בשינוי מעט. ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אמימר\u0004 לרב גביהא: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"קטורא\"? אי קטורא בידי\u0004 \u0005[אם קשירה בידים]\u0006 — הלא \u0003מעשה אומן הוא\u0004 ואסור, \u0003אי\u0004 \u0005[אם]\u0006 הכוונה היא \u0003לעשן\u0004 — הרי \u0003אסור\u0004 משום \u0003דקא מוליד ריחא\u0004 \u0005[שהוא מוליד ריח]!\u0006 \u0003אמר רב אשי: אנא אמריתה נהליה\u0004 \u0005[אני אמרתי אותה,\u0006 את ההלכה הזאת\u0005],\u0006 לרב גביהא, \u0003ומשמיה דגברא רבה אמריתה נהליה\u0004 \u0005[ומשמו של אדם גדול,\u0006 רבא, \u0005אמרתי\u0006 אותה לו\u0005],\u0006 ש\u0003לעולם\u0004 הכוונה היא \u0003לעשן, ומידי דהוה אבשרא אגומרי\u0004 \u0005[ובדרך שהוא בבשר על גחלים],\u0006 שמותר להניח אותו עליהם, ואין חוששים.","שנינו במשנה שאחד משלושת הדברים בהם דעת רבן גמליאל להקל, ש\u0003עושין גדי מקולס\u0004 בליל פסח. בענין זה \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 \u0003ר' יוסי אומר: תודוס איש רומי הנהיג את בני רומי לאכול גדי מקולס בלילי פסחים,\u0004 זכר למקדש. \u0003שלחו ליה\u0004 \u0005[לו]\u0006 חכמים: \u0003אלמלא תודוס אתה\u0004 שאתה אדם חשוב \u0003גוזרנו\u0004 (היינו גוזרים) \u0003עליך נדוי, שאתה מאכיל את בני ישראל קדשים בחוץ.\u0004","ותוהים על הלשון: \u0003קדשים סלקא דעתך\u0004 \u0005[עולה על דעתך]?!\u0006 ודאי לא היו אלה קדשים! \u0003אלא אימא\u0004 \u0005[אמור]:\u0006 \u0003כעין קדשים,\u0004 שעלולים אנשים לטעות ולחשוב שגדי זה הוא לקרבן פסח.","\u0003שלשה דברים ר' אלעזר בן עזריה מתיר וחכמים אוסרים: פרתו יוצאה\u0004 בשבת \u0003ברצועה שבין קרניה\u0004 שקושרים לה לנוי, שלדעת ר' אלעזר אין בכך משום משא ועבודה לפרה, אלא נוי ותכשיט הוא לה, ולדעת חכמים אינו אלא משא.","\u0003ומקרדין\u0004 \u0003את הבהמה ביום טוב\u0004 להוציא את הלכלוך שבשערה ואין חוששים שמא יעשה בה פצע או חבורה עקב כך, ולדעת חכמים יש לחשוש שמא תיפצע. \u0003ושוחקים את הפלפלין\u0004 לצורך יום טוב אפילו \u0003ברחים שלהן\u0004, לפי שהדבר נראה כמלאכת חול.","\u0003ר' יהודה אומר: אין מקרדין\u0004 (מסרקים ומורידים את הקרציות) \u0003את הבהמה ביום טוב מפני\u0004 שבודאי \u0003עושה חבורה\u0004 (פצעים), \u0003אבל מקרצפין\u0004 במסרק של עץ ששיניו גסות ואינו גורם לפצעים. \u0003וחכמים אומרים: אין מקרדין, אף לא מקרצפין.\u0004","על הביטוי במשנה \"פרתו יוצאה\" שואלים: \u0003למימרא\u0004 \u0005[האם לומר]\u0006 ש\u0003ר' אלעזר בן עזריה חדא פרה הויא ליה\u0004 \u0005[פרה אחת היתה לו]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003אמר\u0004 זאת \u0003רב יהודה אמר רב: תליסר אלפי עגלי\u0004 \u0005[שלושה עשר אלף עגלים]\u0006 \u0003הוה\u0004 \u0005[היה]\u0006 \u0003מעשר ר' אלעזר בן עזריה מעדריה\u0004 \u0005[מעדרו]\u0006 \u0003כל שתא ושתא\u0004 \u0005[כל שנה ושנה]\u0006 ומתוך שמספר עגלים זה היה רק עשירית מעדרו שבכל שנה, קל איפוא לשער כמה מרובים היו עדרי הבקר שלו. ואם כן מה לשון \"פרתו\" שנקט כאן? \u0003תנא\u0004 \u0005[שנה\u0006 החכם בתוספתא\u0005]:\u0006 \u0003לא שלו היתה\u0004 פרה זו \u0003אלא של שכנתו היתה, ומתוך שלא מיחה בה\u0004 (שהרי לדעתו הדבר מותר) — \u0003נקראת על שמו\u0004 כאילו היתה זו פרתו שלו, שהאחריות מוטלת עליו.","שנינו במשנה כי לדעת ר' אלעזר בן עזריה \u0003מקרדין את הבהמה ביום טוב. תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003איזהו קרוד ואיזהו קרצוף? קרוד\u0004 הוא במסרק שיש בו שינים \u0003קטנים ועושים חבורה, קרצוף\u0004 — שינים \u0003גדולים ואין עושין חבורה.\u0004","\u0003ושלש מחלוקות\u0004 יש \u0003בדבר, ר' יהודה\u0004 אמנם \u0003סבר: דבר שאינו מתכוון אסור,\u0004 שאסור לדעתו לעשות בשבת דבר שיש בו משום מלאכה, ואפילו אם אינו מתכוון לצורך מלאכה זו אלא לדבר אחר שהוא מותר בעיקרו, ולכן אסור לדעתו לסרק את הבהמה באופן שעושה בה אגב כך חבורה, אף שאינו מתכוון לכך. \u0003מיהו\u0004 \u0005[מכל מקום]\u0006 הוא מחלק: ב\u0003קרוד\u0004 על ידי מסרק בעל שינים \u0003קטנים ועושין חבורה\u0004 — אסור. אבל \u0003קרצוף\u0004 במסרק בעל שינים \u0003גדולים ואין עושים חבורה\u0004 — מותר, \u0003ולא גזרינן\u0004 \u0005[ואין אנו גוזרים]\u0006 \u0003קרצוף אטו\u0004 \u0005[משום]\u0006 \u0003קרוד\u0004 ואין חוששים שיטעו ויבואו להתיר אף את האסור.","\u0003ורבנן סברי נמי\u0004 \u0005[וחכמים סבורים גם כן]\u0006 \u0003כר' יהודה\u0004 לגבי עיקר שיטתו ש\u0003דבר שאינו מתכוון אסור,\u0004 אלא לדעתם \u0003גזרינן\u0004 \u0005[גוזרים אנו]\u0006 \u0003קרצוף אטו\u0004 \u0005[משום]\u0006 \u0003קרוד. ו\u0004אילו \u0003ר' אלעזר בן עזריה סבר לה\u0004 \u0005[סבור הוא]\u0006 בענין זה \u0003כ\u0004דעת \u0003ר' שמעון,\u0004 ש\u0003אמר: דבר שאינו מתכוון\u0004 — \u0003מותר,\u0004 ולכן, \u0003בין קרוד בין קרצוף שרי\u0004 \u0005[מותר],\u0006 וגם אם נעשית תוך כדי הסירוק חבורה, כיון שודאי אינו מתכוון לכך — אין בכך איסור.","\u0003אמר רבא אמר רב נחמן אמר שמואל, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003אמר רב נחמן\u0004 שמועה זו \u0003לחודיה\u0004 \u0005[לבדו,\u0006 בעצמו\u0005]:\u0006 \u0003הלכה כר' שמעון\u0004 שדבר שאין מתכוון מותר לעשותו בשבת, \u0003שהרי ר' אלעזר בן עזריה מודה לו. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרב נחמן: ולימא מר\u0004 \u0005[ושיאמר אדוני]\u0006 להיפך, \u0003הלכה כר' יהודה שהרי חכמים מודים לו! אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אנא\u0004 \u0005[אני]\u0006 בכלל \u0003כ\u0004שיטת \u0003ר' שמעון סבירא לי\u0004 \u0005[סבור אני],\u0006 שכך יש לפסוק, אולם אני מוסיף \u0003עוד\u0004 טעם לכך \u0003שהרי ר' אלעזר בן עזריה מודה לו.\u0004"],["\u0003הרחים של פלפלין\u0004 שהוזכרה קודם כלי מורכב הוא וכל אחד מחלקיו נדון בפני עצמו ונטמא בפני עצמו, ולכן \u0003טמאה משום שלשה כלים: משום כלי קבול\u0004 של עץ, \u0003ומשום כלי מתכת, ומשום כלי כברה.\u0004","\u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003תחתונה\u0004 החלק התחתון של הרחים נדון \u0003משום כלי קבול\u0004 שהרי אליו יורד הפלפל השחוק. \u0003אמצעית\u0004 — \u0003משום כלי כברה\u0004 שבה מסתננת שחיקת הפלפל, ואילו ה\u0003עליונה\u0004 שבה טוחנים את הפלפלים — \u0003משום כלי מתכת,\u0004 שאף שאין בה כלי קיבול, כיון שהיא של מתכת — מקבלת היא טומאה כמות שהיא.","\u0003עגלה של קטן\u0004 (של תינוק) שמשחק בה ואף יושב עליה — \u0003טמאה מדרס.\u0004 כלומר, נחשבת כמקום ישיבה קבוע של התינוק, ואם היה התינוק זב — הריהו מטמא את עגלתו, כשיושב עליה, בטומאת מדרס הזב. \u0003ונטלת\u0004 עגלה זו \u0003בשבת\u0004 שהיא נחשבת ככלי, \u0003ואינה נגררת\u0004 בשבת על הקרקע, \u0003אלא על גבי כלים\u0004 (בגדים), או על גבי מקום מרוצף באבנים, שאם לא כן, הריהי יוצרת בגרירתה חריץ וחייב עליה משום אב מלאכה (חורש).","\u0003ר' יהודה אומר: כל הכלים\u0004 כולם אכן \u0003אין נגררין\u0004 על הקרקע מטעם זה, \u0003חוץ מן העגלה\u0004 שהיא מותרת בכך, \u0003מפני שהיא כובשת\u0004 שהרי הגלגלים אינם חורצים בקרקע כי אם כובשים אותה, ובניגוד לחרישה, אין האדמה זזה ממקומה בפעולה מעין זו, ולכן אין בזה משום חפירה בשבת.","שנינו במשנה כי \u0003עגלה של קטן טמאה מדרס\u0004 ומדוע — \u0003דהא סמיך עלויה\u0004 \u0005[שהוא נשען עליה].\u0006 \u0003ונטלת בשבת — משום דאיכא\u0004 \u0005[שיש]\u0006 \u0003תורת כלי עלה\u0004 \u0005[עליה]\u0006 וכלי מותר לטלטל בשבת. עוד שנינו במשנה כי עגלת התינוק \u0003אינה נגררת אלא על גבי כלים.\u0004 ומדייקים: על \u0003גבי כלים — אין\u0004 \u0005[כן],\u0006 \u0003על גבי קרקע — לא. מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]\u0006 — \u0003דקא עביד\u0004 \u0005[\u0006לפי \u0005שהוא עושה]\u0006 \u0003חריץ\u0004 בקרקע אגב הגרירה. ונברר, \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי היא\u0006 הלכה זו\u0005]?\u0006 כדעת \u0003ר' יהודה היא\u0004 ש\u0003אמר דבר שאין מתכוין\u0004 לעשותו, ויש בו משום מלאכה אסורה, אף שנעשה אגב מלאכה מותרת ואין העושה מתכוון לאותה מלאכה אסורה — \u0003אסור.\u0004","","\u0003דאי\u0004 \u0005[שאם]\u0006 כדעת \u0003ר' שמעון\u0004 היא \u0003— האמר\u0004 \u0005[הרי אמר]\u0006 בכלל כי \u0003דבר שאין מתכוון — מותר. דתנן\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 במפורש במשנה\u0005]\u0006 ש\u0003ר' שמעון אומר: גורר אדם מטה כסא וספסל\u0004 על גבי הקרקע, \u0003ובלבד שלא יתכוין לעשות חריץ,\u0004 ואם אינו מתכוון לכך — מותר.","אולם אם כן, \u0003אימא סיפא\u0004 \u0005[אמור את סופה\u0006 של המשנה\u0005]:\u0006 \u0003ר' יהודה אומר אין הכל\u0004 (כל הכלים) \u0003נגררין בשבת, חוץ מן העגלה, מפני שהיא כובשת\u0004 את הקרקע עליה היא נגררת ואינה בכלל מלאכת חורש שהרי אינה יוצרת בה חריץ. משמע: \u0003מפני שכובשת — אין\u0004 \u0005[כן],\u0006 \u0003אבל חריץ — לא עבדא\u0004 \u0005[אינה עושה]\u0006 והלא הוכחנו כי אף החלק הראשון הוא לדעת ר' יהודה, וכיצד חולק הוא על עצמו?","ומשיבים: \u0003תרי תנאי, ואליבא\u0004 \u0005[\u0006מחלוקת \u0005שני תנאים\u0006 היא \u0005ועל פי שיטתו]\u0006 של \u0003ר' יהודה,\u0004 שלדעת התנא הראשון אף עגלה עושה חריץ, ולדעת התנא השני בשם ר' יהודה עגלה אינה עושה חריץ.","","\u0003אין צדין דגים מן הביברין\u0004 (בריכות) \u0003ביום טוב\u0004 גם אם מתכוין לאכלם, שמלאכה זו לא הותרה בחג. \u0003ואין נותנין לפניהם מזונות,\u0004 שאין חובת הזנתם על האדם, אלא ניזונים הם מדגים קטנים מהם, או ממיני אצות הצומחות במים.","\u0003אבל צדין חיה ועוף מן הביברין,\u0004 שכיון שהם בתוך הביברים, הריהם נחשבים כבר כניצודים ושוב אין נחשב הדבר כצידה. \u0003ונותנין לפניהם מזונות\u0004 כמו לחיות הבית. \u0003רבן שמעון בן גמליאל אומר: לא כל הביברין שוין\u0004 לדין ציד, ו\u0003זה הכלל: כל\u0004",""],["כל שהוא בתוך אותן ביברים אבל עדיין הוא \u0003מחוסר צידה\u0004 שהמקום גדול וישנם בתוכו מקומות מסתור וצריך עוד לצוד אותו — \u0003אסור, ושאינו מחוסר צידה\u0004 שאפשר לתפוס אותו מבלי לרדוף אחריו — \u0003מותר.\u0004","\u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה שנאמר בתוספתא: \u0003ביברין של חיה ושל עופות\u0004 — \u0003אין צדין מהם ביום טוב ואין נותנין לפניהם מזונות.\u0004 ואם כן \u0003קשיא\u0004 \u0005[קשה]\u0006 מהדין שנאמר במשנה בענין \u0003חיה\u0004 מהדין שנאמר בתוספתא בענין \u0003חיה,\u0004 וכן \u0003קשיא\u0004 \u0005[קשה]\u0006 מהדין שנאמר במשנה בענין \u0003עופות\u0004 מהדין שנאמר בתוספתא בענין \u0003עופות!\u0004","ומשיבים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003חיה\u0004 על \u0003חיה לא קשיא\u0004 \u0005[קשה];\u0006 כי \u0003הא\u0004 \u0005[זו,\u0006 התוספתא\u0005]\u0006 כשיטת \u0003ר' יהודה\u0004 היא, הסובר כי חיה הנמצאת בביבר עדיין אינה נחשבת כניצודת ולכן אסר על צידתה מן הביבר ביום טוב. \u0003הא\u0004 \u0005[זו,\u0006 משנתנו\u0005]\u0006 כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 היא, הסוברים כי חיה הנמצאת בביבר נחשבת כבר כניצודת ולכן מותר לקחת אותה משם ואין בכך משום צידה מחודשת.","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003ר' יהודה אומר: הצד צפור למגדל\u0004 (לארון) \u0003וצבי לבית\u0004 — \u0003חייב.\u0004 ונדייק: \u0003לבית הוא דמחייב\u0004 \u0005[שמתחייב],\u0006 \u0003אבל\u0004 אם צד את חיה ומכניסה \u0003לביברין\u0004 — \u0003לא. וחכמים אומרים:\u0004 על צידת \u0003צפור\u0004 חייב — אם לאחר הצידה הכניסה \u0003למגדל, וצבי\u0004 — אם הכניסו \u0003לגנה ולחצר ולביברין.\u0004 ואם כן, לשיטת חכמים בעל חיים המצוי בביבר נחשב כבר כניצוד, ואילו לר' יהודה אינו כן, ולפיכך נחלקו גם לענין הוצאתם משם ביום החג.","\u0003אלא, עופות\u0004 על \u0003עופות קשיא\u0004 \u0005[קשה]!\u0006 שהרי לדעת הכל אין לצודם אפילו לבית! \u0003וכי תימא הא נמי לא קשיא\u0004 \u0005[ואם תאמר: זו גם כן אינו קשה];\u0006 כי \u0003הא\u0004 \u0005[זו,\u0006 המשנה\u0005]\u0006 שהתירה צידת עופות מן הביבר, מדברת \u0003בביבר מקורה\u0004 בתקרה והרי הם נחשבים בלא זה כניצודים כבר, \u0003הא\u0004 \u0005[זו,\u0006 התוספתא\u0005]\u0006 שאסרה צידת עופות מן הביברים, מדברת \u0003בביבר שאינו מקורה,\u0004 ואינם נחשבים כניצודים.","אולם דבר זה אי אפשר לומר, \u0003והא\u0004 \u0005[והרי]\u0006 \u0003בית,\u0004 ש\u0003כביבר מקורה דמי\u0004 \u0005[\u0006הוא \u0005נחשב]\u0006 \u0003ובין ל\u0004שיטת \u0003ר' יהודה ובין ל\u0004שיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003צפור למגדל — אין\u0004 \u0005[כן]\u0006 נחשב כדבר ניצוד, אולם \u0003לבית לא,\u0004 שהיא משתמטת ממקום למקום בתוך הבית!","\u0003אמר רבה בר רב הונא: הכא\u0004 \u0005[כאן]\u0006 שאמרו שהכנסת ציפור לבית אינה נחשבת כציד, \u0003בצפור דרור עסקינן\u0004 \u0005[עוסקים אנו],\u0006 \u0003שאינה מקבלת מרות\u0004 כשהיא בבית, ומשתמטת גם בו ממקום למקום. \u0003דתנא דבי\u0004 \u0005[ששנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: למה נקרא שמה\u0004 של זו \u0003צפור דרור\u0004 — משום \u0003שדרה בבית כבשדה,\u0004 שעוברת בתוך הבית ממקום למקום ולכן אינה נבהלת כשמכניסים אותה לבית, ולכך אף אינה נחשבת בכך כניצודה.","ומעירים: \u0003השתא דאתית להכי\u0004 \u0005[עכשיו שהגעת לכך],\u0006 שאין הכרח לומר שיש מחלוקת תנאים בדבר, אלא שמדובר כאן במקרים שונים, יכול אתה לתרץ ולומר כי \u0003חיה\u0004 על \u0003חיה נמי לא קשיא\u0004 \u0005[גם כן איננו קשה],\u0006 כי \u0003הא\u0004 \u0005[זו,\u0006 משנתנו\u0005]\u0006 שהתירה לצוד חיה מן הביברים — הריהי מדברת \u0003בביבר קטן\u0004 שאין לחיה אפשרות להתחמק והריהי נחשבת כבר כניצודת, \u0003הא\u0004 \u0005[זו,\u0006 התוספתא\u0005]\u0006 שאסרה — \u0003בביבר גדול,\u0004 שמפאת גודלו עדיין יש באפשרותה להתחמק ולכך איננה נחשבת בכך עדיין כניצודת.","ושואלים: \u0003היכי דמי\u0004 \u0005[מה נחשב]\u0006 ל\u0003ביבר קטן היכי דמי\u0004 \u0005[מה נחשב]\u0006 ל\u0003ביבר גדול? אמר רב אשי כל היכא דרהיט אבתרה ומטי לה בחד שחיא\u0004 \u0005[כל מקום שהוא רודף אחריה ומשיג אותה בכפיפה אחת]\u0006 — הרי זה \u0003ביבר קטן, ואידך\u0004 \u0005[והאחר]\u0006 שאינו כך — ל\u0003ביבר גדול\u0004 הוא נחשב. \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 \u0003כל היכא דאיכא עוקצי עוקצי\u0004 \u0005[כל מקום שיש בו פינות פינות]\u0006 שיש באפשרותה למצוא שם מקום מסתור — הרי זה \u0003ביבר גדול, ואידך\u0004 \u0005[והאחר]\u0006 נחשב כ\u0003ביבר קטן. אי נמי\u0004 \u0005[או גם כן]\u0006 אפשר לומר: \u0003כל היכא דנפלי טולא דכתלי אהדדי\u0004 \u0005[כל מקום שנופל צל הכתלים זה על זה],\u0006 שהכתלים סמוכים זה לזה — הרי זה \u0003ביבר קטן, ואידך\u0004 \u0005[והאחר]\u0006 שכתליו מרוחקים זה מזה ושטחו גדול יותר — נקרא \u0003ביבר גדול.\u0004","\u0003רבן שמעון בן גמליאל אומר לא כל הביברין שוין. אמר רב יוסף אמר רב יהודה אמר שמואל: הלכה כרבן שמעון בן גמליאל. אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרב יוסף: כיון שקובע אתה \u0003הלכה\u0004 — \u0003מכלל\u0004 הדברים אתה שומע \u0003דפליגי\u0004 \u0005[שחלוקים הם]\u0006 ורבן שמעון בן גמליאל לא לפרש את דברי קודמו בא, אלא לחלוק על דברי התנא הקודם!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף: \u0003ומאי נפקא לך מינה\u0004 \u0005[ומה יוצא לך מזה],\u0006 שכיון שפסקנו הלכה כרבן שמעון בן גמליאל, מה איכפת לך אם היתה מחלוקת בדבר? \u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי כפי הפתגם העממי שאומרים על מי שלומד ואינו מבין: \u0003גמרא גמור זמורתא תהא\u0004 \u0005[לימוד תלמד וזמר תהיה]?!\u0006 הרי עיקרו של הלימוד הוא להבין את טעמי הדברים, ואינו יוצא ידי חובה בחזרה בלבד. ולפיכך עלינו להבין את עקרונות דברי התנאים, אף שלהלכה אין הבדל בדבר.","עוד שנינו במשנה: \u0003זה הכלל כל המחוסר צידה\u0004 אסור לקחתו ביום טוב מן הביבר ושאינו מחוסר צידה — מותר. ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד הוא בדיוק]\u0006 \u0003מחוסר צידה? אמר רב יוסף אמר רב יהודה אמר שמואל: כל שאומר הבא מצודה\u0004 (מלכודת) \u0003ונצודנו,\u0004 שאי אפשר לתפוס אותו מיד בלי מלכודת.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: והא\u0004 \u0005[והרי]\u0006 \u0003אווזין ותרנגולין\u0004 שבחצר, \u0003שאומרים הבא מצודה ונצודנו\u0004 שהרי הם משוטטים ומשתמטים ממקום למקום, \u0003ותניא\u0004 \u0005[ו\u0006הרי \u0005שנויה\u0006 ברייתא\u0005];\u0006 \u0003הצד אווזין ותרנגולין ויוני הרדיסאות\u0004 (יוני בית) — \u0003פטור,\u0004 לפי שהם נחשבים כניצודים!","\u0003אמר רבה בר רב הונא אמר שמואל:\u0004 יש להבחין בין הדברים: \u0003הללו\u0004 אווזים ותרנגולים \u0003באין לכלובן לערב\u0004 והם חיים בקביעות שם ולכן נחשבים הם בכך כניצודים, \u0003והללו\u0004 שבביבר \u0003אין באין לכלובן בערב,\u0004 ולכן בורחים ומשתמטים מן האדם.","ומקשים: \u0003והרי יוני שובך ויוני עלייה,\u0004 ש\u0003באין לכלובן לערב, ותניא\u0004 \u0005[\u0006ובכל זאת \u0005שנויה\u0006 ברייתא\u0005]:\u0006 \u0003הצד יוני שובך ויוני עלייה\u0004 או \u0003צפרים שקננו בטפיחין בבירות\u0004 (בכרים, כעין שובכים שבתוך הבנינים) הרי הוא \u0003חייב\u0004 על צידתן, למרות שבאים לכלובן בערב!","\u0003אלא אמר רבה בר רב הונא אמר שמואל:\u0004 כך יש לחלק, \u0003הללו\u0004 האווזים והתרנגולים \u0003באין לכלובן לערב ומזונותן\u0004 מוטלים \u0003עליך\u0004 ולכן רגילים הם בבעליהם ונחשבים הם כניצודים, \u0003והללו\u0004 יוני שובך — \u0003באין\u0004 אכן \u0003לכלובן לערב,\u0004 אולם \u0003אין מזונותן עליך.\u0004","\u0003רב מרי אמר\u0004 הבדל אחר: \u0003הני עבידי לרבויי [אלה,\u0004 יוני שובך, \u0005עשויים לברוח]\u0006 מפני בני אדם \u0003והני לא עבידי לרבויי\u0004 \u0005[ואלה\u0006 אווזים ותרנגולים ויוני הרדיסאות \u0005אינם עשויים לברוח].\u0006 ותוהים: \u0003כולהו נמי עבידי לרבויי\u0004 \u0005[כולם גם כן עשויים לברוח]\u0006 שהרי גם תרנגולים בורחים כשרודפים אחריהם! ומשיבים: \u0003לכלובן קאמרינן דעבידי לרבויי\u0004 \u0005[לכלובם אמרו שעשויים לברוח]\u0006 כלומר, גם כשמגיעים לכלובם אף שם אינם עומדים במנוחה, ובורחים החוצה, ואינם נחשבים כניצודים ועומדים.","\u0003מצודות\u0004 (מלכודות) \u0003חיה ועוף ודגים שעשאן\u0004 (שהכינם ללכוד) \u0003מערב יום טוב\u0004 — \u0003לא יטול מהן\u0004 מה שנלכד או שמצא בהם \u0003ביום טוב, אלא אם כן יודע שנצודו\u0004 בעלי החיים שנמצאים שם כבר \u0003מערב יום טוב. ומעשה בגוי אחד שהביא דגים לרבן גמליאל, ואמר\u0004 רבן גמליאל: \u0003מותרין הן\u0004 הדגים, \u0003אלא שאין רצוני לקבל הימנו\u0004 משום ששונא אני אותו.","על המעשה ברבן גמליאל תוהים: וכי מביאים \u0003מעשה\u0004 כדי \u0003לסתור\u0004 את ההלכה שדובר בה קודם?! שהרי קודם אמרו שאין משתמשים במה שניצוד ביום טוב, וכאן מביאים מעשה שרבן גמליאל אומר שמותר! ומשיבים: \u0003חסורי מחסרא והכי קתני\u0004 \u0005[חסרה\u0006 המשנה \u0005וכך\u0006 יש \u0005לשנותה]:\u0006 גם \u0003ספק מוכן,\u0004 כשלא ברור אם ניצוד היום או אתמול — הרי זה \u0003אסור. ורבן גמליאל מתיר\u0004 במקרה של ספק. \u0003ומעשה נמי\u0004 \u0005[גם כן]\u0006 \u0003בגוי אחד שהביא דגים לרבן גמליאל, ואמר\u0004 רבן גמליאל: \u0003מותרין הן, אלא שאין רצוני לקבל הימנו.\u0004","\u0003אמר רב יהודה אמר שמואל: אין הלכה כרבן גמליאל. ואיכא דמתני לה אהא\u0004 \u0005[ויש ששונה\u0006 \u0005הזה על זו]\u0006 ששנויה בברייתא באותו ענין: \u0003ספק מוכן\u0004 מערב יום טוב, ספק אינו מוכן \u0003— רבן גמליאל מתיר ור' יהושע אוסר. אמר רב יהודה אמר שמואל: הלכה כר' יהושע. ואיכא דמתני לה אהא\u0004 \u0005[ויש ששונים אותו\u0006 את הדבר \u0005על זה],\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא אחרת\u0005]:\u0006"],["\u0003שוחטין מן\u0004 החיות והבהמות הנמצאות במקום סגור שיש בו \u0003נגרין\u0004 (תעלות מים לשתיה) \u0003ביום טוב, אבל לא מן\u0004 אלה שמצאן ביום טוב בתוך \u0003הרשתות\u0004 שעה כדי שילכדו בהן \u0003ו\u0004לא \u0003מן\u0004 אלה הנמצאות ב\u0003מכמורות,\u0004 שספק ניצודו מערב יום טוב, ספק ניצודו ביום טוב עצמו. \u0003ר' שמעון בן אלעזר אומר:\u0004 אם \u0003בא ומצאן\u0004 את המלכודות \u0003מקולקלין מערב יום טוב\u0004, וזהו הסימן לכך שנלכדה בהן חיה — \u0003בידוע שמערב יום טוב נצודו, ומותרין.\u0004 אולם אם בדק מערב יום טוב סמוך לכניסת החג והיו המלכודות שלימות ו\u0003בא ומצאן מקולקלין ביום טוב\u0004 — \u0003בידוע שביום טוב נצודו, ואסורין.\u0004","על הברייתא הזו שואלים: \u0003הא גופה קשיא\u0004 \u0005[היא עצמה קשה]\u0006 \u0003אמרת\u0004 בתחילה שאם, \u0003בא ומצאן מקולקלין מערב יום טוב\u0004 — \u0003בידוע שמערב יום טוב נצודו.\u0004 ונדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 ש\u0003בא ומצאן מקולקלין, הא ספיקא\u0004 \u0005[הרי אם ספק\u0006 בידו, ואינו ברור\u0005]\u0006 — אסורין. ומעתה \u0003אימא סיפא\u0004 \u0005[אמור את סופה\u0006 של אותה ברייתא\u0005]:\u0006 \u0003בא ומצאן מקולקלין ביום טוב\u0004 — \u0003בידוע שביום טוב נצודו. טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 ש\u0003בא ומצאן מקולקלין, הא ספיקא\u0004 \u0005[הרי\u0006 אם \u0005ספק\u0006 בדבר\u0005]\u0006 אומרים אנו ש\u0003מערב יום טוב נצודו, ומותרין.\u0004 אם כן יש סתירה בדיוק העולה משני חלקי המשנה!","ומסבירים, \u0003הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך התכוון לומר: \u0003בא ומצאן מקולקלין מערב יום טוב\u0004 — \u0003בידוע שמערב יום טוב נצודו ומותרין. הא ספיקא\u0004 \u0005[הרי\u0006 אם \u0005ספק\u0006 בדבר] \u0003נעשה כמי שנצודו ביום טוב ואסורין.\u0004","\u0003אמר רב יהודה אמר שמואל: הלכה כר' שמעון בן אלעזר,\u0004 ובעיקרו של דבר כל הלשונות מסכימות לאותה הלכה: שספק הכנה ביום טוב אסור.","שנינו במשנה שרבן גמליאל \u0003אמר\u0004 על הדגים שהביא לו אותו גוי ש\u0003מותרין הם.\u0004 ושואלים: \u0003מותרין למאי\u0004 \u0005[למה,\u0006 לאיזה ענין\u0005]?\u0006 \u0003רב אמר: מותרין לקבל\u0004 ולטלטל אותם, אבל לא באכילה. \u0003ולוי אמר: מותרין\u0004 אף \u0003באכילה.\u0004","\u0003אמר רב: לעולם אל ימנע אדם עצמו מבית המדרש אפילו שעה אחת.\u0004 וההוכחה לדבר מענין זה: \u0003דאנא\u0004 \u0005[שאני]\u0006 \u0003ולוי הוינן קמיה\u0004 \u0005[היינו לפני]\u0006 \u0003רבי כי אמרה להא שמעתא\u0004 \u0005[כאשר אמר אותה, את ההלכה הזאת],\u0006 \u0003באורתא\u0004 \u0005[בערב]\u0006 \u0003אמר\u0004 ופירש: \u0003מותרין באכילה, בצפרא\u0004 \u0005[בבוקר]\u0006 שלאחריו \u0003אמר: מותרין לקבל. אנא דהואי בי מדרשא\u0004 \u0005[אני שהייתי בבית המדרש]\u0006 גם בבוקר שלמחרת — \u0003הדרי בי\u0004 \u0005[חזרתי בי]\u0006 ואני אומר כשיטתו המאוחרת של רבי, \u0003לוי דלא הוה בי מדרשא\u0004 \u0005[שלא היה בבית המדרש]\u0006 \u0003לא הדר ביה\u0004 \u0005[חזר בו].\u0006","\u0003מיתיבי\u0004 \u0005[מקשים],\u0006 שנינו: \u0003גוי שהביא דורון\u0004 (מתנה) \u0003לישראל\u0004 ביום טוב, \u0003אפילו דגים המפולמין\u0004 (לחים) \u0003ופירות בני יומן\u0004 — \u0003מותרין. בשלמא למאן דאמר\u0004 \u0005[נניח\u0006 \u0005ל\u0006שיטת \u0005מי שאמר]\u0006 \u0003מותרין לקבל — שפיר\u0004 \u0005[יפה]\u0006 אפשר להבין את הדבר. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאמר]\u0006 \u0003מותרין באכילה, פירות בני יומן מי שרו\u0004 \u0005[האם מותרים הם]\u0006 \u0003באכילה?\u0004 שהרי כיון שנקטפו בו ביום מוקצים הם.","על הקושיה הזו עונים בקושיה שכנגד: \u0003ולטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005]\u0006 וכי \u0003פירות בני יומן מי שרו\u0004 \u0005[האם מותרים]\u0006 הם \u0003בטלטול?\u0004 ומדוע אם כן פשוט לך הדבר שלקבל מותר? \u0003אלא\u0004 על כרחך עליך לפרש \u0003בכוורי דאדימי, ופירי דכבישי בירקא עסקינן\u0004 \u0005[בדגים ש\u0006עדיין \u0005אדומים\u0006 זימיהם \u0005ופירות הכבושים בירק עוסקים אנו]\u0006 שאינם ממש בני יומם, \u0003ואמאי קרי להו\u0004 \u0005[ומדוע קורא להם]\u0006 \u0003בני יומן\u0004 — \u0003שהן\u0004 טריים ונראים \u0003כעין בני יומן\u0004 ובאופן כזה מותרים הם אף באכילה.","\u0003אמר רב פפא: הלכתא\u0004 \u0005[ההלכה]\u0006 לפסוק בענין זה היא: \u0003גוי שהביא דורון לישראל ביום טוב, אם יש מאותו המין\u0004 שהביא \u0003במחובר,\u0004 כלומר, דברים או פירות אלה שהביא כרגיל מחוברים לעץ או לקרקע — \u0003אסור,\u0004 שיש לשער שקטפם הגוי בו ביום. \u0003ולערב\u0004 (למוצאי יום טוב) \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003אסורין\u0004 במשך הזמן \u0003בכדי שיעשו,\u0004 כלומר: במשך הזמן שאפשר יהיה לעשות בו מלאכה זו של קטיפתם וניתוקם ממקום חיבורם, כי אסור ליהנות ממלאכה שנעשתה עבור ישראל ביום טוב.","\u0003ואם אין מאותו המין במחובר,\u0004 אם הביא את הדברים \u0003תוך התחום\u0004 — \u0003מותר,\u0004 שלא נעשתה בכך כל מלאכת איסור,"],["אולם אם הביאם מ\u0003חוץ לתחום\u0004 שנעשה בו מלאכה של הוצאה מחוץ לתחום — \u0003אסור. והבא\u0004 מחוץ לתחום \u0003בשביל ישראל זה\u0004 — \u0003מותר לישראל אחר,\u0004 שכיון שלא נתקיימה מחשבתו של הגוי — לא חל האיסור על המקבל השני, שדין תחומים הוא מדברי סופרים ולא גזרו אלא על זה שהביא הגוי לשמו, ולא על השני.","ועוד מענין צייד ביום טוב. \u0003אמר רבה בר רב הונא אמר רב: הסוכר\u0004 (הסותם) \u0003אמת\u0004 (תעלת) \u0003המים\u0004 המובילה מים מן הנהר להשקות את השדה, אם סכרה \u0003מערב יום טוב ולמחר השכים ומצא בה דגים\u0004 — \u0003מותרין,\u0004 שהרי דגים אלה באו עם המים מערב החג ולא יכלו לצאת כיון שהתעלה היתה סכורה, והרי הם נחשבים כמוכנים מערב החג.","\u0003אמר רב חסדא: מדברי רבינו\u0004 (רב) אלה \u0003נלמוד: חיה שקננה בפרדס\u0004 הסמוך לביתו של אדם \u0003אינה צריכה זמון\u0004 מיוחד, והרי היא נחשבת כמוכנה. \u0003אמר רב נחמן\u0004 על מסקנה זו: \u0003נפל חברין\u0004 \u0005[חברנו],\u0006 רב חסדא, \u0003ברברבתא\u0004 \u0005[ב\u0006דבר \u0005גדול],\u0006 כלומר, בענין שאיננו פשוט כלל, ושיש בו כמה מחלוקות. \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 בלשון שונה קצת, ש\u0003אמר רבה בר רב הונא, מדברי רבינו נלמוד: חיה שקננה בפרדס אינה צריכה זמון.\u0004 ועל כן \u0003אמר רב נחמן: נפל\u0004 רבה \u0003בר חברין\u0004 \u0005[בן חברנו]\u0006 רב הונא, \u0003ברברבתא\u0004 \u0005[ב\u0006דבר \u0005גדול]\u0006 כי רב הונא היה כבן גילו של רב נחמן ושניהם מתלמידי רב היו, ולכך קרא לו חבר, ולבנו רבה קרא בן חבר.","ומסביר את ההבדל: \u0003התם\u0004 \u0005[שם]\u0006 בחיה שקננה בפרדס \u0003לא קא עביד\u0004 \u0005[אינו עושה]\u0006 \u0003מעשה\u0004 כלל, אלא החיה מעצמה באה, ואילו \u0003הכא\u0004 \u0005[כאן]\u0006 בסוכר אמת המים \u0003קא עביד\u0004 \u0005[הוא עושה]\u0006 \u0003מעשה\u0004 בידיו, בכך שסוכר את המים.","והוא מסיים את הקושיה, \u0003ולא בעיא\u0004 \u0005[וכי אינה צריכה]\u0006 \u0003זמון\u0004 נוסף, \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 במפורש בברייתא\u0005]:\u0006 \u0003חיה שקננה בפרדס\u0004 — \u0003צריכה לזמן, וצפור דרור\u0004 — \u0003צריך לקשור בכנפיה כדי שלא תתחלף באמה\u0004 שמא יקח צפור דרור אחרת, כגון אמה, במקומה. \u0003וזו\u0004 היא \u0003עדות שהעידו מפי שמעיה ואבטליון.\u0004 ומעירים: אכן, \u0003תיובתא\u0004 \u0005[קושיה חמורה\u0006 היא\u0005]\u0006 על החכמים שהוציאו מסקנה זו מדברי רב.","ושואלים: ולגוף הענין, \u0003ומי בעיא זמון\u0004 \u0005[והאם צריכה\u0006 חיה שבפרדס \u0005זימון]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 \u0003אמר ר' שמעון בן אלעזר: מודים בית שמאי ובית הלל\u0004 על יונים וכיוצא בהן \u0003שהזמינן\u0004 מערב יום טוב כשהיו \u0003בתוך הקן ומצא\u0004 אותם בחג עצמו כשהן \u0003לפני הקן\u0004 — \u0003ש\u0004הם \u0003אסורין,\u0004 שיש לחשוש שמא אין אלו אותן יונים שהזמינן אלא אחרות שבאו מבחוץ. \u0003במה דברים אמורים\u0004 — \u0003ביוני שובך, ויוני עליה, וצפרים שקננו בטפיחין\u0004 (בכרים, כעין שובכים שבתוך הבנינים) \u0003ובבירה\u0004 (בתוך הבנין). \u0003אבל אווזין ותרנגולים ויוני הרדסיאות\u0004 (יוני בית) \u0003וחיה שקננה בפרדס\u0004 — \u0003מותרין\u0004 בכל מקרה, \u0003ואין צריכין זמון\u0004 מראש, \u0003וצפור דרור צריכה לקשר בכנפיה, כדי שלא תתחלף באמה.\u0004","\u0003והמקושרים\u0004 בכנפיהם על יד אדם כסימן \u0003והמנוענעין\u0004 מראש כזימון לצורך החג, שהיו \u0003בבורות בבתים ובשיחין\u0004 (בורות מאורכים) \u0003ובמערות,\u0004 אלה — \u0003מותרין\u0004 ביום טוב, ואם היו \u0003באילנות\u0004 — \u0003אסורין.\u0004 והטעם מחשש איסור אחר: \u0003שמא יעלה\u0004 באילן \u0003ויתלוש\u0004 ממנו. \u0003והמקושרין והמנוענעין בכל מקום אסורין משום גזל.\u0004 שבקשירה או נענוע אלו זכה בהם גם לענין קנין ואסור לאחר לקחתו ממנו. ומכל מקום למדנו כאן שחיה בפרדס אינה צריכה זימון!","\u0003אמר רב נחמן: לא קשיא\u0004 \u0005[אין זה קשה];\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שמותר בלי זימון הוא \u0003בה\u0004 בחיה צעירה שאינה יכולה לברוח, \u0003הא\u0004 \u0005[זה]\u0006 שאסור ללא זימון, מדובר \u0003באמה\u0004 שיכולה לברוח. ותוהים: וכי \u0003אמה בזמון סגי\u0004 \u0005[די]\u0006 \u0003לה?\u0004 הלא \u0003צידה מעליותא\u0004 \u0005[מעולה,\u0006 גמורה\u0005]\u0006 \u0003בעיא\u0004 \u0005[צריכה\u0006 היא\u0005]\u0006 כדי לתופסה, שהרי חית בר היא!","\u0003אלא אמר רב נחמן בר יצחק: אידי ואידי בדידה\u0004 \u0005[זה וזה\u0006 מדובר \u0005בה],\u0006 כלומר, בצעירה שאינה יכולה לברוח. ויש לחלק כך: \u0003הא\u0004 \u0005[זה]\u0006 שמותר בלא זימון, הוא \u0003בגנה הסמוכה לעיר,\u0004 שהוא יודע בבירור את המקום המדוייק בו נמצאת החיה ויכול לקחתה בכל עת, ולכן אינה צריכה זימון מיוחד, \u0003הא\u0004 \u0005[זו]\u0006 שצריכה זימון — \u0003בגנה שאינה סמוכה.\u0004","\u0003בהמה מסוכנת\u0004 שיש חשש שמא תמות ותהיה נבילה, ורוצה להקדים ולשחוט אותה שמא תימצא כשירה לאכילה ולא יפסיד בה — \u0003לא ישחוט\u0004 ביום טוב, \u0003אלא אם כן יש\u0004 עדיין \u0003שהות\u0004 בו \u0003ביום\u0004 כדי \u0003לאכול ממנה כזית צלי,\u0004 שבאופן כזה אפשר לומר ששוחטה לצורך יום טוב. \u0003ר' עקיבא אומר:\u0004 אין צורך בכדי זמן שיוכל לצלות, אלא \u0003אפילו\u0004 לאכול \u0003כזית\u0004 בשר \u0003חי מבית טביחתה\u0004 (ממקום שחיטתה), שאינו צריך להוסיף לטרוח לא בהפשטה ולא בצלייה.","וכל בהמה אשר \u0003שחטה בשדה\u0004 — \u0003לא יביאנה\u0004 לביתו \u0003במוט ובמוטה\u0004 (מערכת מוטות) בשני בני אדם, שנראה הדבר כדרך חול, \u0003אבל\u0004 עושה שינוי \u0003ומביא בידו אברים אברים.\u0004","\u0003אמר רמי בר אבא:\u0004 מצוות \u0003הפשט ונתוח\u0004 כתובה בתורה \u0003בעולה, והוא הדין לקצבים,\u0004 כלומר, מכאן יש לקצבים ללמוד שצריכים להפשיט את העור ולנתח תחילה את הבהמה לנתחיה, ו\u0003מכאן למדה תורה דרך ארץ: שלא יאכל אדם בשר קודם הפשט ונתוח.\u0004","ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו]\u0006 בכך, איזה חידוש הלכה יש בענין זה? \u0003אילימא לאפוקי\u0004 \u0005[אם תאמר\u0006 שהוא רוצה \u0005להוציא]\u0006 מדברי \u0003רב הונא,\u0004 ש\u0003אמר רב הונא: בהמה בחייה\u0004 — \u0003בחזקת איסור\u0004 אבר מן החי היא \u0003עומדת, עד שיודע לך במה נשחטה,\u0004 וכל עוד לא נתברר שנשחטה כדין — הרי היא נשארת בחזקת איסור, ואסורה.","ואילו בהמה ש\u0003נשחטה\u0004 כדין — \u0003בחזקת היתר\u0004 היא \u0003עומדת, עד שיודע לך במה נטרפה,\u0004 ואין צורך בבדיקה מיוחדת לדעת אם יש בבהמה פגם או טריפה, שחזקתה שהיא כשרה ואף אם נמצא בה פגם כלשהו — אינה נטרפת בכך, שיש לומר שהדבר אירע לאחר שחיטתה.","ומדברי רמי בר אבא אפשר היה להבין כי הוא דורש שבכל זאת תיבדק הבהמה, אולם, \u0003והאנן תנן מתניתין\u0004 \u0005[והרי אנו שנינו במשנתנו]\u0006 \u0003כ\u0004שיטת \u0003רב הונא! דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בה\u0005]\u0006 \u0003ר' עקיבא אומר: אפילו כזית חי מבית טביחתה.\u0004 משמע שאין צורך לפשוט את עורה או לבדקה, ונוטל מיד ואוכל! \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה \u0003מבית טביחתה ממש\u0004 וקודם הפשט!","ודוחים: \u0003לא,\u0004 אפשר לפרש: \u0003ממקום שטובחת\u0004 \u0005[מבשלת]\u0006 \u0003אכילתה\u0004 כלומר מבני מעיים שלה, ועדיין יתכן לומר שצריך להפשיט את העור טרם אכילה.","אולם \u0003והא תני\u0004 \u0005[והרי שנה]\u0006 \u0003ר' חייא: מקום טביחתה ממש. אלא\u0004 יש לדחות מה שפירשנו, ולומר כי \u0003רמי בר אבא\u0004"],["\u0003אורח ארעא קא משמע לן\u0004 \u0005[דרך ארץ השמיע לנו],\u0006 ולא שיש צד איסור בדבר, אלא למדנו מה מנהג דרך ארץ הראוי.","\u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]\u0006 שלימדונו חכמים מנהגי דרך ארץ, שאין בהם צד איסור והיתר. שאמרו: \u0003לא יאכל אדם שום ובצל מ\u0004צד \u0003ראשו\u0004 (שורשיו) \u0003אלא מ\u0004צד \u0003עליו. ואם אכל\u0004 מצד ראשו — \u0003הרי זה\u0004 נראה \u0003רעבתן. כיוצא בו: לא ישתה אדם כוסו\u0004 של יין \u0003בבת אחת, ואם שתה\u0004 — \u0003הרי זה גרגרן\u0004 (זללן, סובא). \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בענין זה: \u0003השותה כוסו בבת אחת\u0004 — \u0003הרי זה גרגרן,\u0004 שותה כוסו ב\u0003שנים\u0004 (בשתי גמיעות) — הרי זה מנהג \u0003דרך ארץ,\u0004 שותה ב\u0003שלשה\u0004 (בשלוש גמיעות) — הרי זה \u0003מגסי הרוח,\u0004 שמראה בעצמו עידון ופינוק יותר מדי.","\u0003ו\u0004אגב כך מביאים עוד ממה ש\u0003אמר רמי בר אבא: חצובא\u0004 \u0005[החצב]\u0006 ששורשיו יורדים לעומק — \u0003מקטע רגליהון דרשיעיא\u0004 \u0005[מקצץ רגליהם של הרשעים]\u0006 ביום הדין העתיד להיות, כי היו נוטעים חצב בגבולות השדות, שמטבע שורשיו לחדור לעומק הקרקע, אבל אינם מתפשטים לצדדים, ועל מסיג הגבול היה ללמוד מהם.","ה\u0003נטיעה\u0004 — \u0003מקטע רגליהון דקצביא ובועלי נדות\u0004 \u0005[קוצצת רגליהם של הקצבים ושל בועלי נדות],\u0006 כי בכל נטיעה צריך להמתין שלוש שנים עד שיהיו פירותיה ראויים לאכילה, ומכאן מוסר לקצבים שממהרים לאכול קודם הפשטת העור, ובועלי נדות שאינם ממתינים עד שתטהר האשה.","ואילו \u0003תורמוסא\u0004 \u0005[התורמוס]\u0006 שהוא מין קיטנית מר מאד ואינו ראוי למאכל אלא לאחר תהליך ממושך בו הוא מתבשל שבע פעמים ולבסוף אוכלים אותו כפרפראות, הוא \u0003מקטע רגליהון דשנאיהון\u0004 \u0005[מקצץ רגליהם של השונאים]\u0006 \u0003של ישראל,\u0004 כלומר, בלשון נקיה — ישראל. \u0003שנאמר: \"ויסיפו בני ישראל לעשות הרע בעיני ה' ויעבדו את הבעלים ואת העשתרות ואת אלהי ארם ואת אלהי צידון ואת אלהי מואב ואת אלהי בני עמון ואת אלהי פלשתים ויעזבו את ה' ולא עבדוהו\"\u0004 (שופטים י, ו).","\u0003ממשמע שנאמר \"ויעזבו את ה'\" איני יודע שלא עבדוהו?! ומה תלמוד לומר\u0004 בתוספת המילים \u0003\"ולא עבדוהו\"\u0004 — \u0003אמר ר' אלעזר, אמר הקדוש ברוך הוא: אפילו כתורמוס הזה, ש\u0004על אף שאינו ראוי לאכילה כפי שהוא, וכדי להכשירו לאכילה \u0003שולקין\u0004 (מבשלים אותו במים) \u0003שבע פעמים\u0004 להפיג את מרירותו, וכתוצאה מכך לבסוף הוא נעשה מתוק עד ש\u0003אוכלין אותו בקנוח סעודה, לא עשאוני בני.\u0004 שעבדו את כל שבעת סוגי העבודה זרה המוזכרים בפסוק ואף לאחר שהטריחוני להענישם על כל אחת מהן, לא חזרו מדרכם הרעה ועדיין הם בכלל \"ולא עבדוהו\", שעדיין עומדים הם במריים.","על צד אחר באופיים של ישראל הנובע מאותם מקורות \u0003תנא משמיה\u0004 \u0005[שנה\u0006 החכם \u0005משמו]\u0006 של \u0003ר' מאיר: מפני מה נתנה תורה לישראל\u0004 — \u0003מפני שהן עזין\u0004 (חצופים ומעיזי פנים) והעיסוק בתורה יתיש אותם ויכניע את ליבם. \u0003תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל\u0004 על הנאמר: \u0003\"מימינו אש דת למו\"\u0004 (דברים לג, ב). \u0003אמר הקדוש ברוך הוא:\u0004 לפי אופיים וטבעם \u0003ראויים הללו,\u0004 ישראל, \u0003שתנתן להם דת אש\u0004 — אמונה קשה ולוהטת. \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 בלשון אחרת: \u0003דתיהם\u0004 (מנהגם וטבעם) \u0003של אלו\u0004 ישראל — \u0003אש\u0004 הם. \u0003שאלמלא לא נתנה תורה לישראל\u0004 שהעיסוק בה וקיומה מרסנים אותם \u0003אין כל אומה ולשון יכולים לעמוד בפניהם.\u0004","\u0003והיינו\u0004 (וזה הוא) ש\u0003אמר ר' שמעון בן לקיש: שלשה עזין הן: ישראל\u0004 בין ה\u0003אומות, כלב בחיות, תרנגול בעופות. ויש אומרים: אף עז בבהמה דקה. ויש אומרים: אף צלף באילנות.\u0004","שנינו במשנה: \u0003שחטה בשדה לא יביאנה במוט. תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אין הסומא יוצא\u0004 ביום טוב \u0003במקלו, ולא הרועה בתרמילו. ואין יוצאין בכסא\u0004 שטוענים בו בני אדם ומעבירים אותם בו — \u0003אחד האיש ואחד האשה.\u0004 שכל אלה יש בהם משום דרך חול, ויש בכך כעין זלזול בכבוד החג.","ותוהים: \u0003איני\u0004 \u0005[האם כן הוא]?!\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003שלח ר' יעקב בר אידי\u0004 הלכה זו מארץ ישראל: \u0003זקן\u0004 (חכם) \u0003אחד היה בשכונתינו והיה יוצא\u0004 ביום טוב \u0003בגלודקי\u0004 (מין כסא לנשיאה) \u0003שלו, ובאו ושאלו את ר' יהושע בן לוי\u0004 גדול הדור, אם הדבר מותר. \u0003ואמר\u0004 להם ר' יהושע בן לוי: \u0003אם רבים צריכים לו\u0004 לאותו זקן שיבוא לדרוש בפניהם בתורה — \u0003מותר\u0004 להוציאו על גבי כסא זה ולהביאו לבית המדרש.","וכן \u0003סמכו רבותינו על דברי אחי שקיא,\u0004 ש\u0003אמר: אנא אפיקתיה\u0004 \u0005[אני הוצאתיו]\u0006 ביום טוב את \u0003רב הונא מ\u0004העיירה \u0003היני ל\u0004עיירה \u0003שילי ומשילי להיני\u0004 בכסא כזה. \u0003ואמר רב נחמן בר יצחק: אנא אפיקתיה\u0004 \u0005[אני הוצאתי]\u0006 ביום טוב בכסא כזה את \u0003מר שמואל משמשא לטולא ומטולא לשמשא\u0004 \u0005[משמש לצל ומצל לשמש],\u0006 אם כן מוכח שמותר לצאת בכסא! ומשיבים: משם אין קושיה, \u0003התם כדאמר טעמא\u0004 \u0005[שם כפי שאמר את הטעם]\u0006 להיתר: ש\u0003אם היו רבים צריכים לו\u0004 — \u0003מותר.\u0004 אבל מי שאין נזקקים לו הרבים — לא יצא.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן לחמא בר אדא שליח ציון,\u0004 שהיה שליח ישיבות ארץ ישראל, והיה בא מארץ ישראל לבבל וחוזר שוב: \u0003כי סלקת להתם\u0004 \u0005[כאשר אתה עולה לשם,\u0006 לארץ ישראל\u0005]\u0006 \u0003אקיף וזיל אסולמא דצור\u0004 \u0005[הקף ולך דרך סולמה של צור]\u0006 \u0003וזיל לגבי\u0004 \u0005[ולך אצל]\u0006 \u0003ר' יעקב בר אידי\u0004 המתגורר בצור \u0003ובעי מיניה\u0004 \u0005[ושאל אותו]:\u0006 \u0003כסא, מה אתון ביה\u0004 \u0005[מה אתם בו],\u0006 כלומר, מה פסק ההלכה שלכם בענין זה, האם מותר להוציאו?","\u0003אדאזל להתם נח נפשיה\u0004 \u0005[עד שהלך לשם נחה נפשו,\u0006 נפטר\u0005]\u0006 \u0003ר' יעקב בר אידי.\u0004 אולם \u0003כי סליק אשכחיה\u0004 \u0005[כאשר עלה\u0006 לארץ ישראל \u0005מצא]\u0006 את \u0003ר' זריקא, אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כסא מה אתון ביה\u0004 \u0005[מה אתם בו],\u0006 מה דעתכם בענין זה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר ר' אמי: ובלבד שלא יכתף.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003ובלבד שלא יכתף? אמר רב יוסף בריה\u0004 \u0005[בנו]\u0006 של \u0003רבה: באלונקי\u0004 \u0005[באלונקה]\u0006 שנושאים אדם על הכתפים, והדבר בולט מאד, ונראה כמעשה חול וכזלזול בכבוד וקדושת החג. אלא יחזיקו את רגלי הכסא בידיהם, שאינו גבוה וניכר כל כך.","ושואלים: \u0003איני\u0004 \u0005[וכי כך הוא]?!\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רב נחמן שרא\u0004 \u0005[התיר]\u0006 \u0003לה לילתא\u0004 אשתו \u0003למיפק אאלונקי\u0004 \u0005[לצאת על גבי אלונקה]!\u0006 ומשיבים: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003ילתא דבעיתא\u0004 \u0005[שהיתה מפחדת]\u0006 שמא תפול, ולכן היתה צריכה סידור מיוחד זה.","מספרים: \u0003אמימר ומר זוטרא מכתפי להו בשבתא דרגלא\u0004 \u0005[היו מכתפים אותם\u0006 התלמידים על כתפיהם \u0005בשבת הרגל]\u0006 שהיו הולכים לדרוש \u0003משום ביעתותא\u0004 \u0005[פחד\u0006 הנפילה\u0005],\u0006 \u0003ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שהטעם היה \u0003משום דוחקא דצבורא\u0004 \u0005[דוחק הצבור],\u0006 \u0003שחששו שלא ינזקו החכמים מדוחק הקהל.\u0004","\u0003בכור\u0004 בהמה טהורה בזמן הזה \u0003שנפל לבור\u0004 ביום טוב וחוששים שימות שם. ובזר אינו נשחט אלא כאשר נפל בו מום. \u0003ר' יהודה אומר: ירד מומחה\u0004 לענין זה לבור, \u0003ויראה\u0004"]]};
